                <h3>Как работает майнинг</h3>

                <p>При майнинге вычислительное устройство получает набор данных, связанных с создаваемым блоком, и многократно выполняет вычисления, изменяя определённое значение до тех пор, пока результат не будет соответствовать требованиям протокола. В Proof-of-Work такая работа должна иметь проверяемую вычислительную стоимость, но сама проверка найденного решения выполняется значительно проще.</p>

