                <h3>Оборудование для майнинга</h3>

                <p>Для майнинга используются вычислительные устройства, способные эффективно выполнять конкретный алгоритм сети. В зависимости от блокчейна это могут быть специализированные ASIC-майнеры, графические процессоры или центральные процессоры. Устройство, непосредственно выполняющее вычислительную работу, обычно называют <span class="term" data-term="mining/miner">майнером</span>.</p>

                <p>Эффективность оборудования определяется не только его вычислительной мощностью. Для практической оценки важны энергопотребление, стоимость электроэнергии, стабильность работы, эффективность охлаждения, стоимость самого оборудования и текущие параметры сети.</p>

                <h3>Способы организации майнинга</h3>

                <p>Майнинг может выполняться самостоятельно или совместно с другими участниками. При <span class="term" data-term="mining/solo-mining">соло-майнинге</span> участник самостоятельно ищет блок и в случае успеха получает предусмотренное протоколом вознаграждение. При <span class="term" data-term="mining/pooled-mining">Pooled майнинг</span> вычислительные ресурсы нескольких участников объединяются через майнинговый пул, а выплаты распределяются между ними в соответствии с правилами пула.</p>

                <p>Существуют и другие способы организации вычислительной работы. Например, <span class="term" data-term="mining/merge-mining">Merge майнинг</span> позволяет использовать одну вычислительную работу для участия в нескольких совместимых блокчейнах, а <span class="term" data-term="mining/dual-mining">Dual майнинг</span> может использовать одно устройство для одновременной добычи двух криптовалют.</p>

                <h3>Что влияет на доходность майнинга</h3>

                <p>Экономика майнинга определяется соотношением получаемого вознаграждения и затрат на эксплуатацию оборудования. К основным факторам относятся:</p>

                <ul>
