                <p>Изменение любого из этих параметров может заметно повлиять на прибыльность. Например, рост сложности сети при неизменных остальных условиях уменьшает ожидаемую долю вознаграждения, приходящуюся на единицу вычислительной мощности.</p>

                <h3>Вознаграждение майнера</h3>

                <p>В зависимости от правил конкретной сети <span class="term" data-term="mining/block-reward">вознаграждение за блок</span> может включать несколько компонентов. Один из них — <span class="term" data-term="mining/block-subsidy">субсидия блока</span>, связанная с выпуском новых монет. Другой компонент — комиссии за транзакции, включённые в созданный блок.</p>

                <p>Информация о выплате вознаграждения оформляется через специальную <span class="term" data-term="mining/coinbase-transaction">Coinbase Transaction</span>. Правила формирования такой транзакции и допустимый размер выплаты определяются протоколом конкретного блокчейна.</p>

