                <h3>Как работает Proof-of-Work</h3>

                <p>При формировании блока необходимо найти такое значение, чтобы результат криптографического хеширования соответствовал установленному протоколом условию. Поскольку предсказать подходящее значение заранее практически невозможно, участнику приходится выполнять большое количество попыток.</p>

                <p>Каждая отдельная попытка относительно проста, однако поиск подходящего результата требует значительного количества вычислений. После нахождения решения остальные участники могут быстро проверить его корректность.</p>

                <h3>Роль сложности сети</h3>

                <p>Сеть регулирует требуемую сложность вычислительной задачи таким образом, чтобы новые блоки появлялись с заданной протоколом частотой. Если совокупная вычислительная мощность сети увеличивается, сложность в сетях с механизмом автоматической корректировки также может увеличиваться.</p>

                <p>Таким образом, изменение вычислительной мощности отдельных майнеров и всей сети связано с изменением вероятности нахождения блока конкретным участником.</p>

                <h3>Безопасность сети</h3>

                <p>Одно из ключевых свойств Proof-of-Work заключается в том, что создание альтернативной истории блокчейна требует значительных вычислительных затрат. Чем больше вычислительной работы накоплено в цепочке, тем дороже становится попытка переписать её историю.</p>

                <p>Экономическая модель дополнительно стимулирует честное участие: майнер расходует электроэнергию и использует оборудование, рассчитывая получить <span class="term" data-term="mining/block-reward">вознаграждение за блок</span>. Атака на сеть требует не только вычислительных ресурсов, но и соответствующих затрат на их эксплуатацию.</p>

