                <h3>Зачем объединять мощности</h3>

                <p>Вероятность того, что отдельный небольшой майнер самостоятельно найдёт блок, может быть очень низкой. Объединение большого количества устройств увеличивает суммарную вычислительную мощность и, следовательно, частоту нахождения блоков всей группой.</p>

