                <h3>Как формируется субсидия</h3>

                <p>Размер субсидии задаётся протоколом. Она не определяется непосредственно майнером и не зависит от его вычислительной мощности. Если майнер успешно создаёт блок, он может получить только ту субсидию, которая предусмотрена правилами сети на данный момент.</p>

