                <h3>Влияние на экономику майнинга</h3>

                <p>Изменение субсидии может существенно повлиять на доходность оборудования. Если субсидия уменьшается, майнер получает меньше новых монет за блок при прочих равных условиях.</p>

                <p>При этом влияние снижения субсидии может частично компенсироваться ростом комиссий транзакций, изменением курса актива или изменением конкуренции в сети. Поэтому оценивать доходность необходимо по совокупному <span class="term" data-term="mining/block-reward">вознаграждению за блок</span>, а не только по размеру субсидии.</p>',
            ],

            'coinbase-transaction' => [
                'title' => 'Что такое Coinbase Transaction | TM Wiki',
                'description' => 'Coinbase Transaction — специальная транзакция блока, через которую оформляется субсидия и комиссии в пользу майнера.',
                'name' => 'Coinbase Transaction',
                'caption' => 'Специальная транзакция, создаваемая при формировании блока для получения предусмотренного протоколом вознаграждения.',
                'definition' => '<p><strong>Coinbase Transaction</strong> — специальная транзакция, создаваемая при формировании нового блока для оформления выплаты в пользу создателя блока. Несмотря на название, она не связана с обычным переводом средств между двумя пользователями.</p>

                <h3>Особенности Coinbase Transaction</h3>

                <p>Coinbase Transaction создаётся самим участником, формирующим блок, а не отправляется пользователем сети. Она может содержать сумму, соответствующую <span class="term" data-term="mining/block-subsidy">субсидии блока</span>, а также допустимую протоколом часть комиссий транзакций.</p>

                <p>Такая транзакция обычно является первой транзакцией блока. Её структура и правила формирования зависят от конкретного блокчейна.</p>

                <h3>Связь с вознаграждением</h3>

                <p>Основная функция Coinbase Transaction — оформить <span class="term" data-term="mining/block-reward">вознаграждение за блок</span>. Если блок содержит некорректную сумму или нарушает правила протокола, он может быть отклонён сетью.</p>

                <p>Поэтому максимальный размер выплаты не является произвольным. Майнер не может просто указать любую желаемую сумму: допустимые значения определяются правилами блокчейна.</p>

                <h3>Отличие от обычной транзакции</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Характеристика</th>
                            <th>Coinbase Transaction</th>
                            <th>Обычная транзакция</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Создатель</td>
                            <td>Участник, формирующий блок</td>
                            <td>Пользователь сети</td>
                        </tr>
                        <tr>
                            <td>Назначение</td>
                            <td>Оформление награды и связанных выплат</td>
                            <td>Перевод активов</td>
                        </tr>
                        <tr>
                            <td>Расположение в блоке</td>
                            <td>Как правило, первая транзакция</td>
                            <td>Любая допустимая позиция</td>
                        </tr>
                    </tbody>
                </table>

                <p>Coinbase Transaction является важной частью механизма экономического стимулирования <span class="term" data-term="mining/mining">майнинга</span>, поскольку именно через неё протокол оформляет выплату участнику, создавшему новый блок.</p>',
            ],
