                'definition' => '<p><strong>ASIC</strong> (Application-Specific Integrated Circuit) — специализированная интегральная схема, разработанная для выполнения конкретного типа вычислений. В криптовалютном майнинге ASIC применяются для алгоритмов, под которые аппаратно оптимизированы их вычислительные схемы.</p>

                <p>В отличие от универсальных процессоров и графических процессоров, ASIC не предназначен для широкого спектра задач. Его архитектура оптимизируется под конкретный алгоритм, поэтому устройство может обеспечивать высокую производительность при сравнительно низком энергопотреблении на единицу вычислительной мощности.</p>

                <h3>Как ASIC используется в майнинге</h3>

                <p>В <span class="term" data-term="mining/mining">майнинге</span> ASIC выполняет вычисления, необходимые для участия сети в процессе подтверждения блоков. Например, ASIC для SHA-256 оптимизирован для вычислений этого алгоритма и не является универсальным устройством для произвольных алгоритмов.</p>

                <p>Практические характеристики ASIC оценивают с учётом <span class="term" data-term="equipment-specifications/hashrate">хешрейта</span>, <span class="term" data-term="equipment-specifications/power-consumption">потребления электроэнергии</span> и <span class="term" data-term="equipment-specifications/power-efficiency">энергоэффективности</span>.</p>

                <h3>Основные особенности</h3>
                <ul>
