                <li>ограниченная применимость за пределами исходного алгоритма;</li>
                <li>необходимость эффективного отвода тепла при высокой нагрузке.</li>
                </ul>

                <p>ASIC является основой большинства современных специализированных устройств для майнинга алгоритмов, для которых существует развитая специализированная аппаратная база.</p>'
