                </ul>

                <p>Экономический результат эксплуатации ASIC-майнера зависит не только от характеристик самого устройства, но и от курса добываемой криптовалюты, сложности сети, вознаграждения за блок, комиссии пула и стоимости электроэнергии.</p>

                <p>Для постоянной эксплуатации несколько ASIC-майнеров обычно рассматриваются как часть майнинговой установки или более крупной <span class="term" data-term="mining-infrastructure/mining-farm">майнинговой фермы</span>.</p>'
