                'definition' => '<p><strong>Плата управления</strong> (control board) — электронный контроллер майнингового устройства, который координирует работу вычислительных плат и других компонентов. В ASIC-майнере она обычно взаимодействует с хешбордами, системой охлаждения, сетевым интерфейсом и программным обеспечением.</p>

