                'caption' => 'Количество вычислений хеш-функции, которое оборудование способно выполнять за единицу времени.',
                'definition' => '<p><strong>Хешрейт</strong> (hashrate) — показатель вычислительной производительности оборудования или сети, выраженный количеством хешей, вычисляемых за единицу времени. В <span class="term" data-term="mining/mining">майнинге</span> хешрейт характеризует скорость, с которой оборудование выполняет вычисления для используемого алгоритма.</p>

                <p>Единицей измерения является хеш в секунду (H/s). Для современного оборудования обычно используются производные единицы: KH/s, MH/s, GH/s, TH/s, PH/s и EH/s. Например, 1 TH/s означает один триллион вычислений в секунду.</p>

                <h3>Хешрейт оборудования</h3>

                <p>Номинальный хешрейт зависит от типа оборудования, используемого алгоритма и режима работы. Для <span class="term" data-term="mining-equipment/asic-miner">ASIC-майнера</span> производительность обычно указывается в TH/s или PH/s, тогда как для <span class="term" data-term="mining-equipment/gpu-rig">GPU-майнера</span> единица измерения зависит от алгоритма и может выражаться в MH/s или GH/s.</p>

                <p>Фактический хешрейт может отличаться от заявленного производителем. На него влияют <span class="term" data-term="equipment-specifications/clock-frequency">частота работы</span>, настройки оборудования, температура, <span class="term" data-term="equipment-specifications/power-limit">лимит мощности</span>, <span class="term" data-term="equipment-specifications/thermal-throttling">термальный троттлинг</span>, стабильность питания и количество <span class="term" data-term="equipment-specifications/hardware-error">аппаратных ошибок</span>.</p>

                <h3>Хешрейт и энергоэффективность</h3>

                <p>Сам по себе высокий хешрейт не определяет эффективность оборудования. Для экономической оценки его рассматривают вместе с <span class="term" data-term="equipment-specifications/power-consumption">потреблением электроэнергии</span> и <span class="term" data-term="equipment-specifications/power-efficiency">энергоэффективностью</span>.</p>

                <h3>Хешрейт сети</h3>

                <p>В сетях с <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> также используется понятие суммарного хешрейта сети. Он отражает совокупную вычислительную мощность майнеров, участвующих в поддержании сети. Изменение сетевого хешрейта влияет на распределение вычислительной конкуренции между участниками и связано с механизмом изменения <span class="term" data-term="blockchain/consensus-mechanism">механизма консенсуса</span> и сложности майнинга.</p>'
