                'name' => 'Потребление электроэнергии',
                'caption' => 'Количество электрической мощности, потребляемой майнинговым оборудованием при работе.',
                'definition' => '<p><strong>Потребление электроэнергии</strong> — количество электрической мощности, которое оборудование использует во время работы. Для майнинга этот показатель обычно выражается в ваттах (W) или киловаттах (kW) и является одним из ключевых параметров при расчёте эксплуатационных расходов.</p>

                <p>Потребляемая мощность зависит от конструкции устройства, режима работы, нагрузки, <span class="term" data-term="equipment-specifications/clock-frequency">частоты</span>, настроек напряжения и <span class="term" data-term="equipment-specifications/power-limit">лимита мощности</span>. У ASIC-майнеров значительная часть потребления приходится на вычислительные платы и систему охлаждения.</p>

                <h3>Потребление и расходы на электроэнергию</h3>

                <p>При непрерывной работе мощность можно перевести в энергопотребление за определённый период. Например, оборудование мощностью 1 kW, работающее 24 часа, потребляет 24 kWh за сутки, если его фактическая мощность остаётся постоянной.</p>

                <p>Стоимость такой электроэнергии определяется через тариф на электроэнергию. Поэтому один и тот же майнер может иметь различную экономическую эффективность в зависимости от стоимости электричества.</p>

                <h3>Потребление и эффективность</h3>

                <p>Потребление нельзя оценивать отдельно от производительности. Для сравнения оборудования используется <span class="term" data-term="equipment-specifications/power-efficiency">энергоэффективность</span>.</p>

                <p>Снижение потребления при сохранении достаточного хешрейта может повысить экономическую эффективность оборудования. Для этого применяются <span class="term" data-term="equipment-specifications/undervolting">андервольтинг</span>, <span class="term" data-term="equipment-specifications/underclocking">андерклокинг</span> и ограничение мощности.</p>

                <h3>Что ещё учитывать</h3>

                <ul>
                <li>пиковое и фактическое потребление;</li>
                <li>потребление самого вычислительного оборудования и вспомогательных систем;</li>
                <li>нагрузку на электрическую инфраструктуру;</li>
                <li>выделяемое тепло;</li>
                <li>влияние температуры и режима охлаждения на стабильность работы.</li>
