                <p>Почти вся потребляемая майнером электрическая энергия в конечном счёте преобразуется в тепло, поэтому расчёт мощности одновременно является частью расчёта <span class="term" data-term="cooling/thermal-load">тепловой нагрузки</span> системы охлаждения.</p>'
            ],

            'power-efficiency' => [
                'title' => 'Что такое энергоэффективность майнера | TM Wiki',
                'description' => 'Энергоэффективность майнера показывает, сколько вычислительной мощности оборудование получает на единицу потребляемой электроэнергии.',
                'name' => 'Энергоэффективность',
                'caption' => 'Соотношение вычислительной производительности оборудования и потребляемой им мощности.',
                'definition' => '<p><strong>Энергоэффективность</strong> — характеристика оборудования, показывающая, сколько вычислительной работы оно выполняет относительно потребляемой электрической мощности. В майнинге энергоэффективность особенно важна, поскольку электроэнергия является одной из основных статей <span class="term" data-term="mining-economics/opex">операционных расходов</span>.</p>

                <p>Для ASIC-оборудования энергоэффективность часто выражают в J/TH — джоулях на терахеш. Чем меньше значение J/TH, тем меньше энергии требуется для получения одного терахеша вычислительной мощности.</p>

                <h3>Расчёт</h3>

                <p>Если устройство потребляет 3000 W и обеспечивает 200 TH/s, его удельное потребление составляет:</p>

                <p><strong>3000 / 200 = 15 J/TH.</strong></p>

                <p>Тот же показатель можно представить через хешрейт на ватт. Эти показатели описывают одну и ту же связь между производительностью и потреблением, но используют разные единицы измерения.</p>

                <h3>От чего зависит энергоэффективность</h3>

