                <p>Энергоэффективность непосредственно связана со стоимостью электроэнергии и <span class="term" data-term="mining-economics/mining-profitability">рентабельностью майнинга</span>. Чем выше стоимость электричества, тем существеннее влияние эффективности оборудования на экономический результат.</p>'
