                'definition' => '<p><strong>Лимит мощности</strong> (Power Limit) — настройка, ограничивающая максимальное электрическое потребление вычислительного оборудования. Она используется для управления соотношением между <span class="term" data-term="equipment-specifications/hashrate">хешрейтом</span>, энергопотреблением и температурой.</p>

