            'operating-temperature' => [
                'title' => 'Рабочая температура майнера: что это | TM Wiki',
                'description' => 'Рабочая температура характеризует температурные условия эксплуатации майнингового оборудования и влияет на стабильность и ресурс компонентов.',
                'name' => 'Рабочая температура',
                'caption' => 'Температурный диапазон, при котором оборудование рассчитано на стабильную эксплуатацию.',
                'definition' => '<p><strong>Рабочая температура</strong> — температурный параметр, характеризующий условия, в которых майнинговое оборудование должно работать в штатном режиме. Для разных компонентов могут применяться разные температурные диапазоны и предельные значения.</p>

                <p>Температура влияет на стабильность вычислений, энергопотребление, работу системы охлаждения и долговременную эксплуатацию оборудования. Поэтому при проектировании установки учитывают не только температуру самих чипов, но и температуру окружающей среды, температуру входящего воздуха и эффективность отвода тепла.</p>

                <h3>Температура и производительность</h3>

                <p>При чрезмерном нагреве оборудование может автоматически снижать рабочие параметры. Такой механизм называется <span class="term" data-term="equipment-specifications/thermal-throttling">термальным троттлингом</span>. Он позволяет ограничить тепловую нагрузку, но одновременно может уменьшить <span class="term" data-term="equipment-specifications/hashrate">хешрейт</span>.</p>

                <p>Для контроля температуры используются датчики, установленные непосредственно на компонентах или внутри оборудования. В ASIC-майнерах отдельно контролируется температура вычислительных чипов, поскольку именно они создают значительную часть тепловой нагрузки.</p>

                <h3>Связь с охлаждением</h3>

                <p>Поддержание рабочей температуры зависит от системы <span class="term" data-term="cooling/cooling-loop">охлаждения</span> и способности оборудования отводить образующееся тепло. В воздушных системах большое значение имеют температура входящего воздуха и расход воздуха. В жидкостных системах дополнительно контролируются параметры теплоносителя и температурная разница между входом и выходом.</p>

                <p>Для оценки условий эксплуатации также используются <span class="term" data-term="equipment-specifications/chip-temperature">температура чипа</span>, <span class="term" data-term="equipment-specifications/operating-temperature">рабочая температура</span> и показатели окружающей среды.</p>'
            ],

            'chip-temperature' => [
                'title' => 'Что такое температура чипа майнера | TM Wiki',
                'description' => 'Температура чипа показывает нагрев вычислительных микросхем во время работы и используется для контроля состояния майнера.',
                'name' => 'Температура чипа',
                'caption' => 'Температура вычислительной микросхемы во время работы майнингового оборудования.',
                'definition' => '<p><strong>Температура чипа</strong> — температура вычислительной микросхемы во время работы оборудования. В майнинге этот показатель используется для контроля теплового состояния ASIC, GPU или других вычислительных компонентов.</p>

                <p>Температура чипа формируется под воздействием электрической мощности, рабочей частоты, напряжения, нагрузки и эффективности отвода тепла. Поэтому изменение <span class="term" data-term="equipment-specifications/power-limit">лимита мощности</span>, <span class="term" data-term="equipment-specifications/clock-frequency">частоты</span> или параметров охлаждения может непосредственно изменить температуру.</p>

                <h3>Почему температура важна</h3>

                <p>Чрезмерный нагрев может привести к снижению производительности, увеличению количества <span class="term" data-term="equipment-specifications/hardware-error">аппаратных ошибок</span> и срабатыванию <span class="term" data-term="equipment-specifications/thermal-throttling">термального троттлинга</span>. При этом слишком низкая температура сама по себе не является отдельным показателем эффективности: важнее стабильная работа оборудования в допустимом диапазоне.</p>

                <h3>Контроль температуры</h3>

                <p>Температуру чипов контролируют через датчики оборудования и программное обеспечение управления майнером. При превышении заданных порогов система может автоматически изменять частоты, скорость вентиляторов или другие параметры.</p>

                <p>Для поддержания температуры применяются различные технологии охлаждения, включая воздушное, жидкостное и иммерсионное охлаждение. Эффективность системы зависит также от <span class="term" data-term="cooling/heat-dissipation">отвода тепла</span> и <span class="term" data-term="cooling/thermal-load">тепловой нагрузки</span>.</p>'
            ],

