                <p>В майнинге пропускная способность особенно важна для алгоритмов, производительность которых ограничена скоростью доступа к данным. В таких случаях увеличение вычислительной мощности без соответствующего увеличения скорости памяти может не привести к пропорциональному росту <span class="term" data-term="equipment-specifications/hashrate">хешрейта</span>.</p>

