                <p>В майнинге изменение частоты может влиять на <span class="term" data-term="equipment-specifications/hashrate">хешрейт</span>, <span class="term" data-term="equipment-specifications/power-consumption">потребление энергии</span> и <span class="term" data-term="equipment-specifications/chip-temperature">температуру чипов</span>. Однако зависимость не является универсально линейной и определяется архитектурой оборудования и алгоритмом.</p>

