                <p>Повышение частоты выше штатных значений называется <span class="term" data-term="equipment-specifications/overclocking">разгоном</span>. Он может увеличить производительность, но одновременно повысить энергопотребление, температуру и вероятность <span class="term" data-term="equipment-specifications/hardware-error">аппаратных ошибок</span>.</p>

                <p>Снижение частоты называется <span class="term" data-term="equipment-specifications/underclocking">андерклокингом</span>. Его используют для уменьшения энергопотребления и тепловыделения либо для поиска более подходящего режима эксплуатации.</p>

