                'definition' => '<p><strong>Андервольтинг</strong> (undervolting) — снижение напряжения питания вычислительного компонента относительно стандартного значения при сохранении стабильной работы. В майнинге этот метод используется для уменьшения <span class="term" data-term="equipment-specifications/power-consumption">потребления электроэнергии</span> и <span class="term" data-term="equipment-specifications/chip-temperature">температуры чипов</span>.</p>

                <p>Энергопотребление вычислительных схем зависит от напряжения и частоты. Поэтому снижение напряжения может дать значительное уменьшение мощности, особенно если одновременно используется <span class="term" data-term="equipment-specifications/underclocking">андерклокинг</span>.</p>

                <h3>Андервольтинг и стабильность</h3>

                <p>Слишком низкое напряжение может привести к нестабильной работе вычислительных компонентов, появлению <span class="term" data-term="equipment-specifications/hardware-error">аппаратных ошибок</span>, снижению производительности или перезапускам.</p>

                <p>Поэтому после изменения напряжения необходимо проверять фактический <span class="term" data-term="equipment-specifications/hashrate">хешрейт</span>, температуру, потребление и стабильность работы в течение достаточного периода.</p>

