                'definition' => '<p><strong>Термальный троттлинг</strong> — механизм автоматического снижения производительности вычислительного компонента при достижении высокой температуры. Он предназначен для ограничения тепловой нагрузки и предотвращения работы за пределами допустимого температурного режима.</p>

                <p>В майнинге троттлинг может проявляться снижением <span class="term" data-term="equipment-specifications/clock-frequency">рабочей частоты</span>, напряжения или других параметров, от которых зависит производительность. В результате уменьшается фактический <span class="term" data-term="equipment-specifications/hashrate">хешрейт</span>.</p>

                <h3>Причины троттлинга</h3>

                <ul>
                <li>высокая <span class="term" data-term="equipment-specifications/chip-temperature">температура чипов</span>;</li>
                <li>недостаточная производительность системы охлаждения;</li>
                <li>высокая температура окружающей среды;</li>
                <li>загрязнение или ограничение воздушного потока;</li>
                <li>слишком высокая мощность и вычислительная нагрузка;</li>
                <li>неправильные настройки оборудования.</li>
                </ul>

                <p>Троттлинг не является отдельной неисправностью: это защитный механизм. Однако постоянная работа в таком режиме указывает на несоответствие тепловой нагрузки и возможностей системы охлаждения либо на слишком агрессивные настройки оборудования.</p>

                <h3>Как обнаружить троттлинг</h3>

