                <p>Для устранения причины проверяют <span class="term" data-term="cooling/cooling-capacity">мощность системы охлаждения</span>, воздушный поток, температуру входящего воздуха и настройки <span class="term" data-term="equipment-specifications/power-limit">лимита мощности</span>.</p>'
