        'terms' => [
            'mining-pool' => [
                'title' => 'Что такое майнинг-пул | TM Wiki',
                'description' => 'Майнинг-пул объединяет вычислительную мощность майнеров, распределяет задания и делит вознаграждение за найденные блоки.',
                'name' => 'Майнинг-пул',
                'caption' => 'Инфраструктура для объединения майнеров, распределения вычислительной работы и расчёта выплат.',
                'definition' => '<p><strong>Майнинг-пул</strong> — это серверная инфраструктура и система учёта, которая объединяет вычислительную мощность множества участников для совместного майнинга. Вместо того чтобы каждый майнер самостоятельно пытался найти блок и мог долгое время не получать никаких выплат, участники подключаются к общему пулу и регулярно передают ему результаты своей вычислительной работы.</p>

                <p>Пул не объединяет физически сами устройства. Каждый майнер продолжает выполнять вычисления на собственном оборудовании, а серверная инфраструктура пула распределяет между участниками задания, принимает результаты и ведёт учёт их вклада. В результате вероятность того, что именно совокупная мощность участников найдёт блок, значительно выше, чем вероятность для отдельного небольшого майнера.</p>

                <h3>Как работает майнинг-пул</h3>

                <ol>
                    <li>Майнер настраивает оборудование и подключает его к серверу пула.</li>
                    <li>Пул идентифицирует подключённое устройство или <span class="term" data-term="mining-pools/pool-worker">worker</span> и выдаёт ему задание.</li>
                    <li>Майнер выполняет вычисления и ищет результаты, соответствующие заданной пулом <span class="term" data-term="mining-pools/share-difficulty">сложности шар</span>.</li>
                    <li>Подходящие результаты отправляются обратно на сервер пула в виде <span class="term" data-term="mining-pools/share">shares</span>.</li>
                    <li>Пул проверяет полученные результаты и учитывает корректные shares в статистике участника.</li>
                    <li>Если один из участников находит действительный блок, пул передаёт или учитывает этот блок в соответствии с правилами блокчейн-сети.</li>
                    <li>Полученное вознаграждение распределяется между участниками по выбранной <span class="term" data-term="mining-pools/payout-scheme">схеме выплат</span>.</li>
                </ol>

                <h3>Зачем используются shares</h3>

                <p>Полноценные блоки находятся относительно редко по сравнению с количеством вычислительных попыток. Поэтому пулу нужен промежуточный показатель, позволяющий регулярно измерять работу каждого участника. Для этого используется share.</p>

                <p>Пул устанавливает собственную сложность для shares, которая обычно значительно ниже сетевой сложности. Благодаря этому даже сравнительно небольшой майнер может регулярно отправлять результаты. По частоте и сложности принятых shares пул получает статистическую оценку фактически выполняемой работы.</p>

                <p>Share сама по себе обычно не является найденным блоком. Однако достаточно редкая share может одновременно удовлетворять и сетевой сложности. В таком случае результат становится кандидатом на полноценный блок.</p>

                <h3>Что учитывает пул</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Показатель</th>
                            <th>Практическое значение</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Hashrate</td>
                            <td>Показывает вычислительную мощность подключённого оборудования.</td>
                        </tr>
                        <tr>
                            <td>Shares</td>
                            <td>Используются для подтверждения и измерения выполненной работы.</td>
                        </tr>
                        <tr>
                            <td>Rejected shares</td>
                            <td>Показывают результаты, которые пул не засчитал.</td>
                        </tr>
                        <tr>
                            <td>Worker status</td>
                            <td>Позволяет отслеживать подключение и активность отдельных устройств.</td>
                        </tr>
                        <tr>
                            <td>Payout balance</td>
                            <td>Показывает накопленное вознаграждение участника.</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Как распределяется вознаграждение</h3>

                <p>После нахождения блока пул получает вознаграждение, предусмотренное протоколом сети. Оно может включать <span class="term" data-term="mining/block-reward">награду за блок</span>, состоящую из субсидии и комиссий транзакций.</p>

                <p>Участник получает не всю сумму вознаграждения самостоятельно. Сначала может удерживаться <span class="term" data-term="mining-pools/pool-fee">комиссия пула</span>, после чего оставшаяся сумма распределяется между участниками по правилам выбранной схемы выплат.</p>

                <p>Например, при модели PPS выплата может рассчитываться за каждую принятую share, тогда как при PPLNS учитывается определённое количество последних shares. Поэтому одинаковый хешрейт может приводить к различному распределению дохода в зависимости от выбранной модели.</p>

                <h3>Основные параметры майнинг-пула</h3>

                <ul>
                    <li><strong>Pool fee</strong> — комиссия, удерживаемая пулом.</li>
                    <li><strong>Payout threshold</strong> — минимальный баланс, необходимый для выплаты.</li>
                    <li><strong>Payout scheme</strong> — правила расчёта вознаграждения.</li>
                    <li><strong>Share difficulty</strong> — сложность промежуточных результатов.</li>
                    <li><strong>Stratum</strong> — протокол обмена заданиями и результатами.</li>
                    <li><strong>VarDiff</strong> — механизм автоматического изменения сложности shares.</li>
                </ul>

                <h3>Что важно учитывать при выборе пула</h3>

                <p>Размер комиссии — только один из параметров. На практическую эффективность также влияют стабильность серверов, задержка соединения, частота отклонённых и устаревших shares, правила выплат, минимальный порог выплаты и поддерживаемые протоколы.</p>

                <p>Если соединение между майнером и пулом нестабильно, часть вычислительной работы может становиться устаревшей до момента её отправки. Поэтому инфраструктура пула и качество сетевого подключения могут влиять на фактический результат работы оборудования.</p>

                <p>Майнинг-пул является связующим уровнем между отдельным майнером и процессом коллективной добычи блоков. Для понимания его работы важно различать <span class="term" data-term="mining-pools/pool-mining">Pool Mining</span>, <span class="term" data-term="mining-pools/share">Share</span>, <span class="term" data-term="mining-pools/payout-scheme">Payout Scheme</span> и используемый <span class="term" data-term="mining-pools/stratum">Stratum</span>-протокол.</p>'
            ],

            'pool-mining' => [
                'title' => 'Что такое Pool Mining | TM Wiki',
                'description' => 'Pool Mining — совместный майнинг, при котором участники объединяют вычислительную мощность и получают выплаты за свой вклад.',
                'name' => 'Pool Mining',
                'caption' => 'Модель совместного майнинга через объединение вычислительных ресурсов нескольких участников.',
                'definition' => '<p><strong>Pool Mining</strong> — модель организации майнинга, при которой несколько независимых участников объединяют свои вычислительные ресурсы через общий <span class="term" data-term="mining-pools/mining-pool">майнинг-пул</span>. Каждый участник продолжает самостоятельно выполнять вычисления на своём оборудовании, но результаты работы передаются общей инфраструктуре.</p>

                <p>Основная причина использования Pool Mining заключается в вероятностной природе нахождения блоков. Если отдельный майнер обладает небольшой долей вычислительной мощности сети, вероятность того, что именно его оборудование найдёт следующий блок, может быть невысокой. Объединение большого количества майнеров позволяет чаще находить блоки на уровне всей группы.</p>

                <h3>Механика Pool Mining</h3>

                <p>Пул формирует задания и передаёт их подключённым устройствам. Для контроля вклада используется <span class="term" data-term="mining-pools/share">share</span> — результат вычислений с установленной пулом сложностью. Майнер отправляет такие результаты на сервер, а пул проверяет их и связывает с конкретным worker.</p>

                <p>Когда пул находит блок, полученное вознаграждение распределяется между участниками. Способ распределения определяется <span class="term" data-term="mining-pools/payout-scheme">схемой выплат</span>. В некоторых схемах основной показатель — количество и сложность принятых shares, в других учитывается определённое временное или количественное окно.</p>

                <h3>Pool Mining и Solo Mining</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Характеристика</th>
                            <th>Pool Mining</th>
                            <th>Solo Mining</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Объединение мощности</td>
                            <td>Да</td>
                            <td>Нет</td>
                        </tr>
                        <tr>
                            <td>Источник заданий</td>
                            <td>Пул</td>
                            <td>Сеть или собственная инфраструктура</td>
                        </tr>
                        <tr>
                            <td>Учёт shares</td>
                            <td>Да</td>
                            <td>Обычно не требуется в пуловом смысле</td>
                        </tr>
                        <tr>
                            <td>Распределение награды</td>
                            <td>Между участниками по правилам пула</td>
                            <td>Награда достаётся участнику, нашедшему блок</td>
                        </tr>
                        <tr>
                            <td>Комиссия пула</td>
                            <td>Может применяться</td>
                            <td>Отсутствует</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Экономическая особенность</h3>

                <p>Pool Mining не увеличивает вычислительную мощность отдельного устройства. Он изменяет способ организации этой мощности и распределения результата. Поэтому эффективность участника определяется не только хешрейтом, но и комиссией пула, схемой выплат, сетевой сложностью, наградой за блок и стоимостью электроэнергии.</p>

                <p>Для участника с небольшим хешрейтом важна также статистическая стабильность выплат. Даже если ожидаемый доход определяется одними и теми же сетевыми параметрами, фактическое время получения отдельных выплат зависит от выбранной модели и частоты нахождения блоков.</p>

                <h3>Связь с другими понятиями</h3>

                <p>Pool Mining непосредственно связан с <span class="term" data-term="mining-pools/mining-pool">Mining Pool</span>, <span class="term" data-term="mining-pools/share">Share</span>, <span class="term" data-term="mining-pools/pool-fee">Pool Fee</span>, <span class="term" data-term="mining-pools/payout-scheme">Payout Scheme</span> и протоколом <span class="term" data-term="mining-pools/stratum">Stratum</span>.</p>'
            ],

            'pool-worker' => [
                'title' => 'Что такое Pool Worker | TM Wiki',
                'description' => 'Pool Worker — идентификатор устройства или группы устройств, по которому майнинг-пул учитывает работу и показывает статистику.',
                'name' => 'Pool Worker',
                'caption' => 'Логическая единица майнера, используемая пулом для отдельного учёта вычислительной работы.',
                'definition' => '<p><strong>Pool Worker</strong> — логический идентификатор, с помощью которого майнинг-пул отделяет вычислительную работу одного устройства или группы устройств от других подключённых участников. Worker нужен прежде всего для статистики, мониторинга и диагностики.</p>

                <p>Физический майнер и worker — не обязательно одно и то же. Например, один ASIC может работать как один worker, а несколько процессов или устройств могут в зависимости от используемого программного обеспечения и конфигурации представляться пулу по-разному.</p>

                <h3>Какие данные связаны с worker</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Данные</th>
                            <th>Назначение</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Hashrate</td>
                            <td>Контроль фактической вычислительной мощности.</td>
                        </tr>
                        <tr>
                            <td>Shares</td>
                            <td>Учёт результатов выполненной работы.</td>
                        </tr>
                        <tr>
                            <td>Rejected shares</td>
                            <td>Контроль отклонённых результатов.</td>
                        </tr>
                        <tr>
                            <td>Connection status</td>
                            <td>Определение состояния подключения устройства.</td>
                        </tr>
                        <tr>
                            <td>Worker name</td>
                            <td>Идентификация конкретного устройства или логической группы.</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Зачем создавать отдельных workers</h3>

                <p>Если в пул подключено несколько майнеров, использование отдельных workers позволяет быстро определить, какое устройство работает нормально, какое снизило хешрейт, а какое перестало отправлять shares.</p>

                <p>Например, при наличии десяти ASIC один общий идентификатор значительно усложняет диагностику. Если каждый ASIC представлен отдельным worker, статистика позволяет сравнить их хешрейт, количество shares, долю отклонённых результатов и время последней активности.</p>

                <h3>Worker и выплаты</h3>

                <p>Worker обычно является единицей учёта, а не отдельным получателем средств. Пул может суммировать работу нескольких workers, принадлежащих одному аккаунту, и рассчитывать общий баланс. Конкретная модель зависит от инфраструктуры конкретного пула.</p>

                <p>Таким образом, Pool Worker следует рассматривать как логический уровень между физическим оборудованием и системой статистики майнинг-пула.</p>'
            ],

            'share' => [
                'title' => 'Что такое Share (Шара) в майнинге | TM Wiki',
                'description' => 'Share — результат вычислений, который майнер отправляет пулу для подтверждения выполненной работы и расчёта своего вклада.',
                'name' => 'Share (Шара)',
                'caption' => 'Промежуточный результат вычислений, используемый пулом для измерения работы майнера.',
                'definition' => '<p><strong>Share</strong> — результат вычислительной работы майнера, который соответствует установленному пулом уровню сложности и отправляется на сервер для проверки. Share используется как измеримый показатель выполненной работы внутри майнинг-пула.</p>

                <p>В обычном процессе майнинга оборудование выполняет огромное количество хеш-операций. Большинство результатов не имеют значения для блокчейн-сети. Если пул требовал бы от майнера сообщать только о результатах, соответствующих полной сетевой сложности, небольшие устройства могли бы отправлять данные крайне редко. Поэтому пул устанавливает отдельную, более низкую сложность для shares.</p>

                <h3>Как появляется share</h3>

                <ol>
                    <li>Пул создаёт или получает актуальное задание.</li>
                    <li>Задание передаётся майнеру через используемый протокол.</li>
                    <li>Майнер начинает выполнять вычисления.</li>
                    <li>Один из результатов соответствует заданной share difficulty.</li>
                    <li>Майнер отправляет результат пулу.</li>
                    <li>Пул проверяет результат и принимает или отклоняет его.</li>
                </ol>

                <h3>Share и найденный блок</h3>

                <p>Share не следует путать с блоком. У них разные уровни сложности.</p>

                <table>
                    <thead>
                        <tr>
                            <th>Свойство</th>
                            <th>Share</th>
                            <th>Блок</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Сложность</td>
                            <td>Устанавливается пулом для учёта работы</td>
                            <td>Определяется сетью</td>
                        </tr>
                        <tr>
                            <td>Частота</td>
                            <td>Должна быть достаточно высокой для статистического учёта</td>
                            <td>Значительно ниже</td>
                        </tr>
                        <tr>
                            <td>Экономический результат</td>
                            <td>Используется для расчёта доли участника</td>
                            <td>Создаёт право на награду за блок</td>
                        </tr>
                    </tbody>
                </table>

                <p>Иногда share одновременно соответствует и сетевому условию. Тогда она может представлять найденный блок. Однако большинство shares являются только доказательством выполненной работы для целей внутреннего учёта пула.</p>

                <h3>Типы shares</h3>

                <p>В зависимости от результата и момента отправки share может быть принята, отклонена или признана устаревшей. Для анализа работы оборудования используются понятия <span class="term" data-term="mining-pools/valid-share">Valid Share</span>, <span class="term" data-term="mining-pools/invalid-share">Invalid Share</span> и <span class="term" data-term="mining-pools/stale-share">Stale Share</span>.</p>'
            ],

            'valid-share' => [
                'title' => 'Что такое Valid Share | TM Wiki',
                'description' => 'Valid Share — корректный результат работы майнера, который соответствует сложности пула и принимается для учёта вычислительного вклада.',
                'name' => 'Valid Share',
                'caption' => 'Корректная share, которую пул принял и засчитал как выполненную работу.',
                'definition' => '<p><strong>Valid Share</strong> — корректный результат вычислений, соответствующий установленной пулом <span class="term" data-term="mining-pools/share-difficulty">share difficulty</span> и другим требованиям текущего задания. После проверки такой результат принимается сервером пула и может использоваться при расчёте вознаграждения.</p>

                <p>Valid Share является одним из основных механизмов измерения вклада участника в Pool Mining. Поскольку полноценные блоки находятся редко, пулу необходим более частый способ подтверждать, что оборудование действительно выполняет работу.</p>

                <h3>Что проверяет пул</h3>

                <ul>
                    <li>соответствие результата текущему заданию;</li>
                    <li>корректность вычисленного значения;</li>
                    <li>соответствие установленной сложности;</li>
                    <li>отсутствие дублирования результата;</li>
                    <li>актуальность задания, на основании которого получен результат.</li>
                </ul>

                <h3>Valid Share и выплаты</h3>

                <p>Принятые shares могут использоваться системой выплат по-разному. Например, при <span class="term" data-term="mining-pools/pay-per-share">PPS</span> каждая принятая share имеет заранее рассчитанную стоимость. В <span class="term" data-term="mining-pools/pplns">PPLNS</span> учитывается вклад в определённом окне последних shares.</p>

                <p>Поэтому сама valid share не имеет универсальной фиксированной денежной стоимости. Её экономическое значение зависит от сложности share, схемы выплат, сетевых параметров и правил конкретного пула.</p>'
            ],

            'stale-share' => [
                'title' => 'Что такое Stale Share | TM Wiki',
                'description' => 'Stale Share — устаревший результат майнинга, отправленный после изменения задания и обычно не засчитываемый пулом.',
                'name' => 'Stale Share',
                'caption' => 'Share, относящаяся к уже неактуальному заданию пула.',
                'definition' => '<p><strong>Stale Share</strong> — результат вычислений, который был получен на основании уже устаревшего задания. Сам результат может быть математически корректным, однако к моменту его получения пулом соответствующая работа уже потеряла актуальность.</p>

                <p>Наиболее типичная ситуация возникает при нахождении нового блока в сети. После появления нового блока прежнее задание может стать недействительным для дальнейшей работы. Пул отправляет майнерам новое задание, но часть устройств может ещё некоторое время вычислять старое или отправлять результаты с задержкой.</p>

                <h3>Причины появления stale shares</h3>

                <ul>
                    <li>высокая задержка между майнером и сервером пула;</li>
                    <li>нестабильное интернет-соединение;</li>
                    <li>задержка получения нового задания;</li>
                    <li>перегрузка сети или сервера;</li>
                    <li>медленная обработка команд оборудованием;</li>
                    <li>ошибки или задержки в программном обеспечении.</li>
                </ul>

                <h3>Как оценивается stale rate</h3>

                <p>Пул может показывать количество или процент stale shares относительно общего числа отправленных результатов. Небольшое количество устаревших shares возможно даже при нормальной работе из-за задержек распространения новых заданий.</p>

                <p>Высокая доля stale shares может означать, что значительная часть вычислительной работы выполняется по заданиям, которые уже потеряли актуальность. Поэтому показатель используют при диагностике сетевой инфраструктуры и настройки майнера.</p>

                <p>Stale Share отличается от <span class="term" data-term="mining-pools/invalid-share">Invalid Share</span>: stale результат может быть корректным математически, но устаревшим по времени, тогда как invalid share не соответствует требованиям корректности.</p>'
            ],

            'invalid-share' => [
                'title' => 'Что такое Invalid Share | TM Wiki',
                'description' => 'Invalid Share — результат вычислений, который не соответствует требованиям задания или не проходит проверку майнинг-пула.',
                'name' => 'Invalid Share',
                'caption' => 'Некорректная share, которую пул не принимает как выполненную работу.',
                'definition' => '<p><strong>Invalid Share</strong> — результат вычислений, который не проходит проверку пула. В отличие от stale share, проблема заключается не только в том, что результат пришёл поздно: сам результат не соответствует требованиям текущего задания или установленным правилам проверки.</p>

                <h3>Основные причины</h3>

