                        </tr>
                        <tr>
                            <td>Проблемы памяти</td>
                            <td>Ошибки памяти могут изменять результаты вычислений.</td>
                        </tr>
                        <tr>
                            <td>Конфигурация</td>
                            <td>Неверные параметры программного обеспечения могут приводить к неправильным результатам.</td>
                        </tr>
                        <tr>
                            <td>Программная ошибка</td>
                            <td>Ошибка клиента или прошивки может приводить к формированию некорректных данных.</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Почему invalid shares важны</h3>

                <p>Если доля invalid shares постоянно повышена, фактическая эффективность оборудования может быть ниже ожидаемой. Кроме того, высокая доля ошибок может указывать на проблемы со стабильностью, температурой, разгоном, питанием или программным обеспечением.</p>

                <p>При диагностике необходимо отличать invalid shares от <span class="term" data-term="mining-pools/stale-share">stale shares</span> и других типов <span class="term" data-term="mining-pools/rejected-share">rejected shares</span>, поскольку причины и способы устранения могут различаться.</p>'
            ],

            'rejected-share' => [
                'title' => 'Что такое Rejected Share | TM Wiki',
                'description' => 'Rejected Share — результат, который майнинг-пул отклонил и не засчитал в статистику работы участника.',
                'name' => 'Rejected Share',
                'caption' => 'Share, которую пул не принял для дальнейшего учёта.',
                'definition' => '<p><strong>Rejected Share</strong> — общий термин для результата, который был отправлен майнером, но не был принят пулом. В зависимости от конкретной системы причиной отказа может быть устаревшее задание, вычислительная ошибка, дубликат результата, ошибка протокола или другое нарушение требований.</p>

                <p>Таким образом, rejected share описывает итог обработки результата, а не одну конкретную причину.</p>

                <h3>Основные причины отклонения</h3>

                <table>
