                </table>

                <h3>Rejected shares и эффективность</h3>

                <p>При нормальной работе небольшая доля отклонённых результатов может возникать из-за сетевых задержек и особенностей обработки заданий. Однако устойчиво высокая доля rejected shares требует диагностики.</p>

                <p>Для анализа необходимо определить причину отказа. Если преобладают stale shares, внимание следует обратить на задержки и соединение. Если преобладают invalid shares, необходимо проверить стабильность оборудования, настройки, температуру и программное обеспечение.</p>'
            ],

            'share-difficulty' => [
                'title' => 'Что такое Share Difficulty | TM Wiki',
                'description' => 'Share Difficulty — сложность, которую пул задаёт для получения промежуточных результатов с подходящей частотой.',
                'name' => 'Share Difficulty',
                'caption' => 'Уровень сложности, используемый пулом для регулярного учёта вычислительной работы майнера.',
                'definition' => '<p><strong>Share Difficulty</strong> — уровень сложности, который майнинг-пул устанавливает для промежуточных результатов работы майнера. Результат, удовлетворяющий этой сложности, считается share и может быть использован для измерения вычислительного вклада участника.</p>

                <p>Share difficulty обычно значительно ниже сетевой сложности блокчейна. Это позволяет пулу получать от майнеров результаты значительно чаще, чем сеть получает полноценные блоки.</p>

                <h3>Зачем нужна отдельная сложность</h3>

                <p>Представим сеть с очень высокой сетевой сложностью. Если потребовать от каждого майнера отправлять только результаты, способные удовлетворить сетевому условию, устройство с небольшим хешрейтом могло бы не отправлять результат очень долго. Пул не смог бы оперативно определить, работает ли устройство и какой объём вычислений оно выполняет.</p>

                <p>Share difficulty решает эту задачу. Пул устанавливает более доступный порог и получает регулярные результаты, которые статистически отражают работу устройства.</p>

                <h3>Связь с хешрейтом</h3>

                <p>При прочих равных условиях более мощный майнер будет находить shares чаще при одинаковой сложности. Поэтому пул может повышать share difficulty для мощных устройств и снижать её для слабых.</p>

                <p>Автоматическая адаптация выполняется механизмом <span class="term" data-term="mining-pools/vardiff">VarDiff</span>.</p>

                <h3>Share difficulty и network difficulty</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Параметр</th>
                            <th>Share Difficulty</th>
                            <th>Сетевая сложность</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Кто определяет</td>
                            <td>Майнинг-пул</td>
                            <td>Правила блокчейн-сети</td>
                        </tr>
                        <tr>
                            <td>Назначение</td>
                            <td>Учёт работы майнеров</td>
                            <td>Определение условия нахождения блока</td>
                        </tr>
                        <tr>
                            <td>Влияет на консенсус</td>
                            <td>Нет</td>
                            <td>Да</td>
                        </tr>
                    </tbody>
                </table>

                <p>Изменение share difficulty не означает изменение сложности добычи монеты. Оно меняет только частоту промежуточных результатов, которые майнер отправляет пулу.</p>'
            ],

            'pool-fee' => [
                'title' => 'Что такое Pool Fee | TM Wiki',
                'description' => 'Pool Fee — комиссия майнинг-пула, которая удерживается из дохода участников за предоставление инфраструктуры и обслуживание.',
                'name' => 'Pool Fee',
                'caption' => 'Комиссия, удерживаемая пулом из вознаграждения майнера.',
                'definition' => '<p><strong>Pool Fee</strong> — комиссия, которую майнинг-пул удерживает за предоставление серверной инфраструктуры, распределение заданий, обработку shares, расчёт вознаграждений и проведение выплат.</p>

                <p>Обычно комиссия выражается в процентах от суммы, которая должна быть распределена между участниками. Например, при условной комиссии 1% часть рассчитанного вознаграждения направляется оператору пула, а оставшаяся сумма распределяется согласно выбранной схеме выплат.</p>

                <h3>За что взимается комиссия</h3>

                <ul>
                    <li>работу серверов и сетевой инфраструктуры;</li>
                    <li>распределение заданий между майнерами;</li>
                    <li>приём и проверку shares;</li>
                    <li>ведение статистики и мониторинга;</li>
                    <li>расчёт балансов участников;</li>
                    <li>организацию выплат.</li>
                </ul>

                <h3>Комиссия и фактический доход</h3>

                <p>Pool Fee непосредственно уменьшает сумму, которая остаётся майнеру после расчёта с пулом. Поэтому при сравнении пулов необходимо учитывать комиссию вместе со схемой выплат и другими условиями.</p>

                <p>Например, низкая комиссия сама по себе не означает, что фактическая выплата будет выше при любых условиях. На результат также влияют способ расчёта shares, частота нахождения блоков, особенности распределения дохода, задержки и условия выплат.</p>

                <h3>Комиссия и рентабельность</h3>

                <p>При расчёте <span class="term" data-term="mining-economics/mining-profitability">рентабельности майнинга</span> комиссию пула следует относить к расходам, уменьшающим доход от добычи. Чем выше совокупная комиссия при прочих равных условиях, тем ниже чистая сумма, получаемая майнером.</p>

                <p>Конкретный размер Pool Fee устанавливается оператором пула и может отличаться для разных монет, схем выплат и режимов майнинга.</p>'
            ],

            'payout-threshold' => [
                'title' => 'Что такое Payout Threshold | TM Wiki',
                'description' => 'Payout Threshold — минимальный баланс, после достижения которого пул выполняет выплату накопленного вознаграждения майнеру.',
                'name' => 'Payout Threshold',
                'caption' => 'Минимальная сумма накопленного баланса, необходимая для проведения выплаты.',
                'definition' => '<p><strong>Payout Threshold</strong> — минимальная сумма, которую участник должен накопить на балансе майнинг-пула, чтобы получить выплату. Пока баланс ниже установленного значения, вознаграждение обычно остаётся на внутреннем балансе.</p>

                <h3>Зачем используется порог</h3>

                <p>Если отправлять каждую небольшую сумму отдельной транзакцией, пул и блокчейн будут обрабатывать большое количество мелких выплат. Порог позволяет объединять накопления и уменьшать количество операций.</p>

                <p>Например, если порог установлен на уровне 0,01 монеты, баланс 0,006 монеты обычно не будет выплачен автоматически. После дальнейшего начисления и достижения 0,01 монеты система сможет инициировать выплату в соответствии с правилами пула.</p>

                <h3>От чего зависит фактическая выплата</h3>

                <ul>
                    <li>размер накопленного баланса;</li>
                    <li>установленный payout threshold;</li>
                    <li>правила автоматических выплат;</li>
                    <li>комиссии и условия транзакции;</li>
                    <li>доступность сети и самого пула.</li>
                </ul>

                <p>Порог выплаты не определяет доходность майнинга. Он влияет прежде всего на момент, когда начисленный доход превращается во внешний перевод.</p>

                <p>Поэтому при анализе денежных потоков важно различать <strong>начисленный доход</strong>, <strong>баланс в пуле</strong> и <strong>фактически полученную выплату</strong>.</p>'
            ],

            'payout-scheme' => [
                'title' => 'Что такое Payout Scheme | TM Wiki',
                'description' => 'Payout Scheme определяет, как майнинг-пул рассчитывает долю участника и распределяет доход от найденных блоков.',
                'name' => 'Payout Scheme',
                'caption' => 'Правила расчёта и распределения вознаграждения между участниками майнинг-пула.',
                'definition' => '<p><strong>Payout Scheme</strong> — модель, по которой майнинг-пул рассчитывает и распределяет вознаграждение между участниками. Схема определяет, какие результаты работы учитываются, за какой период они учитываются и как вычисляется доля каждого майнера.</p>

                <p>Разные схемы могут использовать одинаковые вычислительные данные, но по-разному распределять денежный поток во времени. Поэтому название схемы важно учитывать при сравнении условий майнинга.</p>

                <h3>Основные модели</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Схема</th>
                            <th>Принцип</th>
                            <th>Что учитывается</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>PPS</td>
                            <td>Оплата за каждую принятую share</td>
                            <td>Принятые shares и расчётная стоимость работы</td>
                        </tr>
                        <tr>
                            <td>PPLNS</td>
                            <td>Распределение дохода по последним shares</td>
                            <td>Shares в определённом окне</td>
                        </tr>
                        <tr>
                            <td>FPPLNS</td>
                            <td>Вариант PPLNS с фиксированным правилом</td>
                            <td>Shares в фиксированном расчётном окне</td>
                        </tr>
                        <tr>
                            <td>Solo Pool</td>
                            <td>Награда при нахождении блока участником</td>
                            <td>Факт нахождения блока</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Почему схема выплат важна</h3>

                <p>Один и тот же майнер может получать различающиеся по времени выплаты в зависимости от схемы. При PPS выплаты связаны с принятыми shares и поэтому могут быть более регулярными. При PPLNS результат сильнее связан с фактической частотой нахождения блоков и вкладом участника в соответствующем окне.</p>

                <p>При этом схема выплат не меняет саму сетевую награду и не создаёт дополнительную вычислительную мощность. Она определяет способ распределения экономического результата между пулом и его участниками.</p>

                <h3>Что нужно проверить в правилах пула</h3>

                <ul>
                    <li>точную формулу расчёта;</li>
                    <li>какие shares учитываются;</li>
                    <li>размер и продолжительность расчётного окна;</li>
                    <li>размер комиссии;</li>
                    <li>правила выплаты;</li>
                    <li>минимальный порог выплаты;</li>
                    <li>правила при нахождении блока и изменении задания.</li>
                </ul>'
            ],

            'pay-per-share' => [
                'title' => 'Что такое Pay Per Share | TM Wiki',
                'description' => 'Pay Per Share — схема выплат, при которой майнер получает рассчитанное вознаграждение за каждую принятую пулом share.',
                'name' => 'Pay Per Share',
                'caption' => 'Схема выплат, в которой вознаграждение рассчитывается за каждую принятую share.',
                'definition' => '<p><strong>Pay Per Share (PPS)</strong> — схема выплат майнинг-пула, при которой участнику начисляется вознаграждение за каждую принятую share. Расчёт выполняется по формуле, учитывающей ожидаемую стоимость вычислительной работы и параметры сети.</p>

                <h3>Как работает PPS</h3>

                <p>Майнер выполняет вычисления и отправляет пулу shares. После принятия каждой share система начисляет участнику соответствующее вознаграждение. При этом выплата не обязательно зависит от того, был ли найден блок непосредственно в момент отправки конкретной share.</p>

                <p>Таким образом, оператор пула принимает на себя значительную часть вариации между фактической частотой нахождения блоков и статистически ожидаемым значением. Участник получает начисления на основе своей принятой работы, а пул управляет риском различий между начислениями и фактически полученными блоками.</p>

                <h3>Что может учитываться в расчёте</h3>

                <ul>
                    <li>сложность сети;</li>
                    <li>сложность shares;</li>
                    <li>награда за блок;</li>
                    <li>ожидаемая частота нахождения блоков;</li>
                    <li>комиссия пула;</li>
                    <li>правила конкретной реализации PPS.</li>
                </ul>

                <h3>PPS и PPLNS</h3>

                <p>Главное отличие от <span class="term" data-term="mining-pools/pplns">PPLNS</span> заключается в моменте и принципе расчёта. В PPS стоимость принятой share рассчитывается непосредственно по модели PPS. В PPLNS вознаграждение связано с долей участника в определённом наборе последних shares, относящихся к найденному блоку.</p>

                <p>Поэтому при сравнении двух пулов недостаточно сравнивать только процент комиссии. Необходимо учитывать саму формулу выплат и условия, по которым пул рассчитывает стоимость работы.</p>'
            ],

            'pplns' => [
                'title' => 'Что такое PPLNS в майнинге | TM Wiki',
                'description' => 'PPLNS — схема выплат, учитывающая последние N shares участника при распределении вознаграждения за найденный пулом блок.',
                'name' => 'PPLNS',
                'caption' => 'Схема выплат, основанная на вкладе майнера в заданном окне последних shares.',
                'definition' => '<p><strong>PPLNS (Pay Per Last N Shares)</strong> — схема выплат майнинг-пула, при которой для распределения вознаграждения учитываются последние <em>N</em> shares. Конкретное определение окна и правила его применения зависят от реализации пула.</p>

                <p>В отличие от схемы, где каждая share имеет фиксированную расчётную стоимость независимо от момента нахождения блока, PPLNS связывает выплату с определённым историческим набором работы участников.</p>

                <h3>Как работает PPLNS</h3>

                <ol>
                    <li>Пул постоянно получает и сохраняет информацию о принятых shares.</li>
                    <li>Участники выполняют работу с различным хешрейтом.</li>
                    <li>Пул находит блок.</li>
                    <li>Определяется соответствующее окно последних N shares.</li>
                    <li>Для каждого участника рассчитывается его доля shares внутри этого окна.</li>
                    <li>Распределяемое вознаграждение делится пропорционально учтённому вкладу.</li>
                </ol>

                <h3>Почему размер окна имеет значение</h3>

                <p>Если окно небольшое, результат сильнее зависит от недавней активности и момента подключения майнера. Если окно больше, влияние краткосрочных изменений участия может быть распределено на более продолжительный период.</p>

                <p>Поэтому два пула, оба использующие PPLNS, могут давать разные распределения выплат, если используют разные значения N или разные правила определения окна.</p>

                <h3>Пример</h3>

                <p>Предположим, что пул использует окно из 1 000 000 shares. Если в этом окне оборудование конкретного участника сформировало shares, составляющие 2% от общего учтённого вклада, его доля распределяемого вознаграждения будет рассчитываться исходя из этих 2%, с учётом правил пула и комиссии.</p>

                <p>Если майнер подключился непосредственно перед нахождением блока, значительная часть его вычислительной работы может не попасть в соответствующее историческое окно.</p>

                <h3>PPLNS и регулярность выплат</h3>

                <p>PPLNS не гарантирует одинаковый размер выплат через одинаковые промежутки времени. Доход зависит от нахождения блоков пулом, вклада участника и размера используемого окна. Поэтому фактические начисления могут колебаться даже при относительно стабильном хешрейте.</p>'
            ],

            'fpplns' => [
                'title' => 'Что такое FPPLNS в майнинге | TM Wiki',
                'description' => 'FPPLNS — вариант PPLNS с фиксированным правилом расчёта вклада участника при распределении дохода от найденных блоков.',
                'name' => 'FPPLNS',
                'caption' => 'Вариант PPLNS с фиксированным расчётным окном или правилом учёта shares.',
                'definition' => '<p><strong>FPPLNS</strong> — схема выплат, основанная на принципе <span class="term" data-term="mining-pools/pplns">PPLNS</span>, но использующая фиксированное правило определения набора shares, который применяется при расчёте вознаграждения.</p>

                <p>Название обычно расшифровывается как Fixed Pay Per Last N Shares. Однако конкретная реализация может различаться между майнинг-пулами. Поэтому при практическом сравнении необходимо использовать правила конкретного пула, а не только название схемы.</p>

                <h3>Принцип работы</h3>

                <p>Пул получает shares от всех подключённых участников и формирует историю работы. При нахождении блока применяется заранее установленное правило, определяющее, какие shares входят в расчёт. После этого определяется доля каждого участника и распределяется соответствующая часть вознаграждения.</p>

                <h3>Чем FPPLNS отличается от общего понятия PPLNS</h3>

                <p>PPLNS описывает общий принцип оплаты по последним N shares. FPPLNS подчёркивает наличие фиксированного правила или окна, применяемого для расчёта. На практике терминология может использоваться пулами по-разному, поэтому точная формула всегда должна проверяться в документации конкретного сервиса.</p>

                <table>
                    <thead>
                        <tr>
                            <th>Параметр</th>
                            <th>Значение</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr><td>Основа</td><td>PPLNS</td></tr>
                        <tr><td>Учёт работы</td><td>Shares в установленном расчётном окне</td></tr>
                        <tr><td>Распределение</td><td>Пропорционально учтённому вкладу</td></tr>
                        <tr><td>Точная формула</td><td>Зависит от конкретного пула</td></tr>
                    </tbody>
                </table>'
            ],

            'solo-pool' => [
                'title' => 'Что такое Solo Pool | TM Wiki',
                'description' => 'Solo Pool позволяет майнить через инфраструктуру пула, сохраняя право на награду за блок, найденный собственным оборудованием.',
                'name' => 'Solo Pool',
                'caption' => 'Режим пула, при котором награда за найденный блок относится к участнику, обнаружившему этот блок.',
                'definition' => '<p><strong>Solo Pool</strong> — модель майнинга, объединяющая инфраструктуру майнинг-пула с принципом самостоятельного получения награды за найденный блок. Майнер использует серверы пула для получения заданий и передачи результатов, но не участвует в обычном распределении каждой найденной пулом награды между всеми участниками.</p>

                <p>Если оборудование участника находит блок, соответствующий сетевым требованиям, вознаграждение за этот блок относится к данному участнику согласно правилам пула. При этом оператор может удерживать установленную комиссию.</p>

                <h3>Почему используется Solo Pool</h3>

                <p>Самостоятельная работа с собственной полной инфраструктурой требует настройки узла, обработки заданий и организации взаимодействия с сетью. Solo Pool позволяет вынести часть инфраструктуры на сторону оператора, сохранив вероятностную модель самостоятельного нахождения блока.</p>

                <h3>Solo Pool и обычный пул</h3>

                <table>
