                <p>Главная особенность Solo Pool — сохранение полной вероятностной природы нахождения блока. Если участник обладает небольшой долей сетевой вычислительной мощности, период между найденными блоками может быть очень продолжительным.</p>

                <p>Поэтому Solo Pool следует отличать от обычного <span class="term" data-term="mining-pools/pool-mining">Pool Mining</span>: в обоих случаях используется инфраструктура пула, но экономический механизм распределения награды различается.</p>'
