            'stratum' => [
                'title' => 'Что такое Stratum в майнинге | TM Wiki',
                'description' => 'Stratum — протокол обмена заданиями и результатами между майнерами и серверами майнинг-пула.',
                'name' => 'Stratum',
                'caption' => 'Протокол взаимодействия майнера с инфраструктурой майнинг-пула.',
                'definition' => '<p><strong>Stratum</strong> — протокол взаимодействия между майнинг-оборудованием или клиентом и серверной инфраструктурой пула. Он определяет способ передачи заданий, результатов вычислений и служебной информации, необходимой для совместного майнинга.</p>

                <p>В типичной архитектуре майнер не взаимодействует с блокчейн-сетью для каждой отдельной вычислительной попытки. Вместо этого он получает работу через пул. Stratum обеспечивает коммуникационный слой, через который пул сообщает, что именно нужно вычислять, а майнер сообщает о найденных shares.</p>

                <h3>Основные функции Stratum</h3>

                <ul>
                    <li>установление и поддержание соединения;</li>
                    <li>аутентификация или идентификация worker;</li>
                    <li>передача параметров задания;</li>
                    <li>уведомление о появлении нового задания;</li>
                    <li>передача найденных shares;</li>
                    <li>обработка служебных сообщений;</li>
                    <li>контроль состояния соединения.</li>
                </ul>

                <h3>Stratum в архитектуре пула</h3>

                <p>Упрощённая схема выглядит следующим образом:</p>

                <p><strong>Майнер → Stratum → сервер пула → инфраструктура пула → блокчейн-сеть.</strong></p>

                <p>На практике архитектура может быть сложнее, а конкретная реализация зависит от монеты, программного обеспечения и версии протокола.</p>

                <h3>Почему протокол важен</h3>

                <p>Майнинг требует постоянной передачи новых заданий и результатов. Если коммуникация работает нестабильно, оборудование может продолжать вычисления по устаревшему заданию, что увеличивает количество <span class="term" data-term="mining-pools/stale-share">stale shares</span>. Поэтому задержка, стабильность и корректность обмена данными имеют непосредственное практическое значение.</p>

                <p>Наиболее известными версиями являются <span class="term" data-term="mining-pools/stratum-v1">Stratum V1</span> и <span class="term" data-term="mining-pools/stratum-v2">Stratum V2</span>.</p>'
            ],

            'stratum-v1' => [
                'title' => 'Что такое Stratum V1 | TM Wiki',
                'description' => 'Stratum V1 — распространённый протокол связи между майнерами и пулами для передачи заданий и результатов вычислений.',
                'name' => 'Stratum V1',
                'caption' => 'Первая широко распространённая версия протокола Stratum для пулового майнинга.',
                'definition' => '<p><strong>Stratum V1</strong> — протокол взаимодействия майнеров с серверами майнинг-пулов, который получил широкое распространение в инфраструктуре криптовалютного майнинга. Его основная задача — обеспечить постоянный обмен заданиями и результатами между пулом и подключёнными устройствами.</p>

                <h3>Как работает Stratum V1</h3>

                <ol>
                    <li>Майнер устанавливает соединение с сервером пула.</li>
                    <li>Устройство или клиент сообщает пулу информацию о worker.</li>
                    <li>Пул передаёт параметры задания.</li>
                    <li>Майнер выполняет вычисления.</li>
                    <li>При нахождении подходящего результата он отправляет share пулу.</li>
                    <li>Пул проверяет результат и возвращает информацию о принятии или отклонении.</li>
                    <li>При изменении задания майнер получает новые параметры.</li>
                </ol>

                <h3>Почему Stratum V1 получил широкое распространение</h3>

                <p>Протокол позволил организовать эффективную коммуникацию между большим количеством майнеров и централизованными серверами пулов. Вместо необходимости постоянно передавать большие объёмы данных о всей блокчейн-сети пул мог выдавать участникам компактные задания и получать от них результаты.</p>

                <p>Это особенно важно для специализированного оборудования, которое должно выполнять вычисления с минимальными задержками.</p>

                <h3>Ограничения</h3>

                <p>Stratum V1 создавался в архитектуре, где значительная часть управления майнингом сосредоточена на пуле. В более новых подходах уделяется больше внимания безопасности коммуникации, аутентификации, гибкости распределения ролей и снижению зависимости отдельных компонентов инфраструктуры от централизованного управления.</p>

                <p>Эти задачи являются одной из причин появления <span class="term" data-term="mining-pools/stratum-v2">Stratum V2</span>.</p>

                <p>Конкретные особенности V1 могут отличаться в зависимости от реализации, используемого майнингового клиента и конкретной сети.</p>'
            ],

            'stratum-v2' => [
                'title' => 'Что такое Stratum V2 | TM Wiki',
                'description' => 'Stratum V2 — протокол майнинга с более современной архитектурой обмена данными между майнерами и пуловой инфраструктурой.',
                'name' => 'Stratum V2',
                'caption' => 'Новое поколение протокола Stratum для организации более эффективного и защищённого майнинга.',
                'definition' => '<p><strong>Stratum V2</strong> — протокол и архитектура взаимодействия для майнинга, разработанные как развитие подхода <span class="term" data-term="mining-pools/stratum-v1">Stratum V1</span>. Его задача — сделать коммуникацию между майнерами, пулами и другими компонентами инфраструктуры более эффективной, структурированной и защищённой.</p>

                <p>Stratum V2 рассматривает взаимодействие не просто как передачу отдельных заданий, а как набор формализованных сообщений и ролей между участниками системы. Это позволяет разделять функции, которые в более старой архитектуре часто концентрировались на одной стороне.</p>

                <h3>Основные особенности</h3>

                <ul>
                    <li>формализованный набор сообщений и процедур;</li>
