                <h3>Stratum V2 и выбор транзакций</h3>

                <p>Одной из особенностей архитектуры является возможность изменить распределение контроля над формированием работы. В некоторых конфигурациях майнер может получить больше возможностей влиять на выбор транзакций, включаемых в шаблон блока, вместо полного переноса этой функции на пул.</p>

