            'vardiff' => [
                'title' => 'Что такое VarDiff в майнинге | TM Wiki',
                'description' => 'VarDiff автоматически меняет сложность shares для разных майнеров в зависимости от их вычислительной мощности.',
                'name' => 'VarDiff',
                'caption' => 'Механизм динамической настройки сложности shares под хешрейт конкретного майнера.',
                'definition' => '<p><strong>VarDiff (Variable Difficulty)</strong> — механизм автоматического изменения <span class="term" data-term="mining-pools/share-difficulty">share difficulty</span>, который используется майнинг-пулом для адаптации частоты отправки shares к вычислительной мощности конкретного майнера.</p>

                <p>Майнеры одного пула могут иметь очень разный хешрейт. Например, один участник может использовать оборудование с относительно небольшой вычислительной мощностью, а другой — крупную ферму. Если оба будут работать с одинаковой сложностью shares, количество отправляемых результатов будет сильно различаться.</p>

                <h3>Зачем нужен VarDiff</h3>

                <p>Основная задача VarDiff — поддерживать подходящую частоту отправки shares. Пул стремится получать от каждого worker достаточно результатов для статистического учёта, но не создавать чрезмерный объём сетевых сообщений.</p>

                <table>
                    <thead>
                        <tr>
                            <th>Хешрейт майнера</th>
                            <th>Типичная настройка</th>
                            <th>Цель</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td>Низкий</td>
                            <td>Более низкая share difficulty</td>
                            <td>Получать shares достаточно регулярно</td>
                        </tr>
                        <tr>
                            <td>Высокий</td>
                            <td>Более высокая share difficulty</td>
                            <td>Не допускать избыточного количества сообщений</td>
                        </tr>
                    </tbody>
                </table>

                <h3>Как изменяется сложность</h3>

                <p>Пул наблюдает за частотой, с которой worker отправляет shares. Если результаты поступают слишком часто, сложность может быть увеличена. Если shares поступают слишком редко, сложность может быть снижена.</p>

                <p>Таким образом, VarDiff стремится удерживать средний интервал между shares около заданного пулом значения.</p>

                <h3>VarDiff и сетевая сложность</h3>

                <p>VarDiff не изменяет сложность блокчейн-сети. Он работает только на уровне заданий пула.</p>

                <p>Сетевая сложность определяет, насколько сложно найти полноценный блок. Share difficulty определяет, насколько часто пул получает промежуточные результаты от майнеров.</p>

                <p>Поэтому изменение VarDiff не означает, что монету стало сложнее или легче майнить. Оно изменяет только механизм внутреннего учёта работы участника.</p>

                <h3>Практическое значение</h3>

                <p>Корректно настроенный VarDiff помогает снизить лишний сетевой трафик и одновременно получать достаточно данных для оценки хешрейта. Неподходящие параметры могут приводить к слишком частым сообщениям, редким shares или дополнительной нагрузке на инфраструктуру.</p>'
            ],
        ]
    ],

    'cooling' => [
        'title' => 'Термины охлаждения майнинга',
        'description' => 'Словарь терминов охлаждения майнинг-оборудования: иммерсия, гидроохлаждение, теплообмен, диэлектрическая жидкость и другие понятия.',
        'name' => 'Охлаждение',
        'caption' => 'Термины систем охлаждения майнинг-оборудования: воздушное, водяное и иммерсионное охлаждение, теплообмен, теплоносители и другие понятия.',
        'terms' => [
            'air-cooling' => [
                'title' => 'Что такое воздушное охлаждение | TM Wiki',
                'description' => 'Воздушное охлаждение отводит тепло от майнингового оборудования с помощью воздуха, вентиляторов и радиаторов.',
                'name' => 'Воздушное охлаждение',
                'caption' => 'Способ охлаждения майнингового оборудования, при котором тепло отводится потоком воздуха.',
                'definition' => '<p><strong>Воздушное охлаждение</strong> — способ отвода тепла от майнингового оборудования, при котором нагревающиеся компоненты передают тепловую энергию воздуху, а вентиляторы обеспечивают движение этого воздуха через радиаторы и за пределы оборудования. Это один из наиболее распространённых вариантов охлаждения ASIC-майнеров и другого вычислительного оборудования.</p>

                <p>При работе майнера вычислительные чипы постоянно потребляют электроэнергию и преобразуют её значительную часть в тепло. Это тепло необходимо непрерывно отводить, поскольку чрезмерный нагрев снижает стабильность работы компонентов и может привести к автоматическому снижению частоты или отключению оборудования.</p>

                <h3>Как работает воздушное охлаждение</h3>

                <ol>
                    <li>Вычислительные чипы и другие компоненты оборудования выделяют тепло.</li>
                    <li>Тепло передаётся от компонентов к радиаторам через термоинтерфейсный материал.</li>
                    <li>Вентиляторы создают поток воздуха через радиаторы.</li>
                    <li>Воздух поглощает тепло от радиаторов.</li>
                    <li>Нагретый воздух удаляется из корпуса или помещения.</li>
                    <li>На его место поступает более холодный воздух.</li>
                </ol>

                <h3>От чего зависит эффективность</h3>

                <p>Главным фактором является способность системы отводить возникающую <span class="term" data-term="cooling/thermal-load">тепловую нагрузку</span>. При одинаковом оборудовании эффективность охлаждения сильно зависит от температуры воздуха, его расхода и правильной организации воздушных потоков.</p>

                <p>Особенно важна температура окружающей среды. Чем она выше, тем меньше разница температур между нагревающимся оборудованием и поступающим воздухом. В результате для отвода того же количества тепла требуется больший воздушный поток или более эффективная система охлаждения.</p>

                <p>В майнинговых помещениях также необходимо разделять холодный и горячий воздух. Если нагретый воздух возвращается к входам оборудования, фактическая температура на входе быстро повышается.</p>

                <h3>Преимущества и ограничения</h3>

                <ul>
                    <li>простая конструкция и относительно низкая стоимость;</li>
                    <li>отсутствие жидкого теплоносителя;</li>
                    <li>простое обслуживание и замена вентиляторов;</li>
                    <li>совместимость с большинством стандартных ASIC-майнеров;</li>
                    <li>высокие требования к вентиляции при большой плотности оборудования;</li>
                    <li>повышенный уровень шума при работе мощных вентиляторов.</li>
                </ul>

                <h3>Воздушное охлаждение на майнинговой ферме</h3>

                <p>На небольшой установке достаточно обеспечить свободный приток воздуха и удаление горячего воздуха. На крупном объекте воздушное охлаждение становится частью инженерной инфраструктуры: используются воздуховоды, вытяжные системы, фильтрация и автоматическое управление вентиляцией.</p>

                <p>При высокой плотности оборудования воздушная система может потреблять заметное количество электроэнергии сама по себе. Поэтому при оценке эффективности майнинга необходимо учитывать не только энергопотребление ASIC-майнеров, но и расходы на вспомогательную систему охлаждения.</p>

                <p>Воздушное охлаждение остаётся базовой технологией для многих майнинговых объектов, однако при высокой <span class="term" data-term="cooling/thermal-load">тепловой нагрузке</span> могут применяться <span class="term" data-term="cooling/hydro-cooling">гидроохлаждение</span>, <span class="term" data-term="cooling/immersion-cooling">иммерсионное охлаждение</span> и другие специализированные решения.</p>'
            ],

            'immersion-cooling' => [
                'title' => 'Что такое иммерсионное охлаждение | TM Wiki',
                'description' => 'Иммерсионное охлаждение погружает майнинговое оборудование в диэлектрическую жидкость для эффективного отвода тепла.',
                'name' => 'Иммерсионное охлаждение',
                'caption' => 'Охлаждение оборудования путём погружения его в непроводящую диэлектрическую жидкость.',
                'definition' => '<p><strong>Иммерсионное охлаждение</strong> — технология отвода тепла, при которой майнинговое оборудование или его отдельные компоненты погружаются в специальную электрически непроводящую жидкость. Такая жидкость одновременно контактирует с нагревающимися поверхностями и переносит тепло к элементам системы, где оно окончательно отводится наружу.</p>

                <p>Главное отличие иммерсионного охлаждения от воздушного заключается в среде, которая непосредственно принимает тепло от оборудования. Вместо большого объёма воздуха используется специальный <span class="term" data-term="cooling/dielectric-fluid">диэлектрический флюид</span>, не создающий электрического контакта между компонентами.</p>

                <h3>Как работает иммерсионное охлаждение</h3>

                <ol>
                    <li>ASIC-оборудование устанавливается в специальную ёмкость.</li>
                    <li>Оборудование погружается в совместимую <span class="term" data-term="cooling/dielectric-fluid">диэлектрическую жидкость</span>.</li>
                    <li>Тепло от вычислительных компонентов передаётся жидкости.</li>
                    <li>Нагретый теплоноситель перемещается внутри системы.</li>
                    <li>Через теплообменник тепло передаётся наружному контуру.</li>
                    <li>Охлаждённая жидкость возвращается к оборудованию.</li>
                </ol>

                <h3>Однофазное и двухфазное охлаждение</h3>

                <p>В однофазных системах рабочая жидкость остаётся в жидком состоянии на протяжении всего цикла. Она нагревается при контакте с оборудованием, затем перемещается к теплообменнику и после охлаждения возвращается обратно.</p>

                <p>В двухфазных системах используется жидкость, которая при определённой температуре испаряется. Пары поднимаются в верхнюю часть установки, где конденсируются и снова превращаются в жидкость. Такая архитектура использует фазовый переход для переноса тепла.</p>

                <h3>Преимущества технологии</h3>

                <ul>
                    <li>высокая эффективность отвода тепла;</li>
                    <li>возможность работы с высокой плотностью оборудования;</li>
                    <li>снижение зависимости от большого воздушного потока;</li>
                    <li>значительное снижение роли стандартных вентиляторов;</li>
                    <li>более равномерный отвод тепла от компонентов.</li>
                </ul>

                <h3>Что требуется для эксплуатации</h3>

