                <p>Иммерсионное охлаждение особенно интересно для объектов с высокой <span class="term" data-term="cooling/thermal-load">тепловой нагрузкой</span>. Однако сама технология не устраняет необходимость отвода тепла из помещения или здания: она лишь меняет способ передачи тепла от оборудования к внешней системе.</p>'
