                'definition' => '<p><strong>Гидроохлаждение</strong> — технология отвода тепла с использованием циркулирующего жидкого теплоносителя. В майнинге под этим термином обычно понимают инженерную систему, которая отводит тепло от высоконагруженного оборудования через жидкостный контур вместо перемещения больших объёмов воздуха.</p>

                <p>Основой системы является <span class="term" data-term="cooling/cooling-loop">контур охлаждения</span>, по которому движется <span class="term" data-term="cooling/coolant">теплоноситель</span>. Он получает тепло от оборудования, перемещается к теплообменнику, отдаёт энергию внешней среде и возвращается обратно.</p>

