                <h3>Расчёт производительности</h3>

                <p>Для системы важно сопоставить её <span class="term" data-term="cooling/cooling-capacity">охлаждающую способность</span> с фактической <span class="term" data-term="cooling/thermal-load">тепловой нагрузкой</span> оборудования. Если система способна отводить меньше тепла, чем производят майнеры, температура теплоносителя и компонентов будет постепенно повышаться.</p>

                <p>Также контролируется <span class="term" data-term="cooling/delta-t">дельта T</span> между входом и выходом. Слишком высокая разница температур может указывать на недостаточный расход или недостаточную производительность системы.</p>

                <h3>Применение в майнинге</h3>

                <p>Гидроохлаждение особенно полезно для установок с высокой плотностью оборудования, где воздушная вентиляция требует больших объёмов воздуха и значительной вспомогательной мощности.</p>

                <p>При этом жидкостная инфраструктура сложнее воздушной. Требуются защита от утечек, обслуживание насосов и теплообменников, контроль качества жидкости и мониторинг рабочих параметров. Поэтому эффективность технологии необходимо оценивать как свойство всей системы, а не только отдельного охлаждающего блока.</p>'
