                'name' => 'Отвод тепла',
                'caption' => 'Процесс удаления тепловой энергии, возникающей при работе вычислительного оборудования.',
                'definition' => '<p><strong>Отвод тепла</strong> — процесс удаления тепловой энергии от майнингового оборудования и её передачи в окружающую среду либо в отдельную систему, которая выполняет дальнейшее охлаждение. Любая вычислительная система, потребляющая электрическую энергию, должна каким-либо способом избавляться от образующегося тепла.</p>

                <p>В ASIC-майнере тепло образуется прежде всего в вычислительных чипах и связанных с ними электронных компонентах. Сначала энергия должна пройти от источника тепла к охлаждающему элементу, после чего она передаётся воздуху или жидкости и выводится из оборудования.</p>

                <h3>Этапы отвода тепла</h3>

                <ol>
                    <li>образование тепла внутри электронных компонентов;</li>
                    <li>передача тепла к радиатору или охлаждающему блоку;</li>
                    <li>передача энергии воздуху или <span class="term" data-term="cooling/coolant">теплоносителю</span>;</li>
                    <li>перемещение нагретой среды;</li>
                    <li>окончательная передача тепла окружающей среде.</li>
                </ol>

                <p>Эффективность процесса зависит от всех этапов. Даже мощный вентилятор не компенсирует плохой контакт между чипом и радиатором, а эффективный теплоноситель не решит проблему недостаточной производительности теплообменника.</p>

                <h3>Отвод тепла и тепловая нагрузка</h3>

                <p>Производительность системы должна соответствовать <span class="term" data-term="cooling/thermal-load">тепловой нагрузке</span>. Если выделяется 500 кВт тепла, охлаждающая инфраструктура должна иметь возможность непрерывно отводить сопоставимое количество энергии с необходимым запасом.</p>

                <p>В крупных системах отвод тепла может включать несколько последовательных контуров. Например, внутренний контур забирает тепло от оборудования, а внешний контур передаёт его наружному воздуху через теплообменник.</p>

                <h3>Почему отвод тепла важен</h3>

                <p>Недостаточный отвод тепла приводит к росту температуры компонентов. Это может увеличить вероятность нестабильной работы, аппаратных ошибок и <span class="term" data-term="equipment-specifications/thermal-throttling">термального троттлинга</span>. Поэтому система отвода тепла является частью общей надёжности майнинговой инфраструктуры.</p>'
            ],

            'thermal-load' => [
                'title' => 'Что такое тепловая нагрузка | TM Wiki',
                'description' => 'Тепловая нагрузка показывает количество тепла, которое майнинговое оборудование и другие источники выделяют в систему охлаждения.',
                'name' => 'Тепловая нагрузка',
                'caption' => 'Количество тепловой энергии, которое необходимо непрерывно отводить от оборудования.',
                'definition' => '<p><strong>Тепловая нагрузка</strong> — количество тепловой энергии, которое оборудование выделяет за единицу времени и которое система охлаждения должна отвести. Для майнинговых ферм этот показатель является одним из основных параметров при проектировании вентиляции, жидкостного охлаждения и теплообменной инфраструктуры.</p>

                <p>Практически вся электрическая мощность, потребляемая ASIC-майнером, в конечном итоге преобразуется в тепло. Поэтому энергопотребление оборудования является важным исходным параметром для оценки тепловой нагрузки.</p>

                <h3>Как рассчитывается нагрузка</h3>

                <p>Для простой оценки можно суммировать потребляемую мощность всех работающих устройств. Например, если оборудование потребляет суммарно 1 МВт, то приблизительная тепловая нагрузка также составляет около 1 МВт тепловой мощности, если не учитывать небольшую часть энергии, которая уходит на другие формы излучения или работу вспомогательных систем.</p>

                <p>На практике дополнительно учитывается электрооборудование, насосы, вентиляторы, источники питания и другие элементы инфраструктуры. Поэтому полная нагрузка помещения может быть выше нагрузки непосредственно ASIC-оборудования.</p>

                <h3>Тепловая нагрузка и охлаждение</h3>

                <p>Охлаждающая система должна иметь достаточную <span class="term" data-term="cooling/cooling-capacity">охлаждающую способность</span>. Если она меньше фактической нагрузки, температура будет расти до тех пор, пока не изменятся условия теплообмена или оборудование не снизит производительность.</p>

                <p>Для жидкостной системы нагрузка связана с расходом <span class="term" data-term="cooling/coolant">теплоносителя</span> и его <span class="term" data-term="cooling/delta-t">изменением температуры</span>. Для воздушной системы учитываются расход воздуха и разница температур между входом и выходом.</p>

                <h3>Зачем учитывать запас</h3>

                <p>Проектировать систему точно под номинальную нагрузку рискованно. Температура окружающей среды, загрязнение фильтров, изменение мощности оборудования и деградация компонентов могут снизить фактическую производительность охлаждения.</p>'
            ],

            'thermal-paste' => [
                'title' => 'Что такое термопаста | TM Wiki',
                'description' => 'Термопаста заполняет микронеровности между чипом и радиатором и снижает тепловое сопротивление контактного слоя.',
                'name' => 'Термопаста',
                'caption' => 'Пастообразный термоинтерфейсный материал для улучшения передачи тепла от чипа к радиатору.',
                'definition' => '<p><strong>Термопаста</strong> — пастообразный термоинтерфейсный материал, который наносится между нагревающимся компонентом и охлаждающей поверхностью. В майнинговом оборудовании она может использоваться между ASIC-чипом и радиатором или другим теплоотводящим элементом.</p>

                <p>Поверхности чипа и радиатора имеют микроскопические неровности. Если соединить их без специального материала, между поверхностями останутся воздушные промежутки. Термопаста заполняет эти неровности и обеспечивает более эффективную передачу тепла.</p>

                <h3>Как термопаста влияет на охлаждение</h3>

                <p>Термопаста не охлаждает чип самостоятельно. Она уменьшает сопротивление на границе между источником тепла и радиатором. После передачи тепла радиатор или охлаждающий блок должен вывести энергию через воздух или <span class="term" data-term="cooling/coolant">теплоноситель</span>.</p>

                <h3>Важность толщины слоя</h3>

                <p>Задача термопасты заключается в заполнении микронеровностей, а не в создании толстого промежуточного слоя. Поэтому избыток пасты не означает автоматически лучшее охлаждение. Слишком толстый слой может увеличить расстояние теплопередачи.</p>

                <h3>Обслуживание</h3>

                <p>Со временем свойства пасты могут изменяться под воздействием температуры. Она может высыхать, перемещаться или терять первоначальную способность эффективно заполнять контактную поверхность.</p>

                <p>При обслуживании ASIC-оборудования необходимо учитывать конструкцию конкретной платы и производителя. Неправильное нанесение может привести к неравномерному контакту и различиям температуры между отдельными чипами.</p>'
            ],

            'thermal-pad' => [
                'title' => 'Что такое термопрокладка | TM Wiki',
                'description' => 'Термопрокладка передаёт тепло между компонентом и радиатором, заполняя зазор между двумя поверхностями.',
                'name' => 'Термопрокладка',
                'caption' => 'Эластичный термоинтерфейсный материал, используемый для передачи тепла через заданный зазор.',
                'definition' => '<p><strong>Термопрокладка</strong> — мягкий или эластичный термоинтерфейсный материал, предназначенный для передачи тепла между компонентом и радиатором или другой теплоотводящей поверхностью. В отличие от термопасты, прокладка имеет определённую физическую толщину и может компенсировать относительно большой зазор между поверхностями.</p>

                <p>Термопрокладки часто используются там, где компонент не может непосредственно соприкасаться с радиатором. Материал сжимается при монтаже и обеспечивает тепловой контакт между двумя поверхностями.</p>

                <h3>Где применяются термопрокладки</h3>

                <ul>
                    <li>на электронных компонентах с фиксированным зазором;</li>
                    <li>между микросхемами и металлическими пластинами;</li>
                    <li>в системах охлаждения, где поверхности имеют разную высоту;</li>
                    <li>в некоторых конструкциях ASIC-майнеров и блоков питания.</li>
                </ul>

                <h3>Отличие от термопасты</h3>

                <p><span class="term" data-term="cooling/thermal-paste">Термопаста</span> предназначена прежде всего для заполнения очень тонких микронеровностей между поверхностями. Термопрокладка одновременно выполняет функцию теплового интерфейса и физического заполнителя зазора.</p>

                <p>Поэтому термопрокладку выбирают не только по теплопроводности, но и по толщине, сжимаемости и механическим свойствам. Если прокладка слишком толстая или слишком жёсткая, она может создать чрезмерное механическое давление или ухудшить контакт других компонентов.</p>

                <h3>Значение для майнингового оборудования</h3>

                <p>В ASIC-майнерах состояние термопрокладок может влиять на температуру отдельных компонентов. Старение, потеря эластичности или неправильная толщина могут ухудшить передачу тепла.</p>

                <p>При замене важно использовать материал подходящей толщины и характеристик. Нельзя автоматически заменять термопрокладку толстым слоем термопасты, поскольку эти материалы выполняют разные функции.</p>'
            ],

            'delta-t' => [
                'title' => 'Что такое Delta T в охлаждении | TM Wiki',
                'description' => 'Delta T — разница температур между двумя точками системы охлаждения, используемая для оценки передачи тепла.',
                'name' => 'Delta T',
                'caption' => 'Разница температур между входом и выходом системы или отдельного элемента охлаждения.',
                'definition' => '<p><strong>Delta T</strong> — разница температур между двумя выбранными точками системы охлаждения. В майнинге этот показатель часто используется для сравнения температуры теплоносителя или воздуха на входе и выходе из оборудования.</p>

                <p>Например, если жидкость поступает в охлаждающий блок при температуре 30 °C и выходит при 35 °C, Delta T составляет 5 °C. Это означает, что теплоноситель увеличил свою температуру на пять градусов во время прохождения через оборудование.</p>

                <h3>Как рассчитывается Delta T</h3>

                <p>Простейшая формула:</p>

                <p><strong>Delta T = температура выхода − температура входа</strong></p>

                <p>В зависимости от конкретной системы можно измерять температуру воздуха, воды или другого <span class="term" data-term="cooling/coolant">теплоносителя</span>. Важно всегда указывать, между какими именно точками производится измерение.</p>

                <h3>Delta T в жидкостном охлаждении</h3>

                <p>Для жидкостной системы Delta T позволяет оценивать, насколько сильно нагревается теплоноситель при прохождении через оборудование. Вместе с расходом жидкости и её теплоёмкостью этот параметр используется для расчёта фактически переносимой тепловой энергии.</p>

                <p>Большое Delta T не всегда означает хорошую или плохую работу системы само по себе. Необходимо учитывать расход жидкости, температуру компонентов и конструкцию системы.</p>

                <h3>Delta T в воздушном охлаждении</h3>

                <p>В воздушной системе можно сравнивать температуру входящего воздуха и температуру выходящего воздуха. Полученная разница показывает, насколько воздух нагрелся после прохождения через оборудование.</p>

                <h3>Зачем нужен показатель</h3>

                <p>Delta T используется при проектировании и диагностике систем охлаждения. Изменение показателя может указывать на изменение расхода, тепловой нагрузки, температуры окружающей среды или эффективности теплообменника.</p>

                <p>Для корректного анализа Delta T необходимо рассматривать вместе с <span class="term" data-term="cooling/cooling-capacity">охлаждающей способностью</span>, расходом среды и фактической <span class="term" data-term="cooling/thermal-load">тепловой нагрузкой</span>.</p>'
            ],
        ]
    ],

    'mining-infrastructure' => [
