        'description' => 'Словарь терминов майнинг-инфраструктуры: майнинг-фермы, хостинг, дата-центры, PUE, SLA и другие понятия.',
        'name' => 'Инфраструктура майнинга',
        'caption' => 'Термины инфраструктуры для промышленного майнинга: фермы, хостинг, дата-центры, контейнеры, электроснабжение, PUE и другие понятия.',
        'terms' => [
            'mining-farm' => [
                'title' => 'Что такое майнинг-ферма | TM Wiki',
                'description' => 'Майнинг-ферма — комплекс оборудования и инфраструктуры для промышленного или крупного по объёму майнинга криптовалют.',
                'name' => 'Майнинг-ферма',
                'caption' => 'Комплекс оборудования и инфраструктуры для совместной работы большого количества майнеров.',
                'definition' => '<p><strong>Майнинг-ферма</strong> — это совокупность оборудования, сетевых соединений, электроснабжения, охлаждения и систем управления, организованных для одновременной работы большого количества устройств, участвующих в добыче криптовалют.</p>

                <p>В простейшем случае ферма может состоять из нескольких устройств, установленных в одном помещении. В промышленном масштабе она включает десятки, сотни или тысячи майнеров, распределённых по стойкам, контейнерам или отдельным зонам. Поэтому майнинг-ферма представляет собой не только набор <span class="term" data-term="mining-equipment/mining-hardware">майнингового оборудования</span>, но и целую инфраструктуру, обеспечивающую его непрерывную работу.</p>

                <h3>Из чего состоит майнинг-ферма</h3>

                <p>Физическая конфигурация зависит от масштаба объекта и используемого оборудования. Обычно в состав фермы входят:</p>

                <ul>
                    <li><span class="term" data-term="mining-equipment/asic-miner">ASIC-майнеры</span>, GPU- или другое оборудование для вычислений;</li>
                    <li>электрические линии, распределительные устройства и защитная аппаратура;</li>
                    <li>система охлаждения и отвода тепла;</li>
                    <li>сетевое оборудование и подключение к интернету;</li>
                    <li>система мониторинга и <span class="term" data-term="mining-infrastructure/remote-management">удалённого управления</span>;</li>
                    <li>конструкции для размещения оборудования;</li>
                    <li>резервные элементы инфраструктуры, необходимые для поддержания <span class="term" data-term="equipment-specifications/uptime">uptime</span>.</li>
                </ul>

                <h3>Как работает майнинг-ферма</h3>

                <p>Каждый установленный майнер самостоятельно выполняет вычислительную работу, а инфраструктура объекта обеспечивает его питание, охлаждение и сетевое соединение. Оборудование подключается к выбранному <span class="term" data-term="mining-pools/mining-pool">майнинг-пулу</span> или работает в другом режиме добычи.</p>

                <p>При увеличении количества устройств основным ограничением становится уже не только вычислительная мощность. Необходимо обеспечить достаточную мощность электроснабжения, возможность отвода выделяемого тепла, сетевую пропускную способность и обслуживание оборудования.</p>

                <h3>Масштабирование фермы</h3>

                <p>Добавление новых майнеров требует проверки всей инфраструктуры. Например, увеличение вычислительной мощности одновременно повышает нагрузку на электрическую систему и систему охлаждения. Если один из этих элементов не рассчитан на дополнительную нагрузку, фактический хешрейт фермы может оказаться ниже планируемого.</p>

                <p>Для крупных объектов поэтому заранее рассчитывают электрическую ёмкость, <span class="term" data-term="cooling/cooling-capacity">охлаждающую способность</span>, сетевую инфраструктуру и резервирование критических компонентов.</p>

                <h3>Что важно учитывать</h3>

                <table>
                    <thead>
                        <tr>
                            <th>Компонент</th>
