                <p>Таким образом, майнинг-ферма — это комплексная система, в которой вычислительное оборудование является только одним из элементов. Экономическая и техническая эффективность объекта зависит от согласованности электроснабжения, охлаждения, сетей, размещения и управления.</p>'
            ],

            'data-center' => [
                'title' => 'Что такое дата-центр | TM Wiki',
                'description' => 'Дата-центр — объект с инженерной инфраструктурой для размещения вычислительного оборудования, включая специализированные майнинговые нагрузки.',
                'name' => 'Дата-центр',
                'caption' => 'Инженерно оборудованный объект для размещения и непрерывной эксплуатации вычислительного оборудования.',
                'definition' => '<p><strong>Дата-центр</strong> — это специализированный объект, предназначенный для размещения вычислительного и сетевого оборудования с обеспечением электропитания, охлаждения, связи, физической безопасности и других инженерных систем.</p>

                <p>В контексте майнинга дата-центр может использоваться как инфраструктурная площадка для размещения большого количества <span class="term" data-term="mining-equipment/mining-hardware">майнингового оборудования</span>. Однако не каждый дата-центр предназначен для майнинга: высокая плотность энергопотребления и тепловыделения требуют соответствующей инженерной конфигурации.</p>

                <h3>Основные характеристики</h3>

                <ul>
                    <li>высокая доступность электроснабжения;</li>
                    <li>контролируемая система охлаждения;</li>
                    <li>структурированная сетевая инфраструктура;</li>
                    <li>контроль доступа и физическая безопасность;</li>
                    <li>системы мониторинга инженерного оборудования;</li>
                    <li>возможность обслуживания и замены компонентов.</li>
                </ul>

                <h3>Дата-центр и майнинг</h3>

                <p>Майнинговый дата-центр отличается от обычного вычислительного объекта прежде всего характером нагрузки. ASIC-майнеры работают с высокой и относительно постоянной электрической нагрузкой и выделяют значительное количество тепла. Поэтому для них особенно важны доступная мощность и эффективный отвод тепла.</p>

                <p>При размещении оборудования также учитывается плотность нагрузки. Чем больше вычислительной мощности устанавливается на единицу площади, тем выше требования к электрической системе и охлаждению.</p>

                <h3>Надёжность инфраструктуры</h3>

                <p>Для непрерывной работы майнинга большое значение имеет доступность инженерных систем. Отказ питания, перегрев или потеря сетевого соединения могут привести к простою оборудования и снижению фактического времени работы.</p>

                <p>Поэтому при оценке дата-центра учитывают резервирование электроснабжения, возможности обслуживания, мониторинг, сетевые каналы и условия восстановления после отказов.</p>

                <h3>Размещение майнинга</h3>

                <p>Дата-центр может принадлежать оператору майнинга или предоставлять инфраструктуру сторонним клиентам. Во втором случае оборудование размещается на объекте по модели <span class="term" data-term="mining-infrastructure/mining-hosting">майнинг-хостинга</span>, а владелец площадки отвечает за часть инфраструктурных задач.</p>'
            ],

            'mining-container' => [
