                'definition' => '<p><strong>Майнинговый контейнер</strong> — это специально оборудованный контейнерный модуль, предназначенный для установки и эксплуатации майнингового оборудования. В его конструкцию могут входить системы электропитания, охлаждения, вентиляции, сетевого подключения, освещения и мониторинга.</p>

                <p>Контейнер представляет собой физическую единицу инфраструктуры. Несколько контейнеров могут объединяться на одной площадке и формировать более крупный объект. Такой подход позволяет стандартизировать размещение оборудования и добавлять вычислительную мощность отдельными модулями.</p>

                <h3>Основные элементы контейнера</h3>

                <ul>
                    <li>места или конструкции для установки майнеров;</li>
