                </ul>

                <h3>Тепловая нагрузка</h3>

                <p>Практически вся потребляемая майнером электрическая энергия в конечном итоге преобразуется в тепло. Поэтому вместимость контейнера определяется не только количеством доступных мест для оборудования, но и возможностью отводить образующееся тепло.</p>

                <p>При воздушном охлаждении большое значение имеют производительность вентиляторов, организация воздушных потоков и температура окружающей среды. Для других конфигураций могут использоваться специализированные системы охлаждения.</p>

                <h3>Электрическая система</h3>

                <p>Внутреннее распределение мощности должно соответствовать суммарной нагрузке установленного оборудования. При проектировании учитываются номинальная мощность устройств, допустимая нагрузка линий, распределение фаз и необходимый резерв.</p>

                <p>Поэтому контейнер нельзя рассматривать отдельно от внешней электрической инфраструктуры. Даже контейнер с полностью готовыми внутренними системами требует внешнего источника питания подходящей мощности.</p>

                <h3>Масштабирование</h3>

