                'definition' => '<p><strong>Майнинг отель (хостинг)</strong> — это модель размещения майнингового оборудования, при которой владелец устройств устанавливает их на сторонней специализированной площадке. Оператор площадки предоставляет инфраструктуру, необходимую для работы оборудования, а условия обслуживания определяются договором.</p>

