                'definition' => '<p><strong>Трёхфазное питание</strong> — это система переменного тока, в которой используются три электрические фазы со сдвигом между ними. Такая система широко применяется в промышленной энергетике и на объектах с высокой электрической нагрузкой.</p>

                <p>В майнинге трёхфазное питание удобно для крупных площадок, поскольку позволяет распределять нагрузку между фазами и подключать мощное оборудование через соответствующую электрическую инфраструктуру.</p>

                <h3>Зачем используется трёхфазная система</h3>

                <p>Основное преимущество заключается в эффективной передаче и распределении большой мощности. На промышленном объекте большое количество майнеров можно распределять по фазам таким образом, чтобы нагрузка электрической системы оставалась сбалансированной в пределах проектных требований.</p>

                <p>При этом само наличие трёх фаз не означает автоматического увеличения доступной мощности. Максимальная нагрузка определяется всей цепочкой — от подключения к электросети до внутренних линий и защитного оборудования.</p>

                <h3>Балансировка нагрузки</h3>

                <p>При подключении большого количества однофазных потребителей важно правильно распределять их между фазами. Значительный дисбаланс может создавать дополнительные нагрузки на элементы системы и снижать эффективность её использования.</p>

                <p>Промышленное оборудование может подключаться непосредственно к трёхфазной системе, если его электрические параметры это предусматривают.</p>

                <h3>Применение в майнинговой инфраструктуре</h3>

                <ul>
                    <li>питание крупных групп ASIC;</li>
                    <li>распределение нагрузки между фазами;</li>
                    <li>подключение мощных вспомогательных систем;</li>
                    <li>организация промышленных распределительных щитов.</li>
                </ul>

                <p>Конкретная схема подключения должна соответствовать характеристикам оборудования и требованиям местной электрической инфраструктуры. Трёхфазное питание является частью общей системы, а не самостоятельным источником дополнительной мощности.</p>'
