                'description' => 'Remote management — удалённое управление майнинговым оборудованием, мониторингом и частью инфраструктуры через сеть.',
                'name' => 'Remote Management',
                'caption' => 'Удалённый контроль и настройка майнингового оборудования без физического присутствия на площадке.',
                'definition' => '<p><strong>Remote Management</strong> — это система и набор инструментов для удалённого мониторинга, настройки и управления майнинговым оборудованием и связанными инфраструктурными компонентами.</p>

                <p>Для крупных майнинговых объектов удалённое управление позволяет контролировать большое количество устройств из единого интерфейса. Оператор может видеть состояние оборудования, обнаруживать отключения, изменять параметры работы и выполнять перезапуск отдельных устройств без непосредственного доступа к ним.</p>

