                    <li>температуры и состояние оборудования;</li>
                    <li>потребление электроэнергии, если оно доступно через систему мониторинга;</li>
                    <li>статус подключения;</li>
                    <li>аппаратные ошибки;</li>
                    <li>настройки частоты и производительности;</li>
                    <li>перезапуск оборудования.</li>
                </ul>

                <h3>Как работает удалённое управление</h3>

                <p>Майнер подключается к локальной сети объекта, после чего система управления получает от него телеметрию и предоставляет оператору интерфейс для мониторинга. В зависимости от оборудования управление может осуществляться через веб-интерфейс, специализированное программное обеспечение или централизованную платформу.</p>

                <p>На крупной площадке система может автоматически обнаруживать отключившиеся устройства и формировать уведомления. Это сокращает время между возникновением неисправности и реакцией оператора.</p>

                <h3>Безопасность</h3>

                <p>Удалённый доступ должен быть защищён, поскольку получение контроля над майнером позволяет изменять его настройки и направление вычислений. Для доступа используются аутентификация, ограничение прав, защищённые сетевые соединения и разделение управляющей сети от других сетевых сегментов.</p>

                <h3>Значение для крупной фермы</h3>

                <p>При небольшом количестве устройств ручное управление ещё возможно, но с ростом количества оборудования оно становится трудоёмким. Поэтому remote management является важной частью инфраструктуры крупных <span class="term" data-term="mining-infrastructure/mining-farm">майнинг-ферм</span> и удалённых площадок.</p>'
