                'definition' => '<p><strong>Расходы на майнинг</strong> — это совокупность затрат, которые возникают при эксплуатации оборудования и поддержании майнинговой операции. Они уменьшают финансовый результат, получаемый от добычи криптовалюты.</p>

                <p>К основным расходам относятся электроэнергия, размещение оборудования, охлаждение, ремонт, запасные компоненты, интернет и сетевое оборудование, обслуживание инфраструктуры, заработная плата персонала, страхование, налоги и другие обязательные платежи.</p>

                <h3>Основные категории расходов</h3>

                <ul>
                    <li><strong>Энергия</strong> — стоимость потреблённой электроэнергии, которая для многих операций является крупнейшей статьёй затрат.</li>
                    <li><strong>Эксплуатация</strong> — текущие расходы на обслуживание, ремонт и поддержание оборудования.</li>
                    <li><strong>Размещение</strong> — платежи за площадку, электрическую инфраструктуру, охлаждение и другие услуги.</li>
                    <li><strong>Административные расходы</strong> — связь, персонал, бухгалтерия, страхование и аналогичные затраты.</li>
                    <li><strong>Налоги</strong> — платежи, рассчитываемые в соответствии с применимым законодательством.</li>
                </ul>

                <p>Для анализа важно отделять текущие расходы от капитальных вложений. Текущие затраты относятся к <span class="term" data-term="mining-economics/opex">операционным расходам</span>, тогда как приобретение оборудования и создание инфраструктуры обычно относятся к <span class="term" data-term="mining-economics/capex">капитальным затратам</span>.</p>

                <p>В расчётах прибыльности расходы сопоставляются с <span class="term" data-term="mining-economics/mining-revenue">выручкой от майнинга</span> и могут выражаться за сутки, месяц, год, единицу хешрейта или одну добытую монету.</p>'
            ],

            'mining-cost' => [
