                'caption' => 'Затраты, связанные с производством майнингового результата.',
                'definition' => '<p><strong>Себестоимость майнинга</strong> — это совокупные затраты, относимые к получению определённого объёма добытой криптовалюты или выполненной вычислительной работы. Показатель используется для оценки экономической эффективности оборудования и всей майнинговой операции.</p>

                <p>В зависимости от методики расчёта себестоимость может включать только переменные затраты, например электроэнергию, либо более широкий набор расходов: обслуживание, размещение, амортизацию оборудования, персонал, налоги и другие компоненты.</p>

                <h3>Себестоимость одной монеты</h3>

                <p>Один из практических вариантов — определить, сколько денежных средств требуется для добычи одной монеты. Для этого общие относимые затраты за период делят на объём добычи за тот же период.</p>

                <p>Такой показатель зависит не только от расходов, но и от производительности оборудования, сложности сети, времени работы и других параметров. Поэтому рост курса монеты сам по себе не уменьшает себестоимость в техническом смысле, но может увеличить разницу между её рыночной стоимостью и затратами на добычу.</p>

                <h3>Себестоимость хешрейта</h3>

                <p>Для сравнения различных операций применяется <span class="term" data-term="mining-economics/cost-per-hash">стоимость единицы хешрейта</span>. Она позволяет сопоставлять затраты площадок с разным масштабом и производительностью.</p>

                <p>Себестоимость является одним из входных показателей для расчёта безубыточности и <span class="term" data-term="mining-economics/mining-profitability">рентабельности майнинга</span>.</p>'
            ],

