                'name' => 'CAPEX',
                'caption' => 'Сокращение от Capital Expenditure — капитальные затраты.',
                'definition' => '<p><strong>CAPEX</strong> — сокращение от английского <em>Capital Expenditure</em>, то есть капитальные затраты. В майнинге термин обозначает вложения в активы, которые используются для создания, расширения или модернизации операции.</p>

                <p>Типичные элементы CAPEX — майнеры, серверное оборудование, электрические системы, трансформаторы, контейнеры, системы охлаждения, строительство помещений и другая инфраструктура.</p>

                <h3>CAPEX и OPEX</h3>

                <p>Главное практическое отличие CAPEX от <span class="term" data-term="mining-economics/opex">OPEX</span> заключается в характере затрат. CAPEX связан с созданием или приобретением долгосрочного актива, а OPEX — с его текущей эксплуатацией.</p>

                <p>Например, покупка партии ASIC относится к CAPEX, а электроэнергия, необходимая для их ежедневной работы, — к OPEX. Такое разделение важно при расчёте инвестиционной модели.</p>

                <p>Размер CAPEX влияет на необходимое финансирование, срок окупаемости, денежный поток и общую структуру проекта.</p>'
            ],

            'opex' => [
