                'name' => 'OPEX',
                'caption' => 'Сокращение от Operating Expenditure — операционные расходы.',
                'definition' => '<p><strong>OPEX</strong> — сокращение от английского <em>Operating Expenditure</em>, то есть операционные расходы. В майнинге этот термин обозначает затраты, которые возникают в процессе регулярной эксплуатации оборудования и инфраструктуры.</p>

                <p>К основным компонентам OPEX относятся электроэнергия, аренда или <span class="term" data-term="mining-infrastructure/mining-hosting">майнинг-отель</span>, обслуживание, ремонт, интернет, персонал, охлаждение и другие текущие расходы.</p>

                <h3>Почему OPEX важен</h3>

                <p>Для работающей майнинговой операции OPEX напрямую связан с текущей прибыльностью. Даже если оборудование уже полностью оплачено, высокая стоимость электроэнергии или обслуживания может сделать эксплуатацию экономически нецелесообразной.</p>

                <p>OPEX обычно сравнивают с <span class="term" data-term="mining-economics/mining-revenue">выручкой</span>, чтобы определить операционный результат. При долгосрочном анализе также учитываются капитальные вложения и амортизация.</p>

                <p>Точный состав OPEX зависит от модели бизнеса и принятой системы учёта.</p>'
