                'name' => 'ROI',
                'caption' => 'Показатель эффективности вложенного капитала, обычно выражаемый в процентах.',
                'definition' => '<p><strong>Возврат инвестиций</strong> (<em>Return on Investment</em>, ROI) — это показатель, который сопоставляет финансовый результат с объёмом вложенного капитала. В майнинге он используется для оценки эффективности инвестиций в оборудование, инфраструктуру или весь проект.</p>

                <p>В простой форме ROI может рассчитываться как отношение прибыли за выбранный период к первоначальным инвестициям, умноженное на 100 процентов. Однако точная формула зависит от того, какой период и какой финансовый результат используются.</p>

                <h3>ROI в майнинге</h3>

                <p>При оценке майнингового проекта в инвестиции могут включаться ASIC-майнеры, электрическая инфраструктура, охлаждение, строительство площадки и другие компоненты <span class="term" data-term="mining-economics/capex">CAPEX</span>.</p>

                <p>Результат может зависеть от курса криптовалюты, сложности сети, тарифа на электричество, простоев, расходов на обслуживание и остаточной стоимости оборудования.</p>

                <p>ROI не следует путать со сроком окупаемости: ROI выражает относительный финансовый результат, а срок окупаемости показывает время возврата первоначальных вложений.</p>'
