                'caption' => 'Распределение стоимости долгосрочного актива на период его использования.',
                'definition' => '<p><strong>Амортизация</strong> — это метод распределения стоимости долгосрочного актива между периодами его использования. В экономическом анализе майнинга она помогает учитывать тот факт, что оборудование имеет ограниченный срок эксплуатации и постепенно теряет экономическую ценность.</p>

                <p>Амортизация не обязательно означает фактическую выплату денег в момент её начисления. Это важное отличие от непосредственных денежных расходов, таких как оплата электроэнергии.</p>

                <h3>Амортизация в расчётах майнинга</h3>

                <p>При долгосрочном анализе стоимость оборудования может распределяться на расчётный срок полезного использования. Размер начислений зависит от первоначальной стоимости, ожидаемого срока эксплуатации, остаточной стоимости и выбранного метода.</p>

                <p>Для майнингового оборудования срок экономической полезности может быть меньше физического срока работы из-за появления более эффективных поколений устройств, изменения сложности сети и рыночных условий.</p>

                <p>Амортизация связана с <span class="term" data-term="mining-economics/equipment-depreciation">амортизацией оборудования</span>, но общий термин может применяться и к другим долгосрочным активам инфраструктуры.</p>'
