                'name' => 'Амортизация оборудования',
                'caption' => 'Распределение стоимости майнингового оборудования на период его использования.',
                'definition' => '<p><strong>Амортизация оборудования</strong> — это распределение стоимости майнеров и других долгосрочных технических активов между периодами их использования.</p>

                <p>Для майнинга показатель особенно важен, поскольку вычислительное оборудование быстро меняется с точки зрения экономической эффективности. Новый майнер может иметь значительно более высокую энергоэффективность, из-за чего старое устройство теряет рыночную ценность даже при технической работоспособности.</p>

                <h3>Что влияет на амортизацию</h3>

                <ul>
                    <li>первоначальная стоимость оборудования;</li>
