                <p>В отличие от простого расчёта дохода, рентабельность требует учитывать расходы. Для майнера особенно важны цена электроэнергии, потребление, хешрейт, энергоэффективность, стоимость размещения, обслуживание, комиссии и текущие параметры сети.</p>

