                <p>В контексте майнинга вычет может иметь значение при расчёте налоговых обязательств бизнеса, если соответствующее законодательство позволяет учитывать определённые расходы, инвестиции или иные основания.</p>

                <h3>Вычет и расход</h3>

                <p>Налоговый вычет не следует автоматически считать обычным расходом майнинговой операции. Расход уменьшает экономический результат, а налоговый вычет влияет на расчёт налога в соответствии с установленными правилами.</p>

                <p>В некоторых системах вместо термина «вычет» применяются понятия налогового кредита, освобождения, льготы или уменьшения налоговой базы. Их экономический эффект и порядок применения могут различаться.</p>

                <p>При построении модели налоговой нагрузки необходимо учитывать <span class="term" data-term="mining-economics/tax-base">налоговую базу</span>, <span class="term" data-term="mining-economics/tax-rate">ставку налога</span> и конкретные правила соответствующей юрисдикции.</p>'
