                <p>После создания транзакция обычно распространяется по сети и проходит проверку. В UTXO-моделях она состоит из <span class="term" data-term="blockchain/transaction-input">входов</span> и <span class="term" data-term="blockchain/transaction-output">выходов</span>. В account-based сетях структура отличается и обычно содержит адрес отправителя, получателя, значение, nonce и данные вызова.</p>

