                <p>Классическая особенность soft форк состоит в том, что блоки, соответствующие новым более строгим правилам, могут оставаться допустимыми для узлов, которые не требуют полного обновления, хотя такие узлы могут не проверять новые ограничения самостоятельно.</p>

