                <p>В зависимости от типа узел может хранить полную историю, проверять транзакции и блоки, распространять данные другим участникам или получать только ограниченный набор информации. Архитектура узлов определяется конкретным протоколом.</p>

                <h3>Основные функции</h3>

                <ul>
                    <li>приём и проверка транзакций;</li>
                    <li>приём и проверка блоков;</li>
