                'caption' => 'Узел, способный самостоятельно проверять данные блокчейна по правилам протокола.',
                'definition' => '<p><strong>Полный узел</strong> — разновидность <span class="term" data-term="blockchain/blockchain-node">узла блокчейна</span>, который самостоятельно проверяет поступающие блоки и транзакции в соответствии с правилами конкретного протокола.</p>

                <p>Полный узел обычно хранит значительный объём данных и поддерживает состояние сети, необходимое для проверки новых операций. В некоторых реализациях можно использовать режим архивного хранения, при котором сохраняется больше исторических данных.</p>

                <h3>Зачем нужен полный узел</h3>

                <p>Самостоятельная проверка позволяет не полагаться исключительно на сторонний сервер при определении того, какие блоки и транзакции допустимы. Узел может самостоятельно отклонять данные, нарушающие правила протокола.</p>

                <p>Требования к полному узлу зависят от блокчейна: важны размер базы данных, скорость синхронизации, производительность накопителя, память и пропускная способность сети.</p>'
