                <p>Без механизма консенсуса независимые узлы могли бы постоянно поддерживать разные версии истории. Консенсус определяет правила выбора допустимых блоков, разрешения конкурирующих цепочек и принятия новых изменений состояния.</p>

                <h3>Консенсус и правила протокола</h3>

                <p>Механизм консенсуса является частью более широкой системы правил. Например, в сетях с Proof-of-Work участники используют вычислительную работу, а в Proof-of-Stake выбор блоков связан с долей, участвующей в обеспечении сети.</p>

                <p>Консенсус не означает, что каждый узел голосует за каждый блок в буквальном смысле. Конкретная архитектура определяется <span class="term" data-term="blockchain/consensus-mechanism">механизмом консенсуса</span> конкретного блокчейна.</p>'
