                <p>Механизм отвечает за вопросы о том, кто может предлагать новые блоки, как остальные участники их проверяют, какая цепочка считается актуальной и каким образом сеть сопротивляется попыткам нарушить правила.</p>

                <h3>Примеры</h3>

