                'definition' => '<p><strong>Криптовалюта</strong> — это цифровой актив, существование, передача и учет которого обеспечиваются криптографическими методами и правилами распределенной сети. В большинстве современных проектов история операций хранится в <span class="term" data-term="blockchain/blockchain">блокчейне</span>, а корректность новых записей определяется механизмом <span class="term" data-term="blockchain/consensus">консенсуса</span>.</p>

