                'definition' => '<p><strong>Стейблкоин (stablecoin)</strong> — это криптоактив, предназначенный для поддержания относительно стабильной стоимости по отношению к определенному ориентиру. Чаще всего таким ориентиром является национальная валюта, например доллар США, но возможны и другие модели.</p>

                <p>Стейблкоины используются для расчетов, хранения ликвидности, торговли и операций в <span class="term" data-term="defi/defi">DeFi</span>. Они позволяют использовать блокчейн-инфраструктуру без постоянной необходимости конвертировать волатильные криптоактивы в традиционные деньги.</p>

