            'wrapped-token' => [
                'title' => 'Что такое wrapped-токен | TM Wiki',
                'description' => 'Wrapped-токен — представление одного актива в другой блокчейн-среде. Разбираем обеспечение, выпуск и риски обернутых токенов.',
                'name' => 'Wrapped-токен',
                'caption' => 'Токенизированное представление другого актива в совместимой блокчейн-среде.',
                'definition' => '<p><strong>Wrapped-токен</strong> — это токен, который представляет другой актив в блокчейне или стандарте, где исходный актив напрямую не поддерживается.</p>

                <p>Классическая модель предполагает блокировку или хранение исходного актива и выпуск соответствующего количества токенов в другой сети. При обратной операции wrapped-токены погашаются, а исходный актив высвобождается.</p>

                <h3>Зачем нужны wrapped-токены</h3>

                <p>Они позволяют использовать актив в приложениях и протоколах, которые не могут напрямую работать с его исходной нативной формой. Например, представление актива в формате определенного блокчейна может сделать его доступным для <span class="term" data-term="defi/liquidity-pool">пулов ликвидности</span>, кредитных протоколов и других приложений.</p>

                <h3>Обеспечение и риски</h3>

                <p>Надежность wrapped-токена зависит от механизма обеспечения и инфраструктуры, которая связывает представленный актив с оригиналом. Риск может возникать из-за централизованного хранителя, смарт-контракта, моста или другого компонента системы.</p>

                <p>Поэтому wrapped-токен не следует автоматически считать полностью эквивалентным исходному активу: его стоимость и возможность погашения зависят от конкретной реализации.</p>'
            ],

            'tokenomics' => [
                'title' => 'Что такое токеномика | TM Wiki',
                'description' => 'Токеномика описывает экономическую модель криптоактива: эмиссию, предложение, распределение, стимулы и механизмы сжигания.',
                'name' => 'Токеномика',
                'caption' => 'Экономическая модель выпуска, распределения и использования криптоактива.',
                'definition' => '<p><strong>Токеномика (tokenomics)</strong> — это совокупность экономических правил и параметров, определяющих создание, распределение, обращение и использование криптоактива.</p>

                <p>Токеномика показывает, откуда берется предложение актива, кто его получает, с какой скоростью новые единицы поступают в обращение и какие механизмы могут уменьшать или увеличивать доступное предложение.</p>

                <h3>Основные параметры токеномики</h3>

                <ul>
                    <li><span class="term" data-term="cryptocurrency/total-supply">total supply</span> — общее количество созданных единиц;</li>
                    <li><span class="term" data-term="cryptocurrency/max-supply">max supply</span> — установленный максимальный объем, если он существует;</li>
                    <li><span class="term" data-term="cryptocurrency/circulating-supply">circulating supply</span> — количество единиц в обращении;</li>
                    <li><span class="term" data-term="cryptocurrency/emission">эмиссия</span> — выпуск новых единиц;</li>
                    <li><span class="term" data-term="cryptocurrency/token-burn">сжигание</span> — уменьшение количества доступных единиц;</li>
                    <li>распределение токенов между пользователями, командой, инвесторами и казначейством;</li>
                    <li>график разблокировки и выпуска токенов.</li>
                </ul>

                <h3>Почему токеномика важна</h3>

                <p>Экономическая модель влияет на потенциальное изменение предложения и стимулы участников. Например, большое количество токенов, заблокированных у команды или ранних инвесторов, может означать будущие изменения доступного предложения после разблокировки.</p>

                <p>Токеномика не определяет цену актива напрямую. Рыночная стоимость также зависит от спроса, ликвидности, использования проекта и общего состояния рынка.</p>'
            ],

            'total-supply' => [
                'title' => 'Что такое total supply | TM Wiki',
                'description' => 'Total supply — общее количество существующих единиц криптоактива с учетом правил конкретного протокола и сжигания.',
                'name' => 'Total Supply',
                'caption' => 'Общее количество единиц криптоактива, существующих согласно его правилам учета.',
                'definition' => '<p><strong>Total supply</strong> — это общее количество единиц криптоактива, которые существуют в соответствии с правилами конкретного протокола или токена на определенный момент времени.</p>

                <p>Показатель может учитывать как единицы, находящиеся в обращении, так и токены, которые заблокированы, принадлежат контрактам или временно недоступны пользователям. Точное определение зависит от методологии проекта и используемого сервиса.</p>

                <h3>Total supply и circulating supply</h3>

                <p><span class="term" data-term="cryptocurrency/circulating-supply">Circulating supply</span> обычно отражает количество актива, доступное рынку и находящееся в обращении. Total supply является более широким показателем и может включать токены вне свободного обращения.</p>

                <p>Например, если проект создал 1 миллиард токенов, но часть из них находится в заблокированном состоянии, total supply может быть выше circulating supply.</p>

                <h3>Связь с токеномикой</h3>

                <p>Total supply может изменяться вследствие дополнительной эмиссии или <span class="term" data-term="cryptocurrency/token-burn">сжигания токенов</span>. Поэтому показатель необходимо рассматривать вместе с правилами выпуска актива.</p>'
            ],

            'max-supply' => [
                'title' => 'Что такое max supply | TM Wiki',
                'description' => 'Max supply — максимальное количество единиц криптоактива, предусмотренное его протоколом или экономической моделью.',
                'name' => 'Max Supply',
                'caption' => 'Максимальное количество единиц актива, которое может существовать по установленным правилам.',
                'definition' => '<p><strong>Max supply</strong> — это максимальное количество единиц криптоактива, которое может существовать согласно правилам его протокола или экономической модели.</p>

                <p>Не у каждого криптоактива существует фиксированный максимальный запас. Некоторые протоколы предусматривают жесткий предел, другие допускают неограниченную или условно ограниченную эмиссию.</p>

                <h3>Max supply и другие показатели предложения</h3>

                <p><span class="term" data-term="cryptocurrency/circulating-supply">Circulating supply</span> показывает объем актива в обращении, а <span class="term" data-term="cryptocurrency/total-supply">total supply</span> — общее количество существующих единиц согласно используемой методологии. Max supply представляет потенциальный верхний предел.</p>

                <p>Если max supply равен 21 миллиону, это означает, что при сохранении соответствующих правил протокол не должен создать больше указанного количества. Однако для некоторых проектов правила могут изменяться посредством обновления протокола или управления.</p>

                <h3>Почему max supply важен</h3>

                <p>Предел предложения является одним из параметров токеномики. Сам по себе низкий max supply не гарантирует высокую стоимость актива: экономический результат зависит также от спроса, распределения токенов, полезности и ликвидности.</p>'
            ],

            'circulating-supply' => [
                'title' => 'Что такое circulating supply | TM Wiki',
                'description' => 'Circulating supply — количество криптоактива в обращении. Показатель используется при расчете рыночной капитализации.',
                'name' => 'Circulating Supply',
                'caption' => 'Количество единиц криптоактива, находящихся в обращении и доступных рынку.',
                'definition' => '<p><strong>Circulating supply</strong> — это оценка количества единиц криптоактива, которые находятся в обращении и считаются доступными рынку на определенный момент времени.</p>

                <p>Показатель используется, в частности, для расчета <span class="term" data-term="cryptocurrency/market-capitalization">рыночной капитализации</span>. В простейшем виде она рассчитывается как цена одной единицы, умноженная на circulating supply.</p>

                <h3>Что может не входить в circulating supply</h3>

                <p>В зависимости от методологии из обращения могут исключаться заблокированные токены команды, резервные средства, еще не выпущенные единицы, некоторые активы в смарт-контрактах или другие объемы, которые не считаются свободно обращающимися.</p>

                <p>Поэтому значения circulating supply у разных аналитических сервисов иногда отличаются.</p>

                <h3>Изменение предложения</h3>

                <p>Circulating supply может увеличиваться при выпуске новых токенов или разблокировке ранее недоступных единиц. Он может уменьшаться при сжигании токенов или в зависимости от методологии учета.</p>

                <p>Этот показатель не следует путать с <span class="term" data-term="cryptocurrency/total-supply">total supply</span> и <span class="term" data-term="cryptocurrency/max-supply">max supply</span>.</p>'
            ],

            'emission' => [
