                'definition' => '<p><strong>Эмиссия</strong> — это процесс создания новых единиц криптовалюты или токена в соответствии с правилами протокола или экономической модели.</p>

                <p>Механизм эмиссии зависит от конкретного проекта. В сетях с <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> новые монеты могут создаваться в составе вознаграждения за найденные блоки. В сетях с Proof-of-Stake выпуск может быть связан с вознаграждением валидаторов.</p>

                <h3>Эмиссия и предложение</h3>

                <p>Эмиссия увеличивает количество существующих единиц, если она не компенсируется механизмом сжигания. Поэтому для анализа предложения важно учитывать не только объем нового выпуска, но и уничтожение или потерю единиц.</p>

                <p>Некоторые протоколы используют заранее определенный график выпуска. Другие могут изменять темп эмиссии в зависимости от состояния сети, участия валидаторов или решений управления.</p>

                <h3>Эмиссия в майнинге</h3>

