                <p>Условно годовой темп инфляции можно оценить как отношение чистого прироста предложения за период к предложению в начале периода. В реальных протоколах расчет может учитывать дополнительные правила выпуска и сжигания.</p>

                <h3>Эмиссия и чистая инфляция</h3>

                <p>Новая эмиссия не всегда означает одинаковый чистый рост предложения. Если одновременно происходит <span class="term" data-term="cryptocurrency/token-burn">сжигание</span> части активов, итоговое предложение может расти медленнее или даже уменьшаться.</p>

