                <p>Темп выпуска влияет на распределение новых единиц между участниками и может изменять долю существующего владельца в общем предложении. Однако сама инфляция не определяет цену актива: на нее одновременно влияют спрос, полезность, ликвидность и другие экономические факторы.</p>'
            ],

