                <p>К криптоактивам могут относиться <span class="term" data-term="cryptocurrency/coin">монеты</span>, <span class="term" data-term="cryptocurrency/token">токены</span>, стейблкоины и другие виды цифровых активов. Конкретная классификация зависит от технических характеристик и контекста.</p>

                <h3>Криптоактив и криптовалюта</h3>

                <p>Термины часто используются как взаимозаменяемые, но «криптоактив» является более широким понятием. Криптовалюта обычно ассоциируется с активом, используемым как средство передачи стоимости или расчетная единица, тогда как криптоактив может выполнять дополнительные функции.</p>

