            'market-capitalization' => [
                'title' => 'Что такое капитализация криптовалюты | TM Wiki',
                'description' => 'Рыночная капитализация криптовалюты — цена актива, умноженная на количество монет в обращении. Разбираем формулу и ограничения.',
                'name' => 'Рыночная капитализация',
                'caption' => 'Расчетная стоимость криптоактива на основе его цены и предложения в обращении.',
                'definition' => '<p><strong>Рыночная капитализация (market capitalization)</strong> — расчетный показатель, который показывает стоимость криптоактива на основе его рыночной цены и количества единиц в обращении.</p>

                <p>Базовая формула имеет вид:</p>

                <p><strong>Market Cap = Цена × Circulating Supply</strong></p>

                <p>Например, если актив стоит $10, а в обращении находится 20 миллионов единиц, его расчетная рыночная капитализация составляет $200 миллионов.</p>

                <h3>Почему капитализация используется в криптовалютах</h3>

                <p>Цена отдельной монеты без учета предложения мало говорит о масштабе актива. Монета стоимостью $1 может иметь намного больше единиц в обращении, чем монета стоимостью $1000. Рыночная капитализация позволяет учитывать оба параметра.</p>

                <h3>Ограничения показателя</h3>

                <p>Market cap является расчетным показателем, а не суммой денег, которая фактически была вложена в актив. Чтобы продать весь объем по текущей цене, рынок должен иметь соответствующую ликвидность, чего на практике обычно нет.</p>

                <p>Расчет также зависит от корректности данных о <span class="term" data-term="cryptocurrency/circulating-supply">circulating supply</span>. Разные сервисы могут использовать разные методологии определения обращения.</p>

                <p>Для оценки потенциальной стоимости актива при полном выпуске используется <span class="term" data-term="cryptocurrency/fully-diluted-valuation">fully diluted valuation</span>.</p>'
            ],

            'fully-diluted-valuation' => [
                'title' => 'Что такое FDV криптовалюты | TM Wiki',
                'description' => 'FDV — расчетная оценка стоимости криптоактива при его полной потенциальной эмиссии. Разбираем формулу и отличие от market cap.',
                'name' => 'Fully Diluted Valuation',
                'caption' => 'Расчетная стоимость актива при условии учета всего потенциального предложения.',
                'definition' => '<p><strong>Fully Diluted Valuation (FDV)</strong> — расчетный показатель, который оценивает стоимость криптоактива при условии, что учитывается весь объем предложения, предусмотренный его экономической моделью.</p>

                <p>Упрощенная формула выглядит следующим образом:</p>

                <p><strong>FDV = Текущая цена × Max Supply</strong></p>

                <p>Если максимального предложения не существует или оно определяется сложной динамической моделью, расчет FDV может зависеть от используемой методологии.</p>

                <h3>FDV и market cap</h3>

                <p><span class="term" data-term="cryptocurrency/market-capitalization">Market capitalization</span> обычно рассчитывается на основе circulating supply, тогда как FDV использует весь потенциальный объем предложения.</p>

                <p>Например, если токен стоит $2, в обращении находится 100 миллионов единиц, а максимальное предложение составляет 1 миллиард, market cap составляет $200 миллионов, а FDV — $2 миллиарда.</p>

                <h3>Почему разница имеет значение</h3>

                <p>Большая разница между market cap и FDV может означать, что значительная часть токенов еще не находится в обращении. Будущая эмиссия или разблокировка таких токенов может изменить структуру предложения и доли существующих владельцев.</p>

                <p>FDV не является прогнозом будущей рыночной капитализации. Это расчетная величина при текущей цене и предполагаемом полном предложении.</p>'
