                <h3>Как происходит торговая операция</h3>

                <p>На бирже пользователь размещает <span class="term" data-term="crypto-trading/order-book">ордер</span>, который попадает в книгу заявок. В зависимости от типа ордера сделка может быть исполнена немедленно по доступным ценам или ждать появления встречной заявки. На итоговую цену исполнения могут влиять <span class="term" data-term="crypto-trading/spread">спред</span>, ликвидность рынка и <span class="term" data-term="crypto-trading/slippage">проскальзывание</span>.</p>

