                <h3>Как формируется цена</h3>

                <p>Цена на спотовом рынке формируется через взаимодействие заявок покупателей и продавцов в <span class="term" data-term="crypto-trading/order-book">книге ордеров</span>. Заявки могут исполняться по рыночной или заданной пользователем цене.</p>

