                <p>Для получения заемных средств трейдер предоставляет <span class="term" data-term="crypto-trading/margin">маржу</span> в качестве обеспечения. Размер доступной позиции относительно собственного капитала определяется уровнем <span class="term" data-term="crypto-trading/leverage">кредитного плеча</span>.</p>

                <h3>Пример</h3>

                <p>Если трейдер располагает $1 000 и использует плечо 5x, номинальный размер позиции может составлять около $5 000. Изменение цены на 1% относительно позиции соответствует примерно $50 изменения результата до учета комиссий, процентов и других расходов.</p>

                <p>Та же механика работает в обратную сторону: убыток рассчитывается относительно увеличенной позиции и поэтому быстрее уменьшает собственный капитал трейдера.</p>

                <h3>Ликвидация</h3>

                <p>Если стоимость обеспечения становится недостаточной для поддержания позиции, торговая площадка может закрыть ее принудительно. Такой процесс называется <span class="term" data-term="crypto-trading/liquidation">ликвидацией</span>.</p>

                <p>Конкретные правила зависят от биржи, типа маржи, режима позиции и используемого инструмента. Поэтому одинаковое плечо на разных площадках не обязательно означает одинаковый уровень риска.</p>'
            ],

