                <p>Фьючерсный контракт определяет условия расчета между сторонами. В зависимости от конструкции он может предусматривать поставку базового актива или денежный расчет. На криптовалютных площадках широко используются контракты с расчетом в цифровом активе или стейблкоине.</p>

