                <p>Цена ликвидации зависит от направления позиции, размера позиции, внесенной <span class="term" data-term="crypto-trading/margin">маржи</span>, используемого <span class="term" data-term="crypto-trading/leverage">плеча</span>, maintenance margin, комиссий и других правил торговой платформы.</p>

