                'definition' => '<p><strong>Ask</strong> — это цена, по которой продавец готов продать актив. В книге ордеров ask обозначает сторону заявок на продажу.</p>

                <p><strong>Best ask</strong> — самая низкая доступная цена среди активных заявок продавцов. Например, если продавцы предлагают актив по $60 100, $60 050 и $60 000, лучшим ask будет $60 000.</p>

                <h3>Ask и bid</h3>

                <p>Противоположную сторону формируют <span class="term" data-term="crypto-trading/bid">bid</span>-заявки покупателей. Разница между лучшими значениями ask и bid образует <span class="term" data-term="crypto-trading/spread">спред</span>.</p>

                <p>Рыночный ордер на покупку обычно исполняется против доступных ask-заявок. Если объем покупки превышает количество активов на лучшем ask, заявка может перейти на следующие уровни цены.</p>'
            ],

            'trading-volume' => [
                'title' => 'Что такое объем торгов | TM Wiki',
                'description' => 'Объем торгов показывает количество или стоимость активов, которыми торговали за период. Разбираем расчет и ограничения показателя.',
                'name' => 'Объем торгов',
                'caption' => 'Объем активов или их денежная стоимость, прошедшие через сделки за определенный период.',
                'definition' => '<p><strong>Объем торгов (trading volume)</strong> — это показатель количества или денежной стоимости активов, по которым были совершены сделки за определенный период.</p>

                <p>На криптовалютных рынках объем часто указывается в базовом активе или в котируемой валюте, например USDT. Период может составлять одну минуту, час, сутки или другой интервал.</p>

                <h3>Что показывает объем</h3>

                <p>Объем позволяет оценивать торговую активность рынка. Рост объема означает, что за рассматриваемый период было заключено больше сделок или проторгован больший номинальный объем.</p>

                <p>Однако высокий объем не означает автоматически высокую <span class="term" data-term="crypto-trading/market-depth">глубину рынка</span>. Объем отражает уже совершенные сделки, тогда как глубина показывает доступные заявки в текущей книге ордеров.</p>

                <h3>Ограничения</h3>

                <p>Разные биржи могут показывать разные объемы по одному активу. Кроме того, качество данных зависит от методологии учета, торговой площадки и выбранного периода.</p>'
            ],

            'volatility' => [
                'title' => 'Что такое волатильность | TM Wiki',
