                'caption' => 'Степень и скорость изменения рыночной цены за определенный период.',
                'definition' => '<p><strong>Волатильность (volatility)</strong> — это характеристика изменчивости цены или доходности актива за определенный период. Чем сильнее и чаще цена отклоняется от своего среднего или предыдущего значения, тем выше наблюдаемая волатильность.</p>

                <p>В криптовалютных рынках волатильность может быть значительно заметной из-за непрерывной торговли, изменения ликвидности, новостей, рыночных ожиданий и других факторов.</p>

                <h3>Историческая и подразумеваемая волатильность</h3>

                <p><strong>Историческая волатильность</strong> рассчитывается на основе уже наблюдавшихся изменений цены. <strong>Подразумеваемая волатильность</strong> используется преимущественно на рынке опционов и отражает ожидания, заложенные в рыночные цены опционных контрактов.</p>

                <h3>Волатильность и риск</h3>

                <p>Высокая волатильность означает, что цена может быстро пройти значительное расстояние. Для трейдера это увеличивает как возможности для изменения результата, так и риск неблагоприятного движения.</p>

                <p>При торговле с <span class="term" data-term="crypto-trading/leverage">плечом</span> высокая волатильность особенно важна, поскольку резкое движение может быстро приблизить позицию к <span class="term" data-term="crypto-trading/liquidation">ликвидации</span>.</p>'
