            'funding-rate' => [
                'title' => 'Что такое funding rate | TM Wiki',
                'description' => 'Funding rate — периодический платеж между участниками бессрочных фьючерсов. Разбираем механизм и влияние на позиции.',
                'name' => 'Funding Rate',
                'caption' => 'Ставка периодического финансирования между сторонами бессрочного фьючерсного рынка.',
                'definition' => '<p><strong>Funding rate</strong> — это ставка, определяющая периодические платежи между участниками рынка <span class="term" data-term="crypto-trading/perpetual-futures">бессрочных фьючерсов</span>.</p>

                <p>Механизм funding используется для того, чтобы цена бессрочного контракта оставалась связанной со спотовой ценой базового актива. Если контракт значительно отклоняется от спотового рынка, funding может создавать экономический стимул для изменения структуры открытых позиций.</p>

                <h3>Как работает funding</h3>

                <p>В зависимости от значения ставки одна сторона рынка платит другой. При положительной ставке в распространенной модели long-позиции платят short-позициям. При отрицательной ставке направление платежа меняется.</p>

                <p>Фактические правила, интервалы и формулы рассчитываются каждой торговой площадкой самостоятельно.</p>

                <h3>Влияние на трейдера</h3>

                <p>Если позиция удерживается в течение нескольких периодов funding, полученные или уплаченные суммы влияют на итоговый финансовый результат. Поэтому доходность бессрочной позиции нельзя оценивать только по изменению цены.</p>

                <p>Funding rate является платежом между участниками рынка и не следует автоматически приравнивать к обычной торговой комиссии биржи.</p>'
