                'description' => 'Open interest показывает объем открытых деривативных позиций. Разбираем OI, его изменение и отличие от торгового объема.',
                'name' => 'Open Interest',
                'caption' => 'Объем открытых деривативных контрактов, которые еще не были закрыты.',
                'definition' => '<p><strong>Open interest (OI)</strong> — это показатель количества или номинальной стоимости открытых деривативных контрактов, которые остаются активными и еще не были закрыты, погашены или исполнены.</p>

                <p>Показатель особенно используется на фьючерсных и других деривативных рынках. Он отражает накопленный объем открытых позиций, а не количество сделок, совершенных за конкретный период.</p>

                <h3>Open interest и торговый объем</h3>

                <p><span class="term" data-term="crypto-trading/trading-volume">Торговый объем</span> показывает объем совершенных сделок за период. Open interest показывает объем контрактов, которые остаются открытыми.</p>

                <p>Например, если два трейдера открыли новый фьючерсный контракт, open interest увеличивается. Если существующая позиция полностью закрывается встречной операцией, open interest уменьшается. Простая смена владельца позиции может иметь другой эффект в зависимости от механики сделки.</p>

                <h3>Как используется OI</h3>

                <p>Трейдеры используют open interest для оценки количества капитала и позиций, задействованных в деривативном рынке. Изменение OI часто рассматривается вместе с ценой, объемом и <span class="term" data-term="crypto-trading/funding-rate">funding rate</span>.</p>

                <p>Сам по себе рост или снижение open interest не показывает направление будущего движения цены. OI характеризует структуру открытых контрактов, а не гарантированный прогноз рынка.</p>'
            ],
