                <p>Для пользователя операция может выглядеть как перевод на персональный <span class="term" data-term="crypto-exchanges/deposit-address">адрес депозита</span>, хотя технически средства могут поступать в общий кошелёк или систему адресов биржи. Баланс клиента после подтверждения <span class="term" data-term="crypto-trading/transaction">транзакции</span> учитывается во внутренней базе биржи.</p>

                <p>Биржи применяют различные архитектуры хранения, включая горячие и холодные кошельки. Управление ключами является критически важной частью безопасности, поскольку компрометация инфраструктуры хранения может привести к потере активов. Для пользователя также важно понимать разницу между кастодиальным хранением и <span class="term" data-term="crypto-wallet/self-custody">самостоятельным хранением</span>.</p>'
            ],

            'deposit' => [
                'title' => 'Что такое депозит на криптобирже | TM Wiki',
                'description' => 'Депозит — внесение криптоактивов или фиатных средств на биржевой аккаунт для торговли и других операций.',
                'name' => 'Депозит',
                'caption' => 'Пополнение баланса криптобиржи.',
                'definition' => '<p><strong>Депозит</strong> — это операция пополнения баланса на криптобирже. В зависимости от платформы депозитом может быть перевод криптовалюты на указанный <span class="term" data-term="crypto-exchanges/deposit-address">адрес депозита</span> или внесение фиатных средств через поддерживаемый платёжный метод.</p>

                <p>При криптовалютном депозите пользователь выбирает актив и соответствующую сеть, после чего получает адрес или другой идентификатор для перевода. Отправитель создаёт <span class="term" data-term="blockchain/transaction">транзакцию</span>, которая после включения в <span class="term" data-term="blockchain/block">блок</span> и получения необходимого числа подтверждений может быть зачислена биржей.</p>

                <h3>Что важно проверить перед депозитом</h3>
                <ul>
                    <li>правильный актив;</li>
                    <li>совместимую сеть;</li>
                    <li>адрес получателя;</li>
                    <li>memo, tag или другой дополнительный идентификатор, если он требуется;</li>
                    <li>минимальную сумму депозита.</li>
                </ul>

                <p>Ошибочный адрес или несовместимая сеть могут привести к задержке или потере средств. Поэтому параметры депозита необходимо проверять непосредственно перед отправкой.</p>'
            ],

            'deposit-address' => [
                'title' => 'Что такое адрес депозита | TM Wiki',
                'description' => 'Адрес депозита — блокчейн-адрес, который биржа предоставляет для пополнения пользовательского баланса определённым активом.',
                'name' => 'Адрес депозита',
                'caption' => 'Адрес для отправки криптовалюты на биржу.',
                'definition' => '<p><strong>Адрес депозита</strong> — это <span class="term" data-term="crypto-wallet/wallet-address">адрес кошелька</span>, который криптобиржа предоставляет пользователю для получения определённого <span class="term" data-term="cryptocurrency/crypto-asset">криптоактива</span>.</p>

                <p>Адрес связан с конкретной блокчейн-сетью или стандартом токена. Например, один и тот же внешний вид адреса не означает, что любой актив можно безопасно отправить через любую сеть. Для токенов на смарт-контрактных платформах важно выбрать поддерживаемую сеть, а для некоторых активов требуется дополнительный memo или tag.</p>

                <p>После отправки средства перемещаются по <span class="term" data-term="blockchain/blockchain">блокчейну</span>. Биржа отслеживает соответствующие <span class="term" data-term="blockchain/transaction">транзакции</span> и после выполнения внутренних условий зачисляет депозит на пользовательский баланс.</p>

                <p>Перед отправкой необходимо проверить адрес, актив и сеть. Отправка на неподдерживаемую сеть или неправильный адрес может привести к невозможности автоматического зачисления средств.</p>'
            ],

            'trading-fee' => [
                'title' => 'Что такое торговая комиссия | TM Wiki',
                'description' => 'Торговая комиссия — плата бирже за исполнение сделки или использование её торговой инфраструктуры.',
                'name' => 'Торговая комиссия',
                'caption' => 'Комиссия за совершение торговой операции.',
                'definition' => '<p><strong>Торговая комиссия</strong> — это плата, которую биржа взимает при исполнении торговой операции. Обычно она рассчитывается как процент от стоимости сделки, хотя конкретная модель зависит от площадки.</p>

                <p>Размер комиссии может зависеть от торгового продукта, объёма торгов пользователя, уровня аккаунта, типа ордера и роли участника. В биржевой модели часто выделяются <span class="term" data-term="crypto-exchanges/maker">maker</span> fee и <span class="term" data-term="crypto-exchanges/taker">taker</span> fee.</p>

                <p>Торговая комиссия непосредственно влияет на итоговый результат <span class="term" data-term="crypto-trading/crypto-trading">криптотрейдинга</span>. Для частых сделок даже небольшая комиссия может существенно влиять на совокупные расходы, особенно вместе со <span class="term" data-term="crypto-trading/spread">спредом</span> и <span class="term" data-term="crypto-trading/slippage">проскальзыванием</span>.</p>'
            ],

            'maker' => [
                'title' => 'Кто такой maker на криптобирже | TM Wiki',
                'description' => 'Maker — участник, чья заявка добавляет ликвидность в стакан и не исполняется немедленно.',
