                'caption' => 'Участник, добавляющий ликвидность в стакан.',
                'definition' => '<p><strong>Maker</strong> — участник рынка, чья заявка добавляет ликвидность в <span class="term" data-term="crypto-trading/order-book">стакан заявок</span>. Обычно такая заявка не исполняется немедленно и ожидает появления встречной заявки.</p>

                <p>Maker чаще всего использует <span class="term" data-term="crypto-trading/limit-order">лимитные ордера</span>, задавая цену, по которой готов купить или продать актив. Если заявка остаётся в книге и затем исполняется другой стороной, участник получает статус maker для соответствующей части сделки.</p>

                <p>Maker и <span class="term" data-term="crypto-exchanges/taker">taker</span> — это роли конкретного исполнения, а не постоянные характеристики аккаунта. Один и тот же трейдер может быть maker в одной сделке и taker в другой.</p>'
