                'caption' => 'Участник, который забирает ликвидность из стакана.',
                'definition' => '<p><strong>Taker</strong> — участник рынка, чья заявка немедленно исполняется против уже существующих заявок в <span class="term" data-term="crypto-trading/order-book">стакане</span>. Такая операция уменьшает доступную ликвидность на соответствующих ценовых уровнях.</p>

                <p>Рыночные ордера обычно исполняются как taker. Лимитная заявка также может получить статус taker, если она сразу пересекает текущий <span class="term" data-term="crypto-trading/bid">bid</span> или <span class="term" data-term="crypto-trading/ask">ask</span>.</p>

