                'name' => 'Сопоставление ордеров',
                'caption' => 'Механизм соединения встречных заявок на рынке.',
                'definition' => '<p><strong>Сопоставление ордеров</strong> — это процесс поиска совместимых заявок покупателей и продавцов на торговой площадке. На централизованной бирже он обычно выполняется автоматизированной системой, называемой <span class="term" data-term="crypto-exchanges/matching-engine">matching engine</span>.</p>

                <p>Заявки организуются в <span class="term" data-term="crypto-trading/order-book">стакане</span> по цене и времени размещения. Для покупателей важен <span class="term" data-term="crypto-trading/bid">bid</span>, а для продавцов — <span class="term" data-term="crypto-trading/ask">ask</span>. Когда условия двух заявок совпадают, система создаёт сделку.</p>

                <h3>Приоритет исполнения</h3>
                <p>Распространённой моделью является приоритет цены, а затем времени. Более выгодная цена получает преимущество, а при одинаковой цене раньше размещённая заявка обычно исполняется раньше. Конкретные правила определяются биржей.</p>'
