                'caption' => 'Система автоматического исполнения биржевых заявок.',
                'definition' => '<p><strong>Matching engine</strong> — это программная система криптобиржи, которая обрабатывает торговые заявки и определяет, какие из них могут быть исполнены друг против друга.</p>

                <p>Движок поддерживает состояние <span class="term" data-term="crypto-trading/order-book">стакана заявок</span>, учитывает цену и другие правила приоритета и создаёт сделки при появлении совместимых ордеров. От его производительности зависят задержки обработки, пропускная способность и способность биржи обслуживать высокий <span class="term" data-term="crypto-trading/trading-volume">объём торгов</span>.</p>

                <p>После сопоставления система обновляет состояние заявок и пользовательских балансов. В централизованной архитектуре matching engine является одним из ключевых компонентов торговой инфраструктуры.</p>'
