                'name' => 'KYC',
                'caption' => 'Идентификация и проверка личности клиента.',
                'definition' => '<p><strong>KYC</strong> (Know Your Customer) — процедура идентификации и проверки личности клиента финансового сервиса. На централизованных криптобиржах KYC может быть необходим для доступа к определённым функциям, лимитам или операциям.</p>

                <p>Процедура может включать предоставление имени, даты рождения, документа, удостоверяющего личность, подтверждения адреса и других сведений. Конкретные требования зависят от юрисдикции и политики биржи.</p>

                <p>KYC является частью более широкой системы контроля рисков и может использоваться вместе с <span class="term" data-term="crypto-exchanges/aml">AML</span>. При этом KYC относится прежде всего к установлению и проверке личности клиента, а AML — к мерам противодействия отмыванию денег и связанным финансовым рискам.</p>'
