                'name' => 'AML',
                'caption' => 'Контроль операций для противодействия отмыванию денег.',
                'definition' => '<p><strong>AML</strong> (Anti-Money Laundering) — совокупность процедур и мер, направленных на предотвращение использования финансовой инфраструктуры для отмывания денег и других незаконных финансовых операций.</p>

                <p>На централизованных криптобиржах AML может включать мониторинг операций, анализ источников средств, выявление необычной активности, проверку клиентов и взаимодействие с компетентными органами в предусмотренных законом случаях.</p>

                <p>AML тесно связан с <span class="term" data-term="crypto-exchanges/kyc">KYC</span>, но эти понятия не идентичны. KYC устанавливает личность клиента, тогда как AML охватывает более широкий набор процедур мониторинга и контроля финансовой активности.</p>'
