                'description' => 'Proof of Reserves — метод подтверждения наличия у криптобиржи определённых резервов для покрытия заявленных активов клиентов.',
                'name' => 'Proof of Reserves',
                'caption' => 'Подтверждение резервов криптовалютной биржи.',
                'definition' => '<p><strong>Proof of Reserves</strong> (PoR) — подход, при котором криптобиржа предоставляет доказательства наличия определённых активов в контролируемых ею резервах. Цель такого подхода — повысить прозрачность информации о запасах биржи.</p>

                <p>Техническая реализация может включать публикацию адресов блокчейн-кошельков, криптографические доказательства пользовательских балансов или независимую проверку. В некоторых системах применяется <span class="term" data-term="security/cryptographic-hash">криптографическое хеширование</span> данных, позволяющее подтверждать включение информации в агрегированный набор без раскрытия всех деталей.</p>

                <p>Proof of Reserves не является автоматически полным доказательством финансового состояния биржи. Он может показывать наличие определённых активов, но не обязательно раскрывает все обязательства, долги, юридические требования и другие элементы баланса. Поэтому PoR следует рассматривать как отдельный инструмент прозрачности, а не как универсальную гарантию платёжеспособности.</p>'
