                'caption' => 'Способность рынка выполнять сделки с небольшим ценовым воздействием.',
                'definition' => '<p><strong>Ликвидность биржи</strong> — способность торговой площадки обеспечивать покупку и продажу значительных объёмов активов без существенного изменения цены. Ликвидность формируется совокупностью заявок участников рынка и зависит от конкретной торговой пары.</p>

                <p>Одним из основных источников информации о ликвидности является <span class="term" data-term="crypto-trading/order-book">стакан заявок</span>. Его <span class="term" data-term="crypto-trading/market-depth">глубина рынка</span> показывает, какой объём заявок доступен на различных ценовых уровнях.</p>

                <p>Высокая ликвидность обычно связана с меньшим <span class="term" data-term="crypto-trading/spread">спредом</span> и меньшим <span class="term" data-term="crypto-trading/slippage">проскальзыванием</span> для сопоставимых размеров сделок. Однако ликвидность может быстро меняться во время высокой <span class="term" data-term="crypto-trading/volatility">волатильности</span>.</p>

                <p>Ликвидность также следует отличать от <span class="term" data-term="crypto-trading/trading-volume">объёма торгов</span>. Большой объём показывает, сколько сделок или контрактов было проторговано за период, но сам по себе не гарантирует глубокий стакан и низкое ценовое воздействие крупной заявки.</p>'
