                'name' => 'Криптокошелёк',
                'caption' => 'Инструмент для управления криптоактивами и ключами.',
                'definition' => '<p><strong>Криптокошелёк</strong> — это программный, аппаратный или иной инструмент, который позволяет пользователю управлять криптоактивами через соответствующие <span class="term" data-term="crypto-wallet/private-key">приватные ключи</span> и формировать операции в <span class="term" data-term="blockchain/blockchain">блокчейне</span>. В отличие от обычного банковского счёта, кошелёк не хранит монеты или токены в буквальном смысле: активы остаются записанными в состоянии соответствующего блокчейна, а кошелёк предоставляет средства для управления правами на них.</p>

                <p>Ключевыми компонентами кошелька являются ключевой материал, <span class="term" data-term="crypto-wallet/wallet-address">адреса</span> и программная или аппаратная логика для создания и подписания <span class="term" data-term="blockchain/transaction">транзакций</span>. Для отправки средств кошелёк формирует транзакцию и использует <span class="term" data-term="crypto-wallet/transaction-signing">подпись транзакции</span>, подтверждающую владение соответствующим ключом.</p>

                <h3>Основные типы криптокошельков</h3>
                <ul>
                    <li><span class="term" data-term="crypto-wallet/hot-wallet">горячие кошельки</span> — постоянно или регулярно подключены к сети;</li>
