                    <li><span class="term" data-term="crypto-wallet/hardware-wallet">аппаратные кошельки</span> — используют отдельное физическое устройство;</li>
                    <li><span class="term" data-term="crypto-wallet/software-wallet">программные кошельки</span> — работают в приложении, браузере или операционной системе;</li>
                    <li><span class="term" data-term="crypto-wallet/custodial-wallet">кастодиальные кошельки</span> — предполагают хранение ключей третьей стороной;</li>
                    <li><span class="term" data-term="crypto-wallet/non-custodial-wallet">некастодиальные кошельки</span> — передают управление ключами непосредственно пользователю.</li>
                </ul>

                <p>Кошелёк может поддерживать одну или несколько блокчейн-сетей и различные типы активов, включая <span class="term" data-term="cryptocurrency/coin">монеты</span> и <span class="term" data-term="cryptocurrency/token">токены</span>. В зависимости от архитектуры он также может взаимодействовать со <span class="term" data-term="deFi/dapp">dApp</span>, смарт-контрактами, протоколами <span class="term" data-term="deFi/defi">DeFi</span> и системами <span class="term" data-term="staking/staking">стейкинга</span>.</p>

                <h3>Что на самом деле хранит кошелёк</h3>
                <p>Криптовалютные активы физически не перемещаются в файл или устройство кошелька. Блокчейн содержит сведения о состоянии адресов и принадлежащих им активах, а кошелёк хранит или использует секретные данные, необходимые для управления этими активами. Поэтому потеря ключевого материала может привести к потере доступа к средствам даже в том случае, если сами активы продолжают существовать в блокчейне.</p>

                <p>Безопасность кошелька во многом определяется защитой <span class="term" data-term="crypto-wallet/private-key">приватного ключа</span> или <span class="term" data-term="crypto-wallet/seed-phrase">seed-фразы</span>. Их компрометация может позволить злоумышленнику подписывать операции от имени владельца. Поэтому кошельки тесно связаны с понятиями <span class="term" data-term="security/private-key-security">безопасности приватного ключа</span>, резервного копирования и восстановления доступа.</p>'
            ],

            'hot-wallet' => [
