            'hardware-wallet' => [
                'title' => 'Что такое аппаратный криптокошелёк | TM Wiki',
                'description' => 'Аппаратный кошелёк — физическое устройство для хранения и использования приватных ключей при подписании криптовалютных операций.',
                'name' => 'Аппаратный кошелёк',
                'caption' => 'Физическое устройство для защиты криптографических ключей.',
                'definition' => '<p><strong>Аппаратный кошелёк</strong> — это специализированное физическое устройство, предназначенное для хранения или использования <span class="term" data-term="crypto-wallet/private-key">приватных ключей</span> и выполнения операций <span class="term" data-term="crypto-wallet/transaction-signing">подписания транзакций</span>. Его задача — отделить наиболее чувствительные ключевые данные от обычной операционной среды компьютера или смартфона.</p>

                <p>При выполнении операции приложение на компьютере или телефоне передаёт устройству необходимые данные. Аппаратный кошелёк использует защищённый ключ для создания цифровой подписи, после чего подписанная операция возвращается приложению для дальнейшей отправки в <span class="term" data-term="blockchain/blockchain">блокчейн</span>. В правильно спроектированной архитектуре приватный ключ не должен покидать устройство.</p>

                <h3>Почему аппаратные кошельки используют для хранения</h3>
                <ul>
                    <li>для изоляции приватных ключей от обычной операционной системы;</li>
