                    <li>для уменьшения риска кражи ключей вредоносным ПО;</li>
                    <li>для долгосрочного хранения криптоактивов;</li>
                    <li>для работы с несколькими блокчейнами и активами.</li>
                </ul>

                <p>Аппаратный кошелёк не отменяет необходимость защищать <span class="term" data-term="crypto-wallet/seed-phrase">seed-фразу</span>. Если резервная фраза была раскрыта злоумышленнику, безопасность самого устройства уже не гарантирует сохранность средств. Также пользователь должен внимательно проверять адреса и параметры операций на экране устройства перед подписанием.</p>'
