                <p>Программный кошелёк может работать на компьютере, смартфоне или непосредственно в браузере. Он может быть <span class="term" data-term="crypto-wallet/hot-wallet">горячим</span>, если ключи используются в подключённой к интернету среде, и <span class="term" data-term="crypto-wallet/non-custodial-wallet">некастодиальным</span>, если пользователь самостоятельно контролирует ключевой материал.</p>

