                <p>Пользователь обычно получает аккаунт и видит баланс, но не обязательно получает прямой доступ к ключам, с помощью которых можно подписывать блокчейн-операции. Поэтому перевод средств внутри платформы может быть внутренней бухгалтерской операцией, а реальный <span class="term" data-term="blockchain/transaction">транзакционный</span> перевод в блокчейне происходит только при депозите, выводе или другой операции, которую контролирует кастодиан.</p>

                <h3>Преимущества и особенности</h3>
                <p>Кастодиальная модель может упростить восстановление доступа, обслуживание аккаунта и использование биржевых сервисов. Однако пользователь зависит от безопасности, технической инфраструктуры и правил оператора. Возможны ограничения на вывод, блокировка аккаунта или задержка обработки операций.</p>

                <p>Противоположной моделью является <span class="term" data-term="crypto-wallet/non-custodial-wallet">некастодиальный кошелёк</span>, при котором пользователь самостоятельно управляет ключами. Таким образом, главное различие между моделями заключается не в форме приложения, а в том, кто контролирует ключи.</p>'
