                <p>Самостоятельное хранение может осуществляться через <span class="term" data-term="crypto-wallet/software-wallet">программный</span> или <span class="term" data-term="crypto-wallet/hardware-wallet">аппаратный кошелёк</span>. В обоих случаях ключевой материал должен оставаться под контролем владельца, а операции подтверждаются с помощью <span class="term" data-term="crypto-wallet/transaction-signing">цифровой подписи</span>.</p>

                <h3>Ответственность при self-custody</h3>
                <p>При самостоятельном хранении пользователь отвечает за резервное копирование, защиту <span class="term" data-term="crypto-wallet/seed-phrase">seed-фразы</span>, безопасность устройств и проверку операций. Потеря ключа, раскрытие seed-фразы или подписание вредоносной операции может привести к необратимой потере средств.</p>

                <p>Таким образом, self-custody меняет модель доверия: пользователь меньше зависит от кастодиана, но принимает на себя больше технической и операционной ответственности.</p>'
