                <p>Приватный ключ математически связан с <span class="term" data-term="crypto-wallet/public-key">публичным ключом</span>. Публичный ключ может быть использован для проверки подписи, тогда как приватный ключ должен оставаться секретным. Пользователь не должен передавать приватный ключ другим людям или вводить его на неизвестных сайтах.</p>

                <h3>Приватный ключ и блокчейн</h3>
                <p>Сам ключ обычно не записывается в <span class="term" data-term="blockchain/blockchain">блокчейн</span>. Вместо этого блокчейн содержит данные, позволяющие проверить подпись или определить состояние соответствующего адреса. При отправке средств кошелёк использует приватный ключ для создания подписи, а сеть проверяет её корректность.</p>

                <p>Современные кошельки часто не требуют от пользователя вручную хранить отдельный приватный ключ для каждого адреса. В <span class="term" data-term="crypto-wallet/hd-wallet">HD-кошельках</span> множество ключей может быть получено из общего исходного секрета, например seed-фразы.</p>

                <p>Безопасность приватного ключа имеет критическое значение. Его раскрытие может позволить другому лицу подписывать допустимые с точки зрения протокола операции, а потеря ключа без резервной копии может сделать доступ к активам невозможным.</p>'
            ],

