                'name' => 'Публичный ключ',
                'caption' => 'Открытый криптографический ключ для проверки подписей.',
                'definition' => '<p><strong>Публичный ключ</strong> — открытая часть криптографической пары, математически связанная с <span class="term" data-term="crypto-wallet/private-key">приватным ключом</span>. В системах цифровых подписей публичный ключ используется для проверки того, что подпись была создана соответствующим приватным ключом.</p>

                <p>В некоторых блокчейн-системах <span class="term" data-term="crypto-wallet/wallet-address">адрес</span> получается непосредственно или косвенно из публичного ключа. Однако публичный ключ и адрес не являются универсально взаимозаменяемыми понятиями: конкретный способ формирования адреса зависит от протокола и используемого стандарта.</p>

                <p>В отличие от приватного ключа, публичный ключ не предназначен для сохранения в секрете. Его раскрытие само по себе не даёт возможности подписывать транзакции. Безопасность системы основана на вычислительной сложности получения приватного ключа из соответствующего публичного.</p>'
            ],

            'seed-phrase' => [
                'title' => 'Что такое seed-фраза | TM Wiki',
                'description' => 'Seed-фраза — последовательность слов, используемая для восстановления криптокошелька и связанных с ним ключей.',
                'name' => 'Seed-фраза',
                'caption' => 'Резервная фраза для восстановления криптокошелька.',
                'definition' => '<p><strong>Seed-фраза</strong> — последовательность слов, из которой совместимый криптокошелёк может восстановить исходный набор ключей и производные адреса. Она используется как удобное для человека представление секретного материала, лежащего в основе многих <span class="term" data-term="crypto-wallet/hd-wallet">HD-кошельков</span>.</p>

                <p>Наиболее известным стандартом формирования таких фраз является BIP-39, хотя конкретные форматы и механизмы восстановления зависят от кошелька. Seed-фраза не является просто паролем от приложения: она может содержать достаточно информации для восстановления доступа к криптоактивам, если кошелёк использует соответствующий стандарт.</p>

                <h3>Почему seed-фраза критична</h3>
                <p>Любой человек, получивший полную seed-фразу, потенциально может восстановить соответствующий кошелёк на другом устройстве. Поэтому её нельзя отправлять через мессенджеры, хранить в обычном облачном документе или вводить на случайном сайте.</p>

                <p>Seed-фраза должна иметь резервную копию в форме, устойчивой к случайному удалению, потере устройства и другим физическим рискам. При этом резервная копия сама становится чувствительным объектом: её компрометация может быть эквивалентна компрометации ключей. Безопасность seed-фразы является отдельной частью <span class="term" data-term="security/seed-phrase-security">защиты seed-фразы</span>.</p>'
            ],

            'mnemonic-phrase' => [
                'title' => 'Что такое mnemonic фраза | TM Wiki',
                'description' => 'Mnemonic фраза — последовательность слов, кодирующая энтропию и используемая для восстановления криптографических ключей кошелька.',
                'name' => 'Mnemonic фраза',
                'caption' => 'Мнемоническое представление исходного секрета кошелька.',
                'definition' => '<p><strong>Mnemonic фраза</strong> — это последовательность слов, используемая для представления криптографической энтропии в удобной для человека форме. В совместимых кошельках из неё может быть получен исходный материал, на базе которого создаются ключи и адреса.</p>

                <p>В практическом употреблении термины <span class="term" data-term="crypto-wallet/seed-phrase">seed-фраза</span> и mnemonic фраза часто используются как взаимозаменяемые, однако техническая терминология может различаться в зависимости от стандарта. Например, в BIP-39 мнемоническая фраза кодирует исходную энтропию и с контрольной суммой преобразуется в исходный seed.</p>

                <h3>Связь с HD-кошельками</h3>
                <p>После восстановления исходного seed кошелёк может использовать <span class="term" data-term="crypto-wallet/derivation-path">путь деривации</span> для получения различных ветвей ключей и адресов. Поэтому одна mnemonic фраза может быть связана с большим количеством адресов и аккаунтов.</p>

                <p>Мнемоническая фраза должна рассматриваться как секретный ключевой материал. Её раскрытие может дать возможность восстановить соответствующие ключи, а потеря без другой резервной копии может привести к потере доступа к активам.</p>'
