                'caption' => 'Идентификатор для получения криптоактивов в блокчейне.',
                'definition' => '<p><strong>Адрес криптокошелька</strong> — это идентификатор, который используется блокчейн-сетью или соответствующим протоколом для указания получателя средств. Пользователь передаёт адрес отправителю, после чего тот может создать <span class="term" data-term="blockchain/transaction">транзакцию</span>, направляющую активы на этот адрес.</p>

