                'caption' => 'Адрес для получения сдачи от транзакции.',
                'definition' => '<p><strong>Change address</strong> — это адрес, используемый кошельком для получения остатка средств, который не был потрачен в рамках конкретной <span class="term" data-term="blockchain/transaction">транзакции</span>. Понятие особенно характерно для <span class="term" data-term="blockchain/transaction-input">UTXO-модели</span>, используемой, например, в Bitcoin.</p>

