                <h3>Зачем используются отдельные адреса</h3>
                <p>Использование новых адресов позволяет кошельку управлять большим количеством UTXO и может улучшать конфиденциальность, поскольку не все операции пользователя обязательно связаны с одним постоянно используемым адресом.</p>

