                'description' => 'HD-кошелёк создаёт множество криптографических ключей и адресов из единого исходного секрета по иерархической структуре.',
                'name' => 'HD-кошелёк',
                'caption' => 'Иерархический детерминированный криптокошелёк.',
                'definition' => '<p><strong>HD-кошелёк</strong> (Hierarchical Deterministic Wallet) — это кошелёк, который способен детерминированно создавать множество криптографических ключей и адресов из единого исходного секрета. Такая архитектура позволяет управлять большим количеством адресов без необходимости отдельно создавать и резервировать каждый ключ.</p>

                <p>Исходным материалом может выступать <span class="term" data-term="crypto-wallet/seed-phrase">seed-фраза</span>. На её основе кошелёк получает корневой ключ, а затем создаёт иерархию дочерних ключей. Конкретная структура определяется используемыми стандартами и <span class="term" data-term="crypto-wallet/derivation-path">путём деривации</span>.</p>

                <h3>Преимущества HD-модели</h3>
                <ul>
                    <li>одна резервная копия может восстановить множество адресов;</li>
