            'derivation-path' => [
                'title' => 'Что такое derivation path | TM Wiki',
                'description' => 'Derivation path определяет путь, по которому HD-кошелёк получает конкретные ключи и адреса из исходного seed.',
                'name' => 'Derivation Path',
                'caption' => 'Путь получения ключей и адресов в HD-кошельке.',
                'definition' => '<p><strong>Derivation path</strong> — это структура, которая определяет, какие дочерние ключи должен получить <span class="term" data-term="crypto-wallet/hd-wallet">HD-кошелёк</span> из исходного ключевого материала. Один и тот же seed может использоваться для создания множества различных ключей, а путь определяет конкретную ветвь этой иерархии.</p>

                <p>Популярным стандартом записи путей является BIP-32, а различные схемы аккаунтов и адресов могут использовать дополнительные стандарты, такие как BIP-44. Путь может содержать уровни, соответствующие назначению, типу монеты, аккаунту, цепочке и индексу адреса.</p>

                <h3>Почему путь важен при восстановлении</h3>
                <p>Если пользователь восстанавливает кошелёк из <span class="term" data-term="crypto-wallet/seed-phrase">seed-фразы</span>, но выбирает другой derivation path, приложение может показать пустой баланс, хотя исходные средства всё ещё находятся в блокчейне. В таком случае проблема может быть не в seed, а в использовании другой ветви ключей.</p>

                <p>Поэтому при миграции между кошельками необходимо учитывать используемый стандарт, тип аккаунта и derivation path. Совместимость seed-фразы сама по себе не гарантирует автоматического обнаружения всех ранее использованных адресов.</p>'
