                'name' => 'Multisig',
                'caption' => 'Кошелёк с несколькими ключами для подтверждения операций.',
                'definition' => '<p><strong>Multisig</strong> (multisignature) — механизм управления активами, при котором выполнение операции требует нескольких независимых <span class="term" data-term="security/digital-signature">цифровых подписей</span>. Вместо единственного ключа используется набор ключей и правило, определяющее необходимое количество подписей.</p>

                <p>Например, схема 2-of-3 означает, что существует три авторизованных ключа, но для подтверждения операции достаточно любых двух. Такая архитектура позволяет распределить контроль между несколькими людьми, устройствами или организациями.</p>

                <h3>Где применяется multisig</h3>
                <ul>
                    <li>совместное управление корпоративными резервами;</li>
