                <p>Multisig может повысить устойчивость к компрометации одного ключа, но добавляет операционную сложность. Необходимо безопасно хранить несколько ключей, контролировать процесс подписания и иметь план восстановления. В зависимости от блокчейна multisig может быть реализован непосредственно на уровне протокола, через специальные скрипты или с помощью <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span>.</p>'
