                'definition' => '<p><strong>Подпись транзакции</strong> — это криптографическая операция, с помощью которой владелец соответствующего <span class="term" data-term="crypto-wallet/private-key">приватного ключа</span> подтверждает авторизацию определённой операции. Сеть использует <span class="term" data-term="crypto-wallet/public-key">публичный ключ</span> или связанные с ним данные для проверки подписи.</p>

                <p>При отправке средств кошелёк формирует данные <span class="term" data-term="blockchain/transaction">транзакции</span>, включая получателя, сумму, комиссии и другие параметры, предусмотренные конкретным блокчейном. Затем кошелёк подписывает эти данные приватным ключом. Подписанная транзакция передаётся в сеть и после проверки может попасть в <span class="term" data-term="blockchain/mempool">mempool</span> и далее в <span class="term" data-term="blockchain/block">блок</span>.</p>

                <h3>Что подтверждает подпись</h3>
                <p>Цифровая подпись позволяет проверить, что операция была авторизована обладателем соответствующего ключа и что подписанные данные не были изменены после создания подписи. При этом подпись сама по себе не означает, что операция обязательно будет включена в блокчейн: её ещё должны принять правила сети, а в некоторых системах транзакция может оставаться неподтверждённой или быть отклонена.</p>

                <p>Особенно важно понимать разницу между подписью и визуальным подтверждением в интерфейсе кошелька. Подписание разрешает конкретную операцию, поэтому пользователь должен проверять адрес получателя, сумму, комиссию и другие параметры перед подтверждением. Это особенно важно при взаимодействии со <span class="term" data-term="deFi/dapp">dApp</span> и <span class="term" data-term="blockchain/smart-contract">смарт-контрактами</span>, где подписываемое действие может быть сложнее обычного перевода.</p>'
