        'caption' => 'Термины децентрализованных финансов: DEX, AMM, пулы ликвидности, yield farming, TVL, impermanent loss и другие понятия.',
        'terms' => [
            'defi' => [
                'title' => 'Что такое DeFi | TM Wiki',
                'description' => 'DeFi — децентрализованные финансовые сервисы на блокчейне без традиционного финансового посредника.',
                'name' => 'DeFi',
                'caption' => 'Децентрализованные финансы на блокчейне',
                'definition' => '<p><strong>DeFi (Decentralized Finance)</strong> — это совокупность финансовых приложений, протоколов и сервисов, работающих на основе <span class="term" data-term="blockchain/blockchain">блокчейна</span> и позволяющих выполнять финансовые операции без традиционного централизованного посредника. Вместо банка, брокера или централизованной финансовой компании функции хранения правил, расчетов и исполнения операций выполняют <span class="term" data-term="blockchain/smart-contract">смарт-контракты</span>, блокчейн и связанные с ними протоколы.</p>

                <p>Пользователь взаимодействует с DeFi-протоколом непосредственно через <span class="term" data-term="defi/dapp">dApp</span> или другой интерфейс. Для доступа обычно используется <span class="term" data-term="crypto-wallet/crypto-wallet">криптовалютный кошелек</span>, который позволяет подписывать операции и управлять активами. В отличие от традиционной финансовой системы, многие DeFi-протоколы не требуют открытия банковского счета или передачи активов централизованной компании.</p>

                <p>К DeFi относятся различные типы финансовых сервисов: децентрализованные обмены активов, кредитование и займы, предоставление ликвидности, доходное фермерство, стейблкоин-протоколы, деривативы и другие механизмы. В основе этих систем могут находиться <span class="term" data-term="defi/liquidity-pool">пулы ликвидности</span>, <span class="term" data-term="defi/automated-market-maker">автоматические маркет-мейкеры</span>, <span class="term" data-term="defi/oracle">оракулы</span> и механизмы управления через <span class="term" data-term="defi/dao">DAO</span>.</p>

                <p>DeFi не означает полное отсутствие централизованных компонентов. Конкретный протокол может зависеть от внешних оракулов, интерфейсов, разработчиков, администраторских ключей, инфраструктуры блокчейна или определенных поставщиков данных. Поэтому при оценке децентрализации необходимо рассматривать архитектуру конкретного протокола, а не только его название.</p>

                <p>Основное преимущество DeFi заключается в программируемости финансовых операций. Пользователь может самостоятельно взаимодействовать с протоколом, предоставлять ликвидность, занимать активы, размещать их в различных стратегиях или обменивать токены. При этом операции записываются в блокчейне, а условия исполнения определяются кодом протокола.</p>

                <p>Одновременно DeFi связано с существенными рисками. Ошибка в <span class="term" data-term="security/smart-contract-audit">аудите смарт-контракта</span> или самом коде может привести к потере средств. Дополнительные риски создают манипуляции <span class="term" data-term="defi/price-oracle">ценовыми оракулами</span>, недостаточная ликвидность, <span class="term" data-term="defi/impermanent-loss">непостоянные потери</span>, ошибки пользователя, взломы и экономические атаки. Поэтому DeFi следует рассматривать как технологическую инфраструктуру финансовых операций, а не как автоматически безопасную альтернативу традиционным финансам.</p>'
            ],

            'decentralized-finance' => [
                'title' => 'Что такое децентрализованные финансы | TM Wiki',
                'description' => 'Децентрализованные финансы используют блокчейн и смарт-контракты для предоставления финансовых услуг без традиционного посредника.',
                'name' => 'Децентрализованные финансы',
                'caption' => 'Финансовые сервисы без традиционного посредника',
                'definition' => '<p><strong>Децентрализованные финансы</strong> — это финансовая модель, в которой операции и правила предоставления услуг реализуются с использованием <span class="term" data-term="blockchain/blockchain">блокчейна</span>, <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span> и криптографических механизмов. Пользователь взаимодействует с программным протоколом непосредственно, без необходимости передавать активы традиционному финансовому посреднику.</p>

                <p>В классической финансовой системе кредит, обмен валюты или хранение средств обычно предполагают наличие организации, которая ведет учет, контролирует операции и устанавливает правила обслуживания. В децентрализованных финансах часть этих функций переносится в программный код. Например, <span class="term" data-term="defi/decentralized-lending">децентрализованное кредитование</span> может автоматически принимать залог, рассчитывать доступный объем займа и инициировать ликвидацию при ухудшении позиции.</p>

                <p>Ключевым элементом такой архитектуры являются <span class="term" data-term="defi/dapp">dApp</span> и смарт-контракты. Интерфейс dApp предоставляет пользователю удобный способ взаимодействия, а непосредственно финансовая логика выполняется контрактами. Для авторизации операций используется <span class="term" data-term="crypto-wallet/transaction-signing">подписание транзакций</span> с помощью ключей пользователя.</p>

                <p>Децентрализованные финансы включают несколько основных направлений. К ним относятся обмен токенов через <span class="term" data-term="defi/swap">swap</span>, предоставление ликвидности в <span class="term" data-term="defi/liquidity-pool">пулы ликвидности</span>, кредитование, займы, доходное фермерство и различные финансовые стратегии. Для определения внешних цен протоколы часто используют <span class="term" data-term="defi/oracle">оракулы</span>.</p>

                <p>Децентрализация может существовать на разных уровнях. Сам смарт-контракт может быть размещен в публичной сети, но управление параметрами протокола может оставаться у небольшой группы участников. Кроме того, интерфейс, оракулы, инфраструктура и механизм управления могут иметь собственные точки централизации. Поэтому термин описывает архитектурный подход, а степень фактической децентрализации зависит от конкретного протокола.</p>

                <p>Главная особенность децентрализованных финансов — возможность программировать финансовые операции и комбинировать разные протоколы. Один пользовательский сценарий может последовательно использовать несколько смарт-контрактов, например обменять актив, предоставить его в пул и использовать полученные позиции в другой стратегии. Такая компонуемость является одной из фундаментальных особенностей DeFi.</p>'
            ],

            'dapp' => [
                'title' => 'Что такое dApp | TM Wiki',
                'description' => 'dApp — децентрализованное приложение, интерфейс которого взаимодействует со смарт-контрактами и блокчейном.',
                'name' => 'dApp',
                'caption' => 'Децентрализованное приложение',
                'definition' => '<p><strong>dApp</strong> (decentralized application) — приложение, которое использует <span class="term" data-term="blockchain/blockchain">блокчейн</span> и один или несколько <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span> для выполнения части своей логики. В контексте DeFi dApp обычно представляет собой пользовательский интерфейс, через который человек взаимодействует с финансовым протоколом.</p>

                <p>Типичный dApp состоит из нескольких компонентов. Пользовательский интерфейс может быть обычным веб-приложением, которое отображает балансы, котировки, доступную ликвидность и параметры операций. При необходимости выполнения действия интерфейс формирует данные для блокчейн-транзакции, а пользователь подтверждает ее через <span class="term" data-term="crypto-wallet/crypto-wallet">криптовалютный кошелек</span>.</p>

                <p>После <span class="term" data-term="crypto-wallet/transaction-signing">подписания транзакции</span> операция отправляется в сеть. Далее ее обрабатывают <span class="term" data-term="blockchain/blockchain-node">узлы блокчейна</span>, а соответствующий смарт-контракт выполняет заложенную в нем логику. Таким образом, интерфейс dApp и смарт-контракт выполняют разные функции: интерфейс упрощает взаимодействие, а контракт определяет фактические правила операции.</p>

                <p>dApp может использовать несколько смарт-контрактов одновременно. Например, интерфейс децентрализованной биржи может обращаться к контракту обмена, контракту пула ликвидности и дополнительным контрактам маршрутизации. В результате одна пользовательская операция может содержать несколько последовательных действий внутри блокчейна.</p>

                <p>Децентрализованное приложение не обязательно является полностью децентрализованным. Веб-интерфейс может размещаться на централизованном сервере, данные могут поступать через централизованный API, а обновление контрактов может контролироваться определенным администратором. Поэтому при анализе dApp необходимо отдельно оценивать децентрализацию интерфейса, смарт-контрактов, управления и внешней инфраструктуры.</p>

                <p>Основные риски dApp связаны с уязвимостями смарт-контрактов, вредоносными или поддельными интерфейсами, ошибочными разрешениями на использование токенов, фишингом и компрометацией кошелька. Перед взаимодействием с новым dApp важно проверять адреса контрактов, сеть, разрешения и репутацию используемого протокола.</p>'
            ],

            'liquidity-pool' => [
                'title' => 'Что такое пул ликвидности | TM Wiki',
                'description' => 'Пул ликвидности — смарт-контракт с резервами активов, используемый для обменов, кредитования и других операций DeFi.',
                'name' => 'Пул ликвидности',
                'caption' => 'Резерв активов для работы DeFi-протокола',
                'definition' => '<p><strong>Пул ликвидности</strong> — это резерв криптоактивов, заблокированных в <span class="term" data-term="blockchain/smart-contract">смарт-контракте</span> и используемых DeFi-протоколом для выполнения финансовых операций. Наиболее известный вариант — пул из двух или более токенов, который используется для автоматического обмена активов без традиционного центрального <span class="term" data-term="crypto-trading/order-book">стакана заявок</span>.</p>

                <p>Пользователь, который вносит активы в такой пул, называется <span class="term" data-term="defi/liquidity-provider">поставщиком ликвидности</span>. В обмен он получает право на соответствующую долю резервов и, в зависимости от протокола, специальные токены или учетную позицию. Поставщик может получать часть комиссий, которые платят пользователи за операции.</p>

                <p>Например, пул может содержать два актива: условно Token A и Token B. Пользователь, желающий обменять Token A на Token B, взаимодействует со смарт-контрактом пула. Контракт уменьшает резерв Token B и увеличивает резерв Token A в соответствии с математической моделью протокола. Цена операции определяется состоянием резервов и формулой конкретного <span class="term" data-term="defi/automated-market-maker">автоматического маркет-мейкера</span>.</p>

                <p>Размер пула имеет большое значение для качества торговли. При большом объеме ликвидности относительно размера сделки изменение цены обычно меньше. При небольшом пуле крупная операция может значительно изменить соотношение резервов и вызвать высокий <span class="term" data-term="crypto-trading/slippage">проскальзывание</span>. Поэтому ликвидность влияет не только на доступность обмена, но и на его стоимость для пользователя.</p>

                <p>Пулы ликвидности используются не только для обменов. Они могут быть частью протоколов кредитования, деривативов и других DeFi-механизмов. В некоторых системах активы пользователей объединяются в общий резерв, из которого выдаются займы, а процентные ставки рассчитываются на основе спроса и предложения.</p>

                <p>Поставщик ликвидности принимает на себя определенные риски. Один из наиболее важных — <span class="term" data-term="defi/impermanent-loss">impermanent loss</span>, возникающий при изменении относительной цены активов в пуле. Дополнительно существуют риски смарт-контракта, манипуляции оракулами, недостаточной ликвидности и экономической модели конкретного протокола.</p>

                <h3>Основные параметры пула</h3>

                <ul>
                    <li><strong>Резервы</strong> — объемы активов, находящихся в контракте.</li>
                    <li><strong>Объем торгов</strong> — количество активов, проходящих через пул.</li>
                    <li><strong>Комиссия</strong> — часть стоимости операций, которая может распределяться между протоколом и поставщиками ликвидности.</li>
                    <li><strong>Доля ликвидности</strong> — относительная часть пула, принадлежащая конкретному поставщику.</li>
                    <li><strong>Цена и проскальзывание</strong> — параметры, зависящие от состояния пула и размера операции.</li>
                </ul>'
            ],

            'liquidity-provider' => [
                'title' => 'Кто такой поставщик ликвидности | TM Wiki',
                'description' => 'Поставщик ликвидности вносит активы в DeFi-пул и получает долю комиссий или другие вознаграждения за предоставление ликвидности.',
                'name' => 'Поставщик ликвидности',
                'caption' => 'Участник, предоставляющий активы пулу',
                'definition' => '<p><strong>Поставщик ликвидности</strong> (liquidity provider, LP) — пользователь или организация, которые вносят криптоактивы в <span class="term" data-term="defi/liquidity-pool">пул ликвидности</span> DeFi-протокола. Предоставленные активы используются для обменов, кредитования или других операций, предусмотренных архитектурой протокола.</p>

                <p>В простейшем AMM-пуле поставщик обычно вносит два актива в определенном соотношении. Например, если пул предназначен для пары Token A/Token B, пользователь может внести оба токена. Взамен он получает долю пула, которая определяет его право на часть резервов и потенциально на часть комиссий.</p>

                <p>Доход поставщика ликвидности может формироваться из торговых комиссий. Если через пул проходит значительный объем операций, суммарные комиссии могут быть существенными. Однако доходность нельзя оценивать только по размеру комиссии: необходимо учитывать изменение цены активов, размер пула, долю пользователя, дополнительные стимулы и риски.</p>

                <p>Ключевой риск — <span class="term" data-term="defi/impermanent-loss">непостоянные потери</span>. Если относительная цена активов значительно изменяется после внесения средств, стоимость позиции поставщика может отличаться от стоимости простого удержания тех же активов вне пула. При этом торговые комиссии и другие вознаграждения могут частично или полностью компенсировать такой эффект, но это не гарантируется.</p>

                <p>В некоторых протоколах поставщик ликвидности получает специальные токены, отражающие его долю. Такие токены могут использоваться в других DeFi-протоколах, например в стратегиях <span class="term" data-term="defi/yield-farming">yield farming</span>. В других системах позиция хранится непосредственно в смарт-контракте и отображается через интерфейс протокола.</p>

                <p>Перед предоставлением ликвидности важно изучить модель пула, комиссии, правила вывода средств, возможные блокировки, механизм расчета вознаграждений и риски смарт-контрактов. Дополнительно необходимо учитывать <span class="term" data-term="crypto-trading/slippage">проскальзывание</span>, волатильность активов и возможные проблемы с оракулами или управлением протокола.</p>'
            ],

            'automated-market-maker' => [
                'title' => 'Что такое AMM | TM Wiki',
                'description' => 'AMM — автоматический маркет-мейкер, который определяет условия обмена активов с помощью математической модели и ликвидности пула.',
                'name' => 'Автоматический маркет-мейкер',
                'caption' => 'Алгоритмическая модель обмена в DeFi',
                'definition' => '<p><strong>Автоматический маркет-мейкер</strong> (AMM) — механизм децентрализованной торговли, который позволяет обменивать активы с использованием ликвидности <span class="term" data-term="defi/liquidity-pool">пула</span> и математической формулы вместо традиционного <span class="term" data-term="crypto-trading/order-book">стакана заявок</span>, где отдельные участники выставляют ордера на покупку и продажу.</p>

                <p>В классической модели AMM пул содержит резервы нескольких активов. Пользователь не ищет конкретного контрагента, готового совершить противоположную сделку. Вместо этого он взаимодействует со смарт-контрактом, который изменяет состав резервов согласно правилам протокола.</p>

                <p>Одна из наиболее известных моделей использует постоянное произведение резервов. В упрощенном виде для двух активов оно описывается как <code>x * y = k</code>, где <code>x</code> и <code>y</code> — количества двух активов в пуле, а <code>k</code> — значение, которое модель стремится сохранять с учетом комиссий и особенностей реализации. Такая формула приводит к тому, что цена сделки зависит от размера резервов и объема операции.</p>

                <p>При крупной сделке отношение резервов заметно изменяется, поэтому итоговая цена может существенно отличаться от исходной. Это связано с <span class="term" data-term="crypto-trading/slippage">проскальзыванием</span>. Чем меньше ликвидность относительно размера операции, тем сильнее потенциальное влияние сделки на цену.</p>

                <p>AMM создает условия, при которых обмен может выполняться практически непрерывно при наличии достаточной ликвидности. Источником ликвидности выступают <span class="term" data-term="defi/liquidity-provider">поставщики ликвидности</span>, которые размещают активы в пуле и получают часть комиссий или дополнительные стимулы.</p>

                <p>Существуют разные конструкции AMM. Они могут отличаться математической кривой, количеством активов, формой пулов, правилами ребалансировки и механизмом комиссий. Например, для стейблкоинов может использоваться модель, оптимизированная для торговли активами с близкой стоимостью.</p>

                <p>AMM является не только механизмом определения цены, но и экономической системой. Изменение резервов влияет на цену, арбитражные операции стремятся вернуть цену пула к внешнему рынку, а поставщики ликвидности получают комиссии в обмен на предоставление капитала. При этом именно изменения относительных цен могут приводить к <span class="term" data-term="defi/impermanent-loss">непостоянным потерям</span>.</p>'
            ],

            'yield-farming' => [
                'title' => 'Что такое yield farming | TM Wiki',
                'description' => 'Yield farming — стратегия получения доходности в DeFi за счет размещения активов в протоколах и использования их вознаграждений.',
                'name' => 'Yield farming',
                'caption' => 'Стратегии получения доходности в DeFi',
                'definition' => '<p><strong>Yield farming</strong> — это использование одной или нескольких DeFi-стратегий для получения доходности от размещения криптоактивов. Пользователь может предоставлять ликвидность, кредитовать активы, получать токены протокола и перемещать капитал между различными механизмами в поиске более высокой ожидаемой доходности.</p>

                <p>В простом варианте yield farming может начинаться с предоставления средств в <span class="term" data-term="defi/liquidity-pool">пул ликвидности</span>. Пользователь получает часть торговых комиссий и, если протокол предусматривает дополнительные стимулы, токены вознаграждения. Полученный доход может реинвестироваться в ту же или другую стратегию.</p>

                <p>Более сложные стратегии используют несколько протоколов. Например, пользователь может предоставить актив в <span class="term" data-term="defi/lending-protocol">кредитный протокол</span>, получить доходную позицию, использовать ее в другом протоколе или автоматически реинвестировать полученные вознаграждения. Такие стратегии часто называют composable или многослойными.</p>

                <p>Доходность yield farming необходимо отличать от гарантированной прибыли. Показатель APY или APR может изменяться в зависимости от объема капитала, спроса, эмиссии токена вознаграждения, цены этого токена и других факторов. Высокая отображаемая доходность может быстро снижаться после притока новых участников.</p>

                <p>Кроме рыночного риска, yield farming несет технологический риск. Пользователь может взаимодействовать сразу с несколькими <span class="term" data-term="blockchain/smart-contract">смарт-контрактами</span>, поэтому ошибка в одном из них способна повлиять на всю стратегию. Дополнительно возникают риски <span class="term" data-term="defi/oracle">оракулов</span>, ликвидности, управления и экономической модели.</p>

                <p>Если стратегия включает AMM-пулы, необходимо учитывать <span class="term" data-term="defi/impermanent-loss">impermanent loss</span>. Если активы используются в кредитовании, необходимо учитывать риск <span class="term" data-term="defi/liquidation-threshold">ликвидации</span>. Таким образом, оценка yield farming должна учитывать не только заявленную доходность, но и все источники риска.</p>

                <h3>Из чего может состоять доходность</h3>

                <ul>
                    <li>торговые комиссии от предоставления ликвидности;</li>
                    <li>процентный доход от кредитования активов;</li>
                    <li>токены стимулирования протокола;</li>
                    <li>вознаграждения за стейкинг или блокировку специальных токенов;</li>
                    <li>доход от сложных стратегий реинвестирования.</li>
                </ul>'
            ],

            'liquidity-mining' => [
                'title' => 'Что такое liquidity mining | TM Wiki',
                'description' => 'Liquidity mining — получение вознаграждений за предоставление ликвидности DeFi-протоколу.',
                'name' => 'Liquidity mining',
                'caption' => 'Вознаграждение за предоставление ликвидности',
                'definition' => '<p><strong>Liquidity mining</strong> — механизм стимулирования пользователей предоставлять активы в <span class="term" data-term="defi/liquidity-pool">пулы ликвидности</span> DeFi-протокола в обмен на дополнительные вознаграждения. Чаще всего такими вознаграждениями являются токены самого протокола или другой актив, распределяемый по установленным правилам.</p>

                <p>Основная задача liquidity mining — привлечь капитал в протокол на ранних этапах или увеличить ликвидность конкретных рынков. Чем больше доступной ликвидности, тем легче пользователям выполнять операции и тем меньше может быть влияние крупных сделок на цену.</p>

                <p>Механика обычно начинается с внесения пользователем активов в пул. Протокол отслеживает долю пользователя или количество специальных LP-токенов и на основании времени, размера позиции и других параметров рассчитывает вознаграждение.</p>

                <p>Liquidity mining отличается от обычного получения торговых комиссий. Комиссия возникает непосредственно из деятельности пользователей протокола, тогда как liquidity mining представляет собой дополнительную систему стимулов. Один пользователь может одновременно получать оба вида дохода.</p>

                <p>Вознаграждение в токенах не является безрисковым доходом. Цена стимулирующего токена может существенно измениться, а эмиссия новых токенов может создавать инфляционное давление. Кроме того, поставщик ликвидности может столкнуться с <span class="term" data-term="defi/impermanent-loss">непостоянными потерями</span> и рисками смарт-контракта.</p>

                <p>Liquidity mining часто используется как один из элементов <span class="term" data-term="defi/yield-farming">yield farming</span>. В сложной стратегии полученные токены могут снова размещаться в другом протоколе, создавая несколько уровней потенциальной доходности и риска.</p>'
            ],

            'lending-protocol' => [
                'title' => 'Что такое lending protocol | TM Wiki',
                'description' => 'Lending protocol — DeFi-протокол для автоматизированного кредитования и заимствования криптоактивов через смарт-контракты.',
                'name' => 'Кредитный протокол',
                'caption' => 'Протокол для кредитования и займов',
                'definition' => '<p><strong>Lending protocol</strong> — это DeFi-протокол, который позволяет пользователям предоставлять криптоактивы в кредитный рынок и занимать активы на заранее определенных условиях. Управление операциями осуществляется через <span class="term" data-term="blockchain/smart-contract">смарт-контракты</span>, которые учитывают депозиты, задолженность, процентные ставки и требования к обеспечению.</p>

                <p>Обычно кредитный протокол содержит общий резерв определенного актива. Пользователь может внести актив в этот резерв и получать процентный доход. Другой пользователь может предоставить <span class="term" data-term="defi/collateral">залог</span> и получить возможность занять актив из доступного резерва.</p>

                <p>Большинство протоколов работает по модели избыточного обеспечения. Это означает, что стоимость залога должна превышать стоимость займа. Такое требование необходимо потому, что протокол обычно не использует традиционную проверку кредитоспособности пользователя и должен защищать кредиторов от недостатка обеспечения.</p>

                <p>Процентные ставки могут зависеть от использования пула. При небольшом спросе на займы ликвидность остается доступной, а ставка может быть ниже. При высоком использовании резерва ставка может увеличиваться, стимулируя поставщиков предоставлять больше капитала и заемщиков возвращать часть долга.</p>

                <p>Кредитный протокол также должен определять правила ликвидации. Если стоимость обеспечения падает настолько, что позиция становится недостаточно обеспеченной, протокол может разрешить третьим сторонам погасить часть или весь долг в обмен на получение части залога. Конкретные параметры зависят от протокола.</p>

                <p>Ключевыми рисками являются волатильность залога, ошибки смарт-контрактов, проблемы <span class="term" data-term="defi/price-oracle">ценовых оракулов</span>, недостаточная ликвидность и резкое изменение рыночных условий. Поэтому показатели TVL и процентной ставки сами по себе не описывают полный риск кредитного протокола.</p>'
            ],

            'borrowing' => [
                'title' => 'Что такое borrowing в DeFi | TM Wiki',
                'description' => 'Borrowing в DeFi — получение криптоактивов в долг через протокол с использованием обеспечения и автоматических правил.',
                'name' => 'Borrowing',
                'caption' => 'Заимствование активов через DeFi',
                'definition' => '<p><strong>Borrowing</strong> в DeFi — это процесс заимствования криптоактивов у протокола или его участников на условиях, определяемых смарт-контрактом. В большинстве систем заемщик сначала размещает <span class="term" data-term="defi/collateral">обеспечение</span>, после чего получает возможность занять определенный объем другого актива.</p>

                <p>Например, пользователь может внести криптовалюту в кредитный протокол и занять стейблкоин. При этом заемщик продолжает контролировать заложенный актив, но он становится частью обеспечения позиции. Пока требования протокола выполняются, заем может оставаться открытым.</p>

                <p>Размер доступного займа определяется стоимостью залога и параметрами риска. Один из важных показателей — <span class="term" data-term="defi/collateralization-ratio">коэффициент обеспечения</span>. Чем выше требуемый коэффициент, тем меньшую сумму относительно стоимости залога пользователь может занять.</p>

                <p>Стоимость залога и долга может изменяться со временем. Для определения рыночных цен протокол часто использует <span class="term" data-term="defi/price-oracle">ценовой оракул</span>. Если цена залога падает или стоимость долга возрастает относительно обеспечения, позиция приближается к <span class="term" data-term="defi/liquidation-threshold">порогу ликвидации</span>.</p>

                <p>Borrowing может использоваться для различных задач: получения ликвидности без продажи долгосрочного актива, создания торговой позиции, хеджирования или участия в других DeFi-стратегиях. Однако заем создает обязательство, поэтому потенциальная доходность другой операции должна оцениваться вместе с процентами и риском ликвидации.</p>

                <p>В отличие от традиционного банковского кредита, DeFi borrowing часто не требует идентификации заемщика и оценки его кредитной истории. Вместо этого безопасность кредитора обеспечивается программными правилами и залогом. Такая модель повышает доступность, но переносит значительную часть риска и ответственности на пользователя.</p>'
            ],

            'collateral' => [
                'title' => 'Что такое collateral в DeFi | TM Wiki',
                'description' => 'Collateral — залог, который пользователь предоставляет DeFi-протоколу для обеспечения займа или другой финансовой позиции.',
                'name' => 'Collateral',
                'caption' => 'Залог, обеспечивающий обязательство',
                'definition' => '<p><strong>Collateral</strong> — это актив, который пользователь предоставляет в качестве обеспечения для займа или другой позиции в DeFi-протоколе. Залог снижает риск кредитора: если заемщик не выполняет условия протокола или стоимость позиции становится слишком низкой, часть обеспечения может быть продана в рамках ликвидации.</p>

                <p>В децентрализованных кредитных системах залог обычно блокируется в <span class="term" data-term="blockchain/smart-contract">смарт-контракте</span>. Пользователь не передает его отдельному сотруднику или кредитной организации. Контракт автоматически контролирует параметры позиции и доступный объем заимствования.</p>

                <p>Часто используется избыточное обеспечение. Например, протокол может разрешать занять активов на сумму, меньшую стоимости залога. Это создает запас прочности на случай изменения рыночной цены. Конкретный уровень определяется параметрами риска для каждого актива.</p>

                <p>Стоимость collateral должна регулярно оцениваться. Для этого протоколу требуется надежный источник рыночной информации, обычно через <span class="term" data-term="defi/price-oracle">ценовой оракул</span>. Если цена залога снижается, отношение стоимости обеспечения к долгу ухудшается.</p>

                <p>Если позиция достигает установленного <span class="term" data-term="defi/liquidation-threshold">порога ликвидации</span>, протокол может разрешить ликвидатору закрыть часть или всю позицию. Механизм необходим для защиты кредиторов и поддержания платежеспособности рынка.</p>

                <p>Collateral может использоваться и в более сложных DeFi-стратегиях. Один и тот же актив может быть залогом в одном протоколе, а полученные заемные средства — использоваться в другом. Такая компонуемость увеличивает эффективность капитала, но одновременно создает цепочку взаимосвязанных рисков.</p>'
            ],

            'collateralization-ratio' => [
                'title' => 'Что такое коэффициент обеспечения | TM Wiki',
                'description' => 'Коэффициент обеспечения показывает отношение стоимости залога к стоимости долга в DeFi-позиции.',
                'name' => 'Коэффициент обеспечения',
                'caption' => 'Отношение залога к сумме займа',
                'definition' => '<p><strong>Коэффициент обеспечения</strong> (collateralization ratio) показывает отношение стоимости залога к стоимости задолженности пользователя. Он используется в кредитных DeFi-протоколах для оценки того, насколько обеспечена заемная позиция.</p>

                <p>В упрощенном виде показатель рассчитывается как стоимость collateral, разделенная на стоимость долга. Например, если пользователь внес залог стоимостью 150 единиц и занял активов на 100 единиц, коэффициент обеспечения составляет 150%.</p>

                <p>Чем выше коэффициент, тем больше запас стоимости между залогом и долгом. Если стоимость collateral снижается, коэффициент также уменьшается. При достижении определенного уровня позиция может стать подверженной ликвидации.</p>

                <p>Необходимо отличать коэффициент обеспечения от <span class="term" data-term="defi/liquidation-threshold">порога ликвидации</span>. Первый описывает текущее состояние позиции, а второй представляет собой параметр протокола, при достижении которого применяются правила ликвидации. В некоторых протоколах также существует отдельный параметр loan-to-value, который выражает отношение долга к стоимости залога.</p>

                <p>Расчет коэффициента зависит от цен, получаемых протоколом через <span class="term" data-term="defi/price-oracle">ценовой оракул</span>. Поэтому надежность оракула непосредственно влияет на безопасность кредитной системы.</p>

                <p>Пользователь может самостоятельно повышать коэффициент обеспечения, добавляя collateral или погашая часть долга. Такие действия увеличивают запас прочности позиции и уменьшают вероятность ликвидации при неблагоприятном изменении цены.</p>'
            ],

            'liquidation-threshold' => [
                'title' => 'Что такое порог ликвидации | TM Wiki',
                'description' => 'Порог ликвидации определяет уровень риска, при котором DeFi-протокол может начать принудительное закрытие заемной позиции.',
                'name' => 'Порог ликвидации',
                'caption' => 'Уровень, при котором позиция становится ликвидируемой',
                'definition' => '<p><strong>Порог ликвидации</strong> — параметр кредитного DeFi-протокола, определяющий состояние, при котором заемная позиция становится доступной для принудительного закрытия или частичной ликвидации. Он нужен для защиты кредиторов и поддержания достаточного обеспечения системы.</p>

                <p>Положение пользователя зависит от стоимости его <span class="term" data-term="defi/collateral">залога</span> и задолженности. Если цена залога падает, стоимость обеспечения относительно долга уменьшается. При достижении установленного порога протокол может разрешить ликвидаторам погасить долг и получить часть залога в соответствии с правилами системы.</p>

                <p>Порог рассчитывается не самим пользователем, а определяется параметрами конкретного протокола и актива. Для разных типов collateral могут использоваться разные уровни риска, поскольку волатильность, ликвидность и рыночная глубина активов отличаются.</p>

                <p>Например, более волатильный актив может требовать большего запаса обеспечения. Если его цена быстро падает, ликвидатору необходимо иметь возможность закрыть позицию до того, как стоимость залога станет недостаточной для покрытия задолженности.</p>

                <p>Цена collateral обычно определяется через <span class="term" data-term="defi/price-oracle">ценовой оракул</span>. Поэтому ошибка или манипуляция источником цены может привести к неправильной оценке позиции и потенциальным проблемам с ликвидациями.</p>

                <p>Порог ликвидации не следует воспринимать как гарантированную точку, в которой пользователь успеет самостоятельно закрыть позицию. При высокой волатильности, перегруженности сети или недостаточной ликвидности фактическое исполнение может происходить в быстро меняющихся условиях.</p>'
            ],

            'decentralized-lending' => [
                'title' => 'Что такое decentralized lending | TM Wiki',
                'description' => 'Decentralized lending — децентрализованное кредитование через смарт-контракты без традиционного кредитного посредника.',
                'name' => 'Децентрализованное кредитование',
                'caption' => 'Кредитование через блокчейн и смарт-контракты',
                'definition' => '<p><strong>Децентрализованное кредитование</strong> — механизм предоставления и получения криптоактивов в долг через DeFi-протоколы и <span class="term" data-term="blockchain/smart-contract">смарт-контракты</span>. Вместо банка или другой централизованной кредитной организации правила работы рынка задаются программным кодом.</p>

                <p>Поставщики капитала вносят активы в протокол и получают доход в форме процентов или других вознаграждений. Заемщики предоставляют <span class="term" data-term="defi/collateral">обеспечение</span> и получают возможность использовать активы из соответствующего резерва.</p>

                <p>Кредитный рынок автоматически учитывает доступную ликвидность, задолженность, процентные ставки и состояние обеспечения. Если позиция становится недостаточно обеспеченной, может запускаться ликвидационный механизм.</p>

                <p>Большинство современных систем использует избыточное обеспечение, поскольку протокол не располагает традиционным механизмом взыскания долга с физического лица. В случае проблем система должна иметь возможность реализовать залог непосредственно через блокчейн.</p>

                <p>Децентрализованное кредитование может использоваться для получения ликвидности без продажи активов, торговли, хеджирования и построения более сложных <span class="term" data-term="defi/yield-farming">yield farming</span>-стратегий. Однако комбинирование нескольких протоколов увеличивает системный риск.</p>

                <p>К основным рискам относятся уязвимости смарт-контрактов, ошибки ценовых оракулов, резкие изменения рынка, недостаточная ликвидность и ошибки пользователя. В отличие от банковского депозита, средства не обязательно защищены государственным страхованием или централизованной системой компенсации.</p>'
            ],

            'flash-loan' => [
                'title' => 'Что такое flash loan | TM Wiki',
                'description' => 'Flash loan — необеспеченный DeFi-займ, который должен быть полностью возвращен в рамках одной блокчейн-транзакции.',
                'name' => 'Flash loan',
                'caption' => 'Заем без залога внутри одной транзакции',
                'definition' => '<p><strong>Flash loan</strong> — механизм DeFi, позволяющий временно получить большой объем активов без традиционного залога при условии, что заем будет полностью возвращен в рамках той же <span class="term" data-term="blockchain/transaction">транзакции</span>. Если условие возврата не выполнено, вся операция обычно отменяется благодаря атомарности исполнения блокчейн-транзакции.</p>

                <p>Механика flash loan основана на программируемости <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span>. В рамках одной транзакции пользователь может получить средства, выполнить одну или несколько операций с другими протоколами и вернуть первоначальную сумму вместе с комиссией.</p>

                <p>Классический пример применения — арбитраж. Пользователь может временно получить актив, обменять его на одной площадке по одной цене, продать на другой по более высокой цене и вернуть заем. Если итоговой прибыли недостаточно для комиссии и других расходов, транзакция не должна завершиться успешно.</p>

                <p>Flash loans также могут использоваться для рефинансирования, изменения залоговой структуры, сложных обменных операций и других атомарных стратегий. При этом заемщик не обязан иметь капитал, равный размеру займа, поскольку средства существуют у него только в рамках исполнения транзакции.</p>

                <p>Flash loan не является безрисковым механизмом для протоколов. Его возможности могут использоваться в сложных экономических атаках, особенно если другой DeFi-протокол неправильно рассчитывает цены, баланс или условия операций. Наличие flash loan само по себе не является уязвимостью; проблема возникает при наличии логической ошибки в атакуемой системе.</p>

                <p>Важную роль играет атомарность. Если хотя бы одно обязательное условие транзакции не выполнено, состояние блокчейна после отклоненной транзакции не должно сохранять промежуточные изменения. Пользователь при этом обычно теряет комиссию сети за неуспешную попытку, если транзакция была включена в блок.</p>'
            ],

            'oracle' => [
                'title' => 'Что такое oracle в блокчейне | TM Wiki',
                'description' => 'Oracle — механизм передачи внешних данных в блокчейн и смарт-контракты, которые не могут напрямую получать информацию из внешнего мира.',
                'name' => 'Oracle',
                'caption' => 'Источник внешних данных для смарт-контрактов',
                'definition' => '<p><strong>Oracle</strong> — механизм, который предоставляет <span class="term" data-term="blockchain/smart-contract">смарт-контрактам</span> данные, отсутствующие непосредственно в состоянии <span class="term" data-term="blockchain/blockchain">блокчейна</span>. Оракулы особенно важны для DeFi, поскольку финансовым протоколам часто необходимо знать цены активов, курсы обмена и другие внешние параметры.</p>

                <p>Проблема возникает из-за изоляции блокчейна. Смарт-контракт может надежно обращаться к данным, записанным в самой сети, но он не может просто отправить HTTP-запрос на внешний сайт и считать его результат частью консенсуса. Для получения внешней информации нужен специальный механизм доставки и проверки данных.</p>

                <p>Оракул может собирать данные из нескольких источников и передавать их в блокчейн. В зависимости от архитектуры используются различные методы агрегирования, подписания и обновления информации. Важной задачей является снижение риска того, что один ошибочный или манипулируемый источник повлияет на финансовые операции.</p>

                <p>В DeFi оракулы могут использоваться для определения стоимости <span class="term" data-term="defi/collateral">залога</span>, расчета <span class="term" data-term="defi/liquidation-threshold">порогов ликвидации</span>, определения стоимости активов в кредитных протоколах и других финансовых операций.</p>

                <p>Oracle является критически важным компонентом безопасности. Если протокол получает неправильную цену, злоумышленник потенциально может занять слишком большой объем средств, вывести недостаточно обеспеченные активы или вызвать нежелательную ликвидацию. Поэтому качество источников данных, частота обновления и устойчивость к манипуляциям имеют большое значение.</p>

                <p>Оракулы бывают централизованными, децентрализованными, основанными на нескольких источниках или использующими специальные криптографические механизмы. Поэтому само наличие слова oracle в архитектуре не говорит о степени децентрализации или надежности системы.</p>'
            ],

            'price-oracle' => [
                'title' => 'Что такое price oracle | TM Wiki',
                'description' => 'Price oracle предоставляет DeFi-протоколам данные о рыночной цене криптоактивов для расчетов и управления риском.',
                'name' => 'Ценовой оракул',
                'caption' => 'Источник рыночных цен для DeFi',
                'definition' => '<p><strong>Ценовой оракул</strong> — специализированный тип <span class="term" data-term="defi/oracle">оракула</span>, который передает смарт-контрактам информацию о рыночной стоимости активов. Такие данные используются там, где протоколу необходимо сравнивать стоимость разных активов или контролировать финансовые риски.</p>

                <p>Например, кредитному протоколу необходимо знать стоимость <span class="term" data-term="defi/collateral">залога</span>, чтобы определить, сколько пользователь может занять и не достигла ли позиция <span class="term" data-term="defi/liquidation-threshold">порога ликвидации</span>. Без надежной цены протокол не сможет корректно оценить обеспеченность займа.</p>

                <p>Цена может формироваться на основе нескольких рыночных источников. Использование одного источника создает риск манипуляции или сбоя. Агрегирование нескольких источников позволяет получить более устойчивую оценку, хотя не устраняет все возможные проблемы.</p>

                <p>Важна не только сама цена, но и ее своевременность. Если рынок быстро движется, устаревшее значение может существенно отличаться от текущей цены. Поэтому протокол должен определять правила обновления данных и допустимый уровень задержки.</p>

                <p>Цена также может зависеть от ликвидности конкретного рынка. Низколиквидный актив легче подвергнуть ценовому воздействию, поэтому использование цены с небольшой или манипулируемой торговой площадки может создать угрозу всему протоколу.</p>

                <p>Ценовой оракул особенно важен для кредитования, деривативов, стейблкоинов и других финансовых приложений. Ошибка в нем может повлиять на <span class="term" data-term="defi/borrowing">заимствования</span>, ликвидации и стоимость активов внутри протокола.</p>'
            ],

            'total-value-locked' => [
                'title' => 'Что такое TVL | TM Wiki',
                'description' => 'TVL показывает совокупную стоимость активов, размещенных в DeFi-протоколе, сети или экосистеме.',
                'name' => 'Total Value Locked',
                'caption' => 'Объем активов, заблокированных в DeFi',
                'definition' => '<p><strong>Total Value Locked (TVL)</strong> — показатель, который отражает совокупную стоимость криптоактивов, размещенных в определенном DeFi-протоколе, приложении, сети или экосистеме. Термин буквально означает «общая заблокированная стоимость», хотя конкретный метод расчета зависит от аналитической платформы и выбранной методологии.</p>

                <p>TVL может включать активы в <span class="term" data-term="defi/liquidity-pool">пуле ликвидности</span>, депозиты в кредитном протоколе, залоги и другие средства, которыми управляют соответствующие смарт-контракты. Для каждого протокола необходимо смотреть, какие именно позиции включены в показатель.</p>

                <p>Для перевода количества токенов в денежную стоимость используется рыночная цена. Поэтому TVL может изменяться даже без внесения или вывода капитала. Если цена активов выросла, долларовый TVL может увеличиться, а если цена упала — уменьшиться.</p>

                <p>TVL часто используется для сравнения размера различных DeFi-протоколов. Большой TVL может указывать на значительный объем капитала, но сам по себе не является доказательством безопасности, прибыльности или качества протокола.</p>

                <p>Показатель необходимо анализировать вместе с другими метриками: объемом торгов, доходами протокола, количеством пользователей, ликвидностью конкретных рынков, концентрацией капитала и историей безопасности. Один и тот же капитал также может учитываться в нескольких связанных протоколах, поэтому агрегирование TVL требует осторожности.</p>

                <p>TVL особенно полезен как динамический показатель. Изменение TVL во времени может показывать приток или отток капитала, реакцию пользователей на изменение стимулов или изменение рыночной стоимости активов. Однако интерпретация должна учитывать, какая часть изменения вызвана реальными потоками средств, а какая — изменением цен.</p>'
            ],

            'impermanent-loss' => [
                'title' => 'Что такое impermanent loss | TM Wiki',
                'description' => 'Impermanent loss — относительное снижение стоимости позиции поставщика ликвидности по сравнению с простым удержанием тех же активов вне пула.',
                'name' => 'Impermanent loss',
                'caption' => 'Потери поставщика ликвидности из-за изменения цен',
                'definition' => '<p><strong>Impermanent loss</strong> — это относительное отклонение стоимости позиции поставщика ликвидности от стоимости тех же активов при простом удержании вне <span class="term" data-term="defi/liquidity-pool">пула ликвидности</span>. Эффект возникает в основном в пулах, где механизм автоматически изменяет количество активов в позиции в ответ на изменение их относительных цен.</p>

                <p>Рассмотрим упрощенный пул из двух активов. Если цена одного актива значительно меняется относительно другого, арбитражные трейдеры совершают сделки с пулом, пока цена внутри пула не приблизится к внешнему рынку. В результате количество каждого актива, принадлежащего поставщику ликвидности, изменяется.</p>

                <p>Если затем сравнить стоимость этой позиции со стоимостью первоначального набора активов, который просто хранился бы без участия в пуле, разница может оказаться отрицательной. Именно эта относительная разница и называется impermanent loss.</p>

                <p>Название «непостоянные потери» связано с тем, что эффект зависит от текущего состояния цен. Если относительная цена активов возвращается к исходному уровню, расчетный impermanent loss может уменьшиться или исчезнуть. Однако если пользователь выводит ликвидность при неблагоприятном соотношении цен, относительная потеря становится реализованной.</p>

                <p>Impermanent loss не означает, что пользователь обязательно потерял деньги в абсолютном выражении. Позиция может одновременно приносить торговые комиссии и другие вознаграждения. Поэтому итоговый финансовый результат определяется сравнением всех доходов и потерь.</p>

                <h3>Что влияет на размер impermanent loss</h3>

                <ul>
                    <li>изменение относительной цены активов;</li>
                    <li>структура и математическая модель пула;</li>
                    <li>время нахождения средств в пуле;</li>
                    <li>полученные торговые комиссии;</li>
                    <li>дополнительные вознаграждения протокола;</li>
                    <li>изменение стоимости самих активов.</li>
                </ul>

                <p>При анализе позиции поставщика ликвидности необходимо учитывать impermanent loss вместе с комиссиями, стоимостью газа, изменением цены активов и риском смарт-контракта. Простое сравнение отображаемой APY с доходностью обычного хранения активов может давать неполную картину.</p>'
            ],

            'swap' => [
                'title' => 'Что такое swap в криптовалюте | TM Wiki',
                'description' => 'Swap — обмен одного криптоактива на другой через DeFi-протокол, AMM или другой механизм обмена.',
                'name' => 'Swap',
                'caption' => 'Обмен одного криптоактива на другой',
                'definition' => '<p><strong>Swap</strong> — операция обмена одного криптоактива на другой. В DeFi swap обычно выполняется через <span class="term" data-term="defi/dapp">dApp</span>, который взаимодействует со смарт-контрактом <span class="term" data-term="defi/liquidity-pool">пула ликвидности</span> или другого механизма обмена.</p>

                <p>В отличие от централизованной биржи, где сделка может проходить через <span class="term" data-term="crypto-trading/order-book">стакан заявок</span> и <span class="term" data-term="crypto-exchanges/matching-engine">matching engine</span>, DeFi swap часто использует <span class="term" data-term="defi/automated-market-maker">AMM</span>. Цена тогда определяется состоянием ликвидности и математической моделью конкретного пула.</p>

                <p>Перед выполнением swap пользователь обычно указывает входной актив, выходной актив и количество. Интерфейс показывает предполагаемый результат и может рассчитывать минимально допустимое количество получаемого актива. Это значение связано с параметром <span class="term" data-term="defi/slippage-tolerance">допустимого проскальзывания</span>.</p>

                <p>На итоговую стоимость операции влияют цена в пуле, размер сделки, ликвидность, комиссия протокола и <span class="term" data-term="crypto-trading/slippage">проскальзывание</span>. Кроме того, пользователь платит <span class="term" data-term="blockchain/transaction-fee">комиссию блокчейна</span> за выполнение транзакции, если это предусмотрено используемой сетью.</p>

                <p>Swap может происходить напрямую между двумя активами или через несколько промежуточных рынков. Например, для обмена Token A на Token C маршрутизатор может использовать пары A/B и B/C. Такой маршрут может дать лучший результат, но содержит больше операций и может увеличить совокупные комиссии.</p>

                <p>Пользователю важно проверять сеть, адреса токенов и конечные параметры операции. Особенно это важно для токенов с похожими названиями и при взаимодействии с неизвестными dApp. Подписание транзакции не означает автоматическую безопасность операции: необходимо понимать, какое действие пользователь разрешает смарт-контракту.</p>'
            ],

            'slippage-tolerance' => [
                'title' => 'Что такое slippage tolerance | TM Wiki',
                'description' => 'Slippage tolerance определяет максимально допустимое отклонение результата swap от ожидаемой цены.',
                'name' => 'Допустимое проскальзывание',
                'caption' => 'Предел изменения цены для swap',
                'definition' => '<p><strong>Slippage tolerance</strong> — параметр, который определяет, насколько итоговый результат обмена может отклониться от ожидаемого до того, как транзакция будет отклонена. Он особенно важен при торговле через <span class="term" data-term="defi/automated-market-maker">AMM</span> и <span class="term" data-term="defi/liquidity-pool">пулы ликвидности</span>.</p>

                <p>Цена, которую пользователь видит перед отправкой операции, не обязательно будет окончательной. Между формированием и включением <span class="term" data-term="blockchain/transaction">транзакции</span> в блок состояние пула может измениться. Другие пользователи могут совершить сделки, изменив резервы и, следовательно, цену.</p>

                <p>Slippage tolerance задает границу допустимого изменения. Если пользователь ожидает получить определенное количество токенов, контракт может быть настроен так, чтобы отменить операцию, если фактический результат окажется хуже установленного минимального значения.</p>

                <p>Слишком низкий параметр повышает вероятность того, что транзакция не выполнится. Слишком высокий параметр позволяет операции исполниться при существенно менее выгодной цене. Поэтому значение должно соответствовать ликвидности рынка и характеру операции.</p>

                <p>Необходимо отличать допустимое проскальзывание от фактического <span class="term" data-term="crypto-trading/slippage">проскальзывания</span>. Slippage tolerance — это ограничение, заданное пользователем, а slippage — фактическое изменение цены или исполнения относительно ожидаемого уровня.</p>

                <p>На некоторых рынках особенно важно учитывать риск неблагоприятного исполнения, если актив имеет низкую ликвидность или высокую волатильность. Дополнительное внимание требуется при использовании неизвестных интерфейсов, поскольку чрезмерно высокий tolerance может расширить диапазон цены, при котором операция будет принята.</p>'
            ],

            'dao' => [
                'title' => 'Что такое DAO | TM Wiki',
                'description' => 'DAO — децентрализованная организация, в которой правила управления реализуются через блокчейн, токены и смарт-контракты.',
                'name' => 'DAO',
                'caption' => 'Децентрализованная модель управления',
                'definition' => '<p><strong>DAO</strong> (Decentralized Autonomous Organization) — организационная модель, в которой правила управления и принятия решений реализуются с использованием <span class="term" data-term="blockchain/blockchain">блокчейна</span>, <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span> и механизмов голосования. DAO часто используются для управления DeFi-протоколами, параметрами их работы, казной и развитием экосистемы.</p>

                <p>Участники DAO могут вносить предложения, обсуждать их и голосовать. В зависимости от архитектуры право голоса может определяться количеством governance-токенов, делегированными голосами или другой системой. Не все DAO используют одинаковую модель, поэтому наличие токена управления не означает автоматически равное влияние всех участников.</p>

                <p>Решения могут касаться различных параметров протокола: комиссий, лимитов риска, поддерживаемых активов, распределения казны, обновления контрактов или других экономических правил. В некоторых системах результат голосования автоматически исполняется смарт-контрактом, в других между голосованием и исполнением существует дополнительный этап.</p>

                <p>DAO часто связано с казной, содержащей <span class="term" data-term="cryptocurrency/crypto-asset">криптоактивы</span> и токены. Управление казной может осуществляться через <span class="term" data-term="crypto-wallets/multisig">multisig</span>, timelock-контракты или другие механизмы. Поэтому фактическая степень автоматизации зависит от конкретной реализации.</p>

                <p>DAO не гарантирует полную децентрализацию. Большая доля governance-токенов может находиться у небольшого числа участников, а ключевые технические компоненты могут оставаться под контролем ограниченной группы. Кроме того, низкая явка на голосованиях может приводить к тому, что формальное право участия значительно отличается от фактического влияния.</p>

                <p>В DeFi DAO играет роль координационного слоя. Сам финансовый протокол может выполнять операции автоматически, а DAO определяет его долгосрочные параметры и правила. Таким образом, децентрализованное управление может быть отделено от непосредственного исполнения финансовых операций.</p>

                <h3>Основные элементы DAO</h3>

                <ul>
                    <li><strong>Proposal</strong> — предложение об изменении или действии.</li>
                    <li><strong>Governance</strong> — система управления и принятия решений.</li>
                    <li><strong>Voting</strong> — механизм голосования участников.</li>
                    <li><strong>Treasury</strong> — активы, которыми управляет организация.</li>
                    <li><strong>Execution</strong> — механизм фактического применения принятого решения.</li>
                </ul>'
            ],
        ],
    ],

    'staking' => [
        'title' => 'Термины стейкинга и PoS',
        'description' => 'Словарь терминов стейкинга и Proof-of-Stake: валидаторы, делегирование, staking, slashing, APR, APY и другие понятия.',
        'name' => 'Стейкинг',
        'caption' => 'Термины стейкинга и Proof-of-Stake: валидаторы, делегирование, награды, slashing, APR, APY и другие понятия.',
        'terms' => [
            'staking' => [
                'title' => 'Что такое стейкинг | TM Wiki',
                'description' => 'Стейкинг — способ участвовать в Proof-of-Stake и получать вознаграждение за блокировку криптоактивов.',
                'name' => 'Стейкинг',
                'caption' => 'Участие в Proof-of-Stake через блокировку криптоактивов',
                'definition' => '<p><strong>Стейкинг</strong> — механизм участия в работе блокчейна, использующего <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span> или родственный ему <span class="term" data-term="staking/delegated-proof-of-stake">Delegated Proof-of-Stake</span>. Пользователь блокирует или делегирует определенное количество нативных монет сети, а взамен может получать <span class="term" data-term="staking/staking-reward">вознаграждение за стейкинг</span>. В зависимости от архитектуры сети стейкинг может использоваться для выбора участников, подтверждающих блоки, обеспечения экономической безопасности сети и распределения новых монет или комиссий.</p>

                <p>Стейкинг принципиально отличается от <span class="term" data-term="mining/mining">майнинга</span> в сетях с <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span>. В Proof-of-Work участники расходуют вычислительные ресурсы и электроэнергию, а в Proof-of-Stake экономическим ресурсом служит капитал, поставленный под риск. Поэтому для стейкинга обычно не требуется <span class="term" data-term="mining-equipment/asic-miner">ASIC-майнер</span> или <span class="term" data-term="mining-equipment/gpu-rig">GPU-ферма</span>: пользователь может делегировать монеты существующему <span class="term" data-term="staking/validator">валидатору</span> либо самостоятельно запустить <span class="term" data-term="staking/validator-node">узел валидатора</span>.</p>

                <p>Экономический результат стейкинга не следует автоматически считать прибылью. Полученные награды обычно выражаются в нативном активе сети, поэтому их стоимость в фиатной валюте зависит от курса <span class="term" data-term="cryptocurrency/coin">монеты</span>. Кроме того, на итоговую доходность могут влиять комиссия валидатора, инфляция предложения, период блокировки, период разблокировки, штрафы и другие параметры конкретного протокола.</p>

                <h3>Как работает стейкинг</h3>

                <p>В простой модели пользователь выбирает сеть и способ участия, приобретает или уже имеет ее нативный актив и направляет его в механизм стейкинга. Средства могут быть непосредственно связаны с валидатором либо заблокированы через специальный смарт-контракт. После этого протокол учитывает экономический вес участника при выборе валидаторов и распределении вознаграждений.</p>

                <ul>
                    <li>пользователь блокирует или делегирует актив;</li>
                    <li>актив становится частью экономической безопасности сети;</li>
                    <li>валидатор участвует в создании и подтверждении блоков;</li>
                    <li>протокол начисляет вознаграждения в соответствии со своими правилами;</li>
                    <li>из вознаграждения может вычитаться <span class="term" data-term="staking/validator-commission">комиссия валидатора</span>;</li>
                    <li>при нарушении правил протокола к валидатору могут применяться санкции, включая <span class="term" data-term="staking/slashing">slashing</span>.</li>
                </ul>

                <p>Конкретная механика существенно различается между блокчейнами. Поэтому слово «стейкинг» не означает единую операцию, одинаковую во всех сетях. В одной сети делегирование может позволять пользователю сохранять прямой контроль над активами, в другой для участия требуется взаимодействие со смарт-контрактом, а в третьей используются собственные модели блокировки и распределения наград.</p>

                <h3>Что определяет доходность</h3>

                <p>Доходность стейкинга обычно рассматривают через <span class="term" data-term="staking/staking-apr">APR</span> или <span class="term" data-term="staking/staking-apy">APY</span>. Эти показатели могут выглядеть высокими, но сами по себе не гарантируют положительный результат в фиатном выражении. Например, если пользователь получает больше монет, но рыночная цена монеты снижается сильнее, стоимость позиции может уменьшиться.</p>

                <p>На результат также влияет эмиссия сети. Если протокол выпускает новые монеты для финансирования вознаграждений, часть доходности может компенсироваться размыванием доли владельца в общем предложении. Поэтому при анализе стейкинга полезно отдельно рассматривать номинальную награду, реальную доходность после инфляции, комиссии, изменение курса и условия вывода средств.</p>

                <h3>Основные формы участия</h3>

                <ul>
                    <li><strong>Самостоятельный валидатор</strong> — пользователь запускает <span class="term" data-term="staking/validator-node">узел валидатора</span> и отвечает за его работу.</li>
                    <li><strong>Делегирование</strong> — пользователь передает экономический вес выбранному валидатору без необходимости самостоятельно обслуживать инфраструктуру.</li>
                    <li><strong>Ликвидный стейкинг</strong> — пользователь размещает актив через специальный протокол и получает <span class="term" data-term="staking/liquid-staking-token">ликвидный токен стейкинга</span>, который может использоваться в других приложениях.</li>
                    <li><strong>Рестейкинг</strong> — уже застейканный актив или его производное используется для обеспечения дополнительного набора сервисов или протоколов.</li>
                </ul>

                <p>Таким образом, стейкинг объединяет технический механизм консенсуса и экономическую модель блокчейна. Для оценки конкретного варианта необходимо смотреть не только на заявленный процент доходности, но и на требования к капиталу, риски валидатора, период блокировки, условия вывода, комиссию, правила штрафов и свойства самого криптоактива.</p>'
            ],

            'proof-of-stake' => [
                'title' => 'Что такое Proof-of-Stake | TM Wiki',
                'description' => 'Proof-of-Stake — механизм консенсуса, в котором участники используют застейканные активы для защиты блокчейна.',
                'name' => 'Proof-of-Stake',
                'caption' => 'Консенсус на основе экономически обеспеченного стейкинга',
                'definition' => '<p><strong>Proof-of-Stake (PoS)</strong> — механизм <span class="term" data-term="blockchain/consensus">консенсуса</span>, при котором безопасность блокчейна обеспечивается экономически заинтересованными участниками, размещающими криптоактивы в стейкинге. Такие участники обычно называются <span class="term" data-term="staking/validator">валидаторами</span>. Протокол выбирает валидаторов для выполнения определенных действий, связанных с созданием, подтверждением и финализацией <span class="term" data-term="blockchain/block">блоков</span>, а нарушение правил может привести к потере части поставленного обеспечения.</p>

                <p>Основная идея PoS заключается в том, что участник получает право или вероятность участвовать в консенсусе не за счет вычисления огромного количества хешей, как в <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span>, а благодаря экономическому обеспечению. Участник рискует собственным капиталом: если он действует в соответствии с правилами сети, он может получать вознаграждение, а при определенных нарушениях может подвергнуться <span class="term" data-term="staking/slashing">slashing</span>.</p>

                <h3>Зачем нужен Proof-of-Stake</h3>

                <p>Блокчейну требуется механизм, позволяющий распределенным узлам согласовать состояние общей <span class="term" data-term="blockchain/blockchain">блокчейн-сети</span>. Узлы должны определить, какие транзакции включаются в блоки и какая версия цепочки считается корректной. PoS решает эту задачу через набор правил выбора и проверки валидаторов, а также через экономические стимулы.</p>

                <p>Важной особенностью PoS является то, что безопасность протокола связана со стоимостью активов, находящихся под риском. Для атаки на сеть злоумышленнику в зависимости от конкретного протокола может потребоваться контролировать значительный объем стейка. При этом точная модель безопасности, пороги голосования и последствия атак различаются между реализациями PoS.</p>

                <h3>Типичный цикл PoS</h3>

                <ol>
                    <li>участники блокируют или делегируют активы;</li>
                    <li>протокол формирует набор активных валидаторов;</li>
                    <li>один или несколько валидаторов получают задания по созданию или подтверждению блока;</li>
                    <li>другие участники проверяют предложенные данные;</li>
                    <li>при выполнении условий консенсуса блок принимается сетью;</li>
                    <li>валидаторы получают вознаграждения или несут штрафы в зависимости от своего поведения.</li>
                </ol>

                <p>Разные PoS-сети используют различные правила выбора валидаторов, финализации и наказаний. Поэтому PoS следует рассматривать как семейство механизмов консенсуса, а не как полностью идентичный алгоритм для всех блокчейнов.</p>

                <h3>PoS и Proof-of-Work</h3>

                <p>В Proof-of-Work участники конкурируют вычислительными ресурсами и энергозатратами. В Proof-of-Stake основным экономическим ресурсом становится капитал. Это меняет структуру расходов и рисков: для PoS важны требования к стейку, надежность валидатора, сетевое соединение, программное обеспечение, правила штрафов и распределение вознаграждений, тогда как для PoW критически важны <span class="term" data-term="equipment-specifications/hashrate">хешрейт</span>, <span class="term" data-term="equipment-specifications/power-consumption">энергопотребление</span> и стоимость электроэнергии.</p>

                <p>PoS также не означает отсутствие инфраструктурных требований. Профессиональные валидаторы могут использовать серверы, резервное питание, мониторинг, сетевую инфраструктуру и системы удаленного управления. Надежность такой инфраструктуры напрямую влияет на способность валидатора стабильно выполнять обязанности.</p>'
            ],

            'validator' => [
                'title' => 'Что такое валидатор | TM Wiki',
                'description' => 'Валидатор — участник Proof-of-Stake, который помогает проверять транзакции и поддерживать консенсус блокчейна.',
                'name' => 'Валидатор',
                'caption' => 'Участник сети, отвечающий за операции консенсуса',
                'definition' => '<p><strong>Валидатор</strong> — участник блокчейна на базе <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>, который выполняет предусмотренные протоколом функции по проверке и подтверждению состояния сети. В зависимости от конкретного блокчейна валидатор может предлагать новые <span class="term" data-term="blockchain/block">блоки</span>, голосовать за блоки других участников, участвовать в их финализации и выполнять другие операции консенсуса.</p>

                <p>Для участия валидатор обычно должен иметь определенный объем собственного или делегированного стейка. Этот капитал является экономическим обеспечением поведения участника. Если валидатор работает корректно и доступен сети, он может получать <span class="term" data-term="staking/staking-reward">вознаграждения</span>. При некоторых нарушениях протокола или длительной недоступности могут применяться штрафы, а в определенных системах — <span class="term" data-term="staking/slashing">slashing</span>.</p>

                <h3>Что делает валидатор</h3>

                <ul>
                    <li>поддерживает работающий узел блокчейна;</li>
                    <li>получает и проверяет данные сети;</li>
                    <li>участвует в создании или подтверждении блоков;</li>
                    <li>подписывает предусмотренные протоколом сообщения;</li>
                    <li>поддерживает постоянное сетевое соединение;</li>
                    <li>следит за состоянием программного обеспечения и инфраструктуры;</li>
                    <li>управляет ключами, необходимыми для работы валидатора.</li>
                </ul>

                <p>Запуск валидатора требует большей технической ответственности, чем простое делегирование монет. Необходимо поддерживать <span class="term" data-term="staking/validator-node">узел валидатора</span>, обновлять программное обеспечение, защищать ключи, контролировать доступность сервера и отслеживать события сети.</p>

                <h3>Валидатор и делегатор</h3>

                <p><span class="term" data-term="staking/delegator">Делегатор</span> может передать свой экономический вес выбранному валидатору, не запуская собственную инфраструктуру. В таком случае валидатор выполняет техническую работу, а делегатор получает часть доступных наград после учета комиссии валидатора и правил конкретной сети.</p>

                <p>Выбор валидатора поэтому связан не только с размером ожидаемого вознаграждения. Важны история работы, комиссия, надежность инфраструктуры, правила сети, распределение стейка и условия делегирования. При этом прошлые показатели не гарантируют будущих результатов.</p>'
            ],

            'delegator' => [
                'title' => 'Что такое делегатор | TM Wiki',
                'description' => 'Делегатор — участник Proof-of-Stake, который передает свой стейк выбранному валидатору для участия в консенсусе.',
                'name' => 'Делегатор',
                'caption' => 'Владелец стейка, участвующий через делегирование',
                'definition' => '<p><strong>Делегатор</strong> — пользователь или организация, которые участвуют в <span class="term" data-term="staking/staking">стейкинге</span> через передачу экономического веса выбранному <span class="term" data-term="staking/validator">валидатору</span>. Делегатору не обязательно самостоятельно запускать <span class="term" data-term="staking/validator-node">узел валидатора</span>: техническую работу выполняет валидатор, а делегированный актив учитывается в механизме консенсуса конкретной сети.</p>

                <p>Делегирование обычно не означает передачу права собственности на монеты валидатору. Во многих PoS-сетях делегатор сохраняет контроль над своим аккаунтом и может инициировать операции, предусмотренные протоколом. Однако актив может быть связан с условиями стейкинга, включая <span class="term" data-term="staking/unbonding-period">период разблокировки</span> и ограничения на перевод средств.</p>

                <h3>Как работает делегирование</h3>

                <ol>
                    <li>делегатор выбирает валидатора;</li>
