                    <li>при выполнении условий сети начисляются вознаграждения;</li>
                    <li>из вознаграждения может удерживаться <span class="term" data-term="staking/validator-commission">комиссия валидатора</span>.</li>
                </ol>

                <p>Делегатор также принимает часть рисков, связанных с выбранным валидатором. В сетях, где штрафы распространяются на делегированный стейк, действия валидатора могут привести к финансовым последствиям для его делегаторов.</p>'
            ],

            'delegation' => [
                'title' => 'Что такое делегирование в стейкинге | TM Wiki',
                'description' => 'Делегирование — передача стейка валидатору для участия в Proof-of-Stake без самостоятельного запуска валидатора.',
                'name' => 'Делегирование',
                'caption' => 'Способ участвовать в PoS через выбранного валидатора',
                'definition' => '<p><strong>Делегирование</strong> — механизм, при котором владелец криптоактива назначает свой стейк определенному <span class="term" data-term="staking/validator">валидатору</span>. Делегированный капитал увеличивает экономический вес валидатора в соответствии с правилами конкретного <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>-протокола. Сам пользователь при этом может не запускать технический узел.</p>

                <p>Делегирование предназначено для разделения ролей. Валидатор отвечает за инфраструктуру и выполнение операций консенсуса, а <span class="term" data-term="staking/delegator">делегатор</span> предоставляет экономический вес. В некоторых сетях делегатор может самостоятельно голосовать, выбирать валидатора или перераспределять свой стейк между участниками.</p>

                <p>Важным параметром является период выхода из стейкинга. После отмены делегирования средства могут не становиться сразу доступными: протокол может устанавливать <span class="term" data-term="staking/unbonding-period">unbonding period</span>. Его продолжительность зависит от конкретной сети.</p>

                <p>Делегирование также связано с риском валидатора. Если протокол предусматривает экономические штрафы за определенные нарушения, делегированный стейк может участвовать в таких санкциях. Поэтому комиссия валидатора — только один из параметров, который имеет значение при выборе.</p>'
            ],

            'validator-node' => [
                'title' => 'Что такое узел валидатора | TM Wiki',
                'description' => 'Узел валидатора — серверная инфраструктура, которая позволяет участвовать в консенсусе Proof-of-Stake.',
                'name' => 'Узел валидатора',
                'caption' => 'Инфраструктура для работы валидатора блокчейна',
                'definition' => '<p><strong>Узел валидатора</strong> — программно-аппаратная инфраструктура, используемая валидатором для участия в консенсусе блокчейна. Обычно она включает сервер, программное обеспечение узла, сетевое соединение и криптографические ключи, необходимые для подписания сообщений протокола.</p>

                <p>Узел должен получать актуальное состояние <span class="term" data-term="blockchain/blockchain">блокчейна</span>, обрабатывать входящие данные и выполнять операции, предусмотренные протоколом. В зависимости от сети валидатор может создавать блоки, голосовать за предложения других валидаторов или участвовать в финализации.</p>

                <h3>Требования к инфраструктуре</h3>

                <ul>
                    <li>достаточная производительность CPU и памяти;</li>
                    <li>быстрое и стабильное сетевое соединение;</li>
                    <li>достаточный объем дискового пространства;</li>
                    <li>надежное питание и резервирование критических компонентов;</li>
                    <li>мониторинг доступности и состояния узла;</li>
                    <li>безопасное хранение ключей;</li>
                    <li>регулярное обновление программного обеспечения.</li>
                </ul>

                <p>Доступность узла особенно важна потому, что некоторые протоколы могут снижать вознаграждение или применять санкции к валидаторам, которые не выполняют необходимые действия. Более серьезные нарушения могут привести к <span class="term" data-term="staking/slashing">slashing</span>.</p>

                <p>В отличие от обычного <span class="term" data-term="blockchain/full-node">full node</span>, валидатор не просто хранит и проверяет состояние сети: он выполняет дополнительные функции, связанные с консенсусом. Конкретные требования зависят от протокола.</p>'
            ],

            'staking-reward' => [
                'title' => 'Что такое награда за стейкинг | TM Wiki',
                'description' => 'Награда за стейкинг — выплаты участникам Proof-of-Stake за выполнение предусмотренных протоколом функций.',
                'name' => 'Награда за стейкинг',
                'caption' => 'Вознаграждение за участие в механизме Proof-of-Stake',
                'definition' => '<p><strong>Награда за стейкинг</strong> — криптоактивы, начисляемые валидаторам и, в зависимости от модели сети, их делегаторам за участие в обеспечении работы <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>-сети. Источником награды могут быть новые выпущенные монеты, часть <span class="term" data-term="blockchain/transaction-fee">комиссий за транзакции</span> или комбинация нескольких источников.</p>

                <p>Размер награды зависит от правил конкретного протокола. На него могут влиять общий объем стейка, доля конкретного валидатора, его доступность, количество правильно выполненных обязанностей, комиссия валидатора и параметры эмиссии.</p>

                <p>Полученная награда не равна автоматически чистой доходности. Если актив испытывает инфляцию, меняется его рыночная цена или пользователь платит комиссии, фактический финансовый результат будет отличаться от номинальной ставки.</p>

                <h3>Пример</h3>

                <p>Если пользователь застейкал 100 монет и за определенный период получил 5 монет награды, номинальное увеличение количества монет составляет 5%. Но если за этот же период цена монеты снизилась на 20%, стоимость позиции в фиатной валюте может уменьшиться. Поэтому стейкинг следует оценивать одновременно в единицах актива и в выбранной расчетной валюте.</p>'
            ],

            'staking-yield' => [
                'title' => 'Что такое доходность стейкинга | TM Wiki',
                'description' => 'Доходность стейкинга показывает, сколько вознаграждения приносит размещенный актив за определенный период.',
                'name' => 'Доходность стейкинга',
                'caption' => 'Доход от размещения криптоактива в стейкинге',
                'definition' => '<p><strong>Доходность стейкинга</strong> — показатель того, сколько вознаграждения пользователь получает относительно объема застейканного капитала за определенный период. Ее могут выражать в процентах за год или другой интервал, а также в количестве полученных токенов.</p>

                <p>Доходность следует отличать от <span class="term" data-term="staking/staking-apr">APR</span> и <span class="term" data-term="staking/staking-apy">APY</span>: APR обычно представляет простую годовую ставку без учета реинвестирования, тогда как APY может учитывать компаундирование. Кроме того, рекламируемая ставка конкретного протокола может быть рассчитана до учета комиссии валидатора, инфляции или изменения курса актива.</p>

                <p>При сравнении вариантов стейкинга необходимо учитывать период блокировки, <span class="term" data-term="staking/unbonding-period">unbonding period</span>, вероятность штрафов, комиссию валидатора, изменение предложения монет и ликвидность позиции. Высокая номинальная ставка сама по себе не описывает весь риск и экономический результат.</p>'
            ],

            'staking-apr' => [
                'title' => 'Что такое Staking APR | TM Wiki',
                'description' => 'Staking APR — годовая простая ставка доходности стейкинга без учета эффекта реинвестирования наград.',
                'name' => 'Staking APR',
                'caption' => 'Годовая ставка стейкинга без компаундирования',
                'definition' => '<p><strong>Staking APR</strong> — показатель годовой процентной доходности стейкинга, обычно рассчитанный без учета автоматического реинвестирования полученных наград. Аббревиатура APR означает Annual Percentage Rate.</p>

                <p>Если APR равен 10%, упрощенная интерпретация состоит в том, что при неизменных условиях за год пользователь может получить награды примерно в размере 10% от первоначального объема стейка. В реальном протоколе ставка может изменяться из-за динамики эмиссии, общего объема стейка, активности сети и других параметров.</p>

                <p>APR обычно удобнее использовать для сравнения базовой ставки без компаундирования. Для оценки результата при регулярном реинвестировании используют <span class="term" data-term="staking/staking-apy">APY</span>. Однако и APR, и APY могут не учитывать изменение рыночной цены токена, комиссии и возможные штрафы.</p>'
            ],

            'staking-apy' => [
                'title' => 'Что такое Staking APY | TM Wiki',
                'description' => 'Staking APY — годовая эффективная доходность с учетом предполагаемого реинвестирования вознаграждений.',
                'name' => 'Staking APY',
                'caption' => 'Эффективная годовая доходность с компаундированием',
                'definition' => '<p><strong>Staking APY</strong> — показатель годовой эффективной доходности, который учитывает предполагаемое реинвестирование полученных наград. APY расшифровывается как Annual Percentage Yield.</p>

                <p>Если награды регулярно добавляются к застейканому капиталу и затем сами начинают приносить вознаграждение, итоговое количество монет может быть выше, чем при простом начислении по <span class="term" data-term="staking/staking-apr">APR</span>. Например, при частом реинвестировании ставка APY будет выше соответствующего простого APR.</p>

                <p>На практике опубликованный APY следует рассматривать как расчетный показатель. Для его реализации необходимо действительно реинвестировать награды с соответствующей частотой, а условия протокола должны оставаться достаточно стабильными. Комиссии, изменение ставки, ограничения на реинвестирование и рыночная цена актива могут изменить фактический результат.</p>'
            ],

            'unbonding-period' => [
                'title' => 'Что такое Unbonding Period | TM Wiki',
                'description' => 'Unbonding period — период, в течение которого застейканные активы становятся доступными после отмены делегирования.',
                'name' => 'Unbonding Period',
                'caption' => 'Период разблокировки средств после выхода из стейкинга',
                'definition' => '<p><strong>Unbonding period</strong> — установленный протоколом период между запросом на выход из стейкинга или отменой делегирования и моментом, когда актив снова становится доступным для свободного использования. Термин особенно распространен в сетях с делегированием.</p>

                <p>В течение этого периода актив обычно перестает участвовать в дальнейших циклах стейкинга, но еще не может быть переведен или потрачен как обычный баланс. Продолжительность определяется правилами конкретного блокчейна и может составлять от нескольких часов до нескольких недель или дольше.</p>

                <p>Наличие unbonding period является важным фактором ликвидности. Пользователь не всегда может немедленно продать актив или перевести его в другой протокол после подачи запроса на выход.</p>

                <p>Ликвидные формы стейкинга, такие как <span class="term" data-term="staking/liquid-staking">liquid staking</span>, создавались в том числе для того, чтобы уменьшить необходимость ждать такого периода: вместо прямого обращения с заблокированным активом пользователь получает производный <span class="term" data-term="staking/liquid-staking-token">ликвидный токен</span>. Это не устраняет связанные риски, а меняет модель управления ликвидностью.</p>'
            ],

            'bonding-period' => [
                'title' => 'Что такое Bonding Period | TM Wiki',
                'description' => 'Bonding period — период, в течение которого актив присоединяется к стейкингу и приобретает статус связанного стейка.',
                'name' => 'Bonding Period',
                'caption' => 'Период подключения актива к стейкингу',
                'definition' => '<p><strong>Bonding period</strong> — период, предусмотренный некоторыми блокчейнами для перевода актива в состояние, при котором он участвует в механизме стейкинга. Точная механика зависит от протокола: в одних сетях делегирование становится активным сразу, в других требуется дождаться следующего периода или определенного числа блоков.</p>

                <p>Bonding period следует отличать от <span class="term" data-term="staking/unbonding-period">unbonding period</span>. Первый относится к входу в механизм стейкинга, второй — к выходу из него. Оба параметра влияют на доступность капитала и должны учитываться при планировании ликвидности.</p>

                <p>Если пользователь переводит актив в стейкинг для получения <span class="term" data-term="staking/staking-reward">наград</span>, важно проверить, с какого момента протокол начинает начислять вознаграждение и существует ли задержка между делегированием и фактическим включением стейка.</p>'
            ],

            'lock-up-period' => [
                'title' => 'Что такое Lock-Up Period | TM Wiki',
                'description' => 'Lock-up period — период, в течение которого застейканные активы нельзя свободно вывести или перевести.',
                'name' => 'Lock-Up Period',
                'caption' => 'Период обязательной блокировки криптоактива',
                'definition' => '<p><strong>Lock-up period</strong> — установленный условиями протокола период, в течение которого актив остается заблокированным и не может свободно использоваться владельцем. В контексте стейкинга lock-up может применяться как к первоначальному размещению средств, так и к последующему периоду после запроса на выход.</p>

                <p>Lock-up period не является универсальным свойством всех PoS-сетей. Некоторые протоколы позволяют относительно быстро вывести актив, другие устанавливают фиксированный срок, а третьи используют отдельный <span class="term" data-term="staking/unbonding-period">unbonding period</span>.</p>

                <p>Чем дольше капитал заблокирован, тем ниже его непосредственная ликвидность. Это важно учитывать, если актив может понадобиться для <span class="term" data-term="defi/swap">обмена</span>, <span class="term" data-term="defi/lending-protocol">кредитования</span>, торговли или других операций.</p>'
            ],

            'slashing' => [
                'title' => 'Что такое Slashing | TM Wiki',
                'description' => 'Slashing — штраф в Proof-of-Stake, при котором валидатор может потерять часть застейканного капитала за определенные нарушения.',
                'name' => 'Slashing',
                'caption' => 'Экономическое наказание за нарушения правил PoS',
                'definition' => '<p><strong>Slashing</strong> — механизм экономического наказания в некоторых сетях <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>, при котором из стейка валидатора может быть изъята часть средств из-за определенного нарушения правил протокола. Цель slashing — сделать некоторые формы вредоносного или критически неправильного поведения экономически невыгодными.</p>

                <p>Важно отличать slashing от обычного снижения награды из-за низкой доступности. Пропуск части обязанностей может приводить к потере потенциального вознаграждения, тогда как slashing обычно означает фактическое уменьшение экономического обеспечения. Конкретные условия зависят от блокчейна.</p>

                <h3>Какие действия могут привести к slashing</h3>

                <p>Наиболее известный класс нарушений — одновременная подпись несовместимых сообщений, например голосование за два конкурирующих состояния сети в условиях, где это запрещено протоколом. Такое поведение может угрожать безопасности консенсуса. В некоторых сетях наказания также связаны с другими видами некорректного поведения.</p>

                <p>Точный размер штрафа определяется правилами сети. Он может зависеть от характера нарушения, размера стейка, количества других нарушений и состояния протокола. Поэтому нельзя использовать единый процент slashing для всех PoS-сетей.</p>

                <h3>Риск для делегаторов</h3>

                <p>В некоторых моделях штраф распространяется не только на собственные средства валидатора, но и на делегированный ему стейк. Поэтому <span class="term" data-term="staking/delegator">делегатор</span> принимает определенный риск выбранного валидатора, даже если сам не управляет сервером.</p>

                <p>Для снижения операционного риска валидаторы используют безопасную инфраструктуру, контроль ключей, резервирование и мониторинг. Особое значение имеет защита от ситуаций, когда две копии валидатора одновременно подписывают конфликтующие сообщения.</p>'
            ],

            'validator-commission' => [
                'title' => 'Что такое комиссия валидатора | TM Wiki',
                'description' => 'Комиссия валидатора — доля вознаграждения, которую валидатор удерживает за обслуживание делегированного стейка.',
                'name' => 'Комиссия валидатора',
                'caption' => 'Плата валидатору из полученных стейкинг-наград',
                'definition' => '<p><strong>Комиссия валидатора</strong> — процент или иная доля вознаграждения от стейкинга, которую валидатор удерживает за предоставление инфраструктуры и выполнение обязанностей в сети. Она обычно применяется к наградам, связанным с делегированным стейком.</p>

                <p>Например, если валидатор устанавливает комиссию 5%, это не обязательно означает, что 5% всего делегированного капитала передается валидатору. Обычно речь идет о доле соответствующего вознаграждения. Точная формула зависит от протокола.</p>

                <p>При сравнении валидаторов комиссия является только одним параметром. Также имеют значение надежность узла, доступность, история работы, распределение стейка, условия изменения комиссии и возможный риск <span class="term" data-term="staking/slashing">slashing</span>.</p>

                <p>Некоторые протоколы устанавливают минимальную или максимальную комиссию, а также правила изменения ставки. Поэтому пользователь должен смотреть не только на текущий процент, но и на условия, по которым валидатор может его изменить.</p>'
            ],

            'minimum-stake' => [
                'title' => 'Что такое Minimum Stake | TM Wiki',
                'description' => 'Minimum stake — минимальный объем криптоактива, необходимый для определенного вида участия в стейкинге.',
                'name' => 'Minimum Stake',
                'caption' => 'Минимальная сумма для участия в стейкинге',
                'definition' => '<p><strong>Minimum stake</strong> — минимальное количество криптоактива, которое требуется протоколом для определенного типа участия в <span class="term" data-term="staking/staking">стейкинге</span>. Это значение может относиться к самостоятельному запуску валидатора, делегированию или другому виду участия.</p>

                <p>Минимальный стейк нужен не во всех сетях и не обязательно одинаков для разных ролей. Например, протокол может требовать значительный минимальный объем для собственного валидатора, одновременно позволяя делегаторам участвовать с гораздо меньшей суммой.</p>

                <p>Минимальный порог может быть задан в нативных монетах, поэтому его эквивалент в фиатной валюте меняется вместе с рыночной ценой актива. При изменении параметров сети минимальный стейк также может быть пересмотрен.</p>'
            ],

            'liquid-staking' => [
                'title' => 'Что такое Liquid Staking | TM Wiki',
                'description' => 'Liquid staking позволяет получать ликвидный токен взамен застейканного актива и использовать его в других криптопротоколах.',
                'name' => 'Liquid Staking',
                'caption' => 'Стейкинг с сохранением производной ликвидной позиции',
                'definition' => '<p><strong>Liquid staking</strong> — модель стейкинга, при которой пользователь размещает актив в протоколе и получает взамен производный актив — <span class="term" data-term="staking/liquid-staking-token">ликвидный токен стейкинга</span>. Этот токен представляет экономическое право на исходный застейканный актив и связанные с ним накопленные результаты, согласно правилам конкретного протокола.</p>

                <p>Обычный стейкинг может ограничивать использование капитала из-за <span class="term" data-term="staking/unbonding-period">периода разблокировки</span>. Liquid staking позволяет вместо ожидания использовать полученный производный токен в других операциях, например в <span class="term" data-term="defi/lending-protocol">DeFi-кредитовании</span>, <span class="term" data-term="defi/liquidity-pool">пуле ликвидности</span> или <span class="term" data-term="defi/swap">обмене</span>.</p>

                <h3>Как работает liquid staking</h3>

                <ol>
                    <li>пользователь передает нативный актив протоколу;</li>
                    <li>протокол использует актив для стейкинга или организует его делегирование валидаторам;</li>
                    <li>пользователь получает производный ликвидный токен;</li>
                    <li>токен может обращаться отдельно от исходного актива;</li>
                    <li>стоимость или количество производного токена отражает правила накопления стейкинг-дохода;</li>
                    <li>для возврата исходного актива используются предусмотренные протоколом механизмы.</li>
                </ol>

                <p>Liquid staking не отменяет риски стейкинга. Пользователь получает дополнительный слой протокольного риска: помимо базового риска блокчейна и валидаторов появляется риск смарт-контрактов, механизмов выпуска токена, ликвидности и возможного отклонения его рыночной цены от ожидаемой стоимости базового актива.</p>

                <p>Если ликвидный токен используется в другом <span class="term" data-term="defi/defi">DeFi</span>-протоколе, риски могут складываться. Например, позиция может одновременно зависеть от стейкинга, смарт-контракта, ликвидности рынка и правил внешнего протокола.</p>'
            ],

            'liquid-staking-token' => [
                'title' => 'Что такое Liquid Staking Token | TM Wiki',
                'description' => 'Liquid staking token — производный токен, представляющий позицию пользователя в ликвидном стейкинге.',
                'name' => 'Liquid Staking Token',
                'caption' => 'Ликвидный токен, связанный с застейканным активом',
                'definition' => '<p><strong>Liquid staking token (LST)</strong> — производный криптоактив, который пользователь получает при участии в <span class="term" data-term="staking/liquid-staking">liquid staking</span>. Он представляет право или экономическую позицию, связанную с застейканным базовым активом, и может использоваться отдельно от самого актива.</p>

                <p>В зависимости от протокола стоимость или количество LST может отражать накопленные стейкинг-награды. Например, обменный курс между LST и базовым активом может постепенно изменяться, показывая накопленный результат стейкинга.</p>

                <p>Главное отличие LST от обычного застейканного баланса состоит в возможности использовать производный токен в других приложениях. Его можно применять в <span class="term" data-term="defi/liquidity-pool">пуле ликвидности</span>, <span class="term" data-term="defi/lending-protocol">кредитном протоколе</span> или для других операций, если соответствующее приложение поддерживает этот актив.</p>

                <p>Однако LST добавляет риски, которых нет у прямого владения базовым активом. К ним относятся риск смарт-контракта, риск механизма стейкинга, риск валидаторов, риск ликвидности и риск расхождения рыночной цены производного токена с расчетной стоимостью базового актива.</p>'
            ],

            'restaking' => [
                'title' => 'Что такое Restaking | TM Wiki',
                'description' => 'Restaking — использование уже застейканного актива для дополнительного обеспечения других сервисов или протоколов.',
                'name' => 'Restaking',
                'caption' => 'Повторное использование стейка для дополнительной экономической безопасности',
                'definition' => '<p><strong>Restaking</strong> — механизм, при котором актив, уже используемый для обеспечения <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>-сети, дополнительно используется для обеспечения других сервисов, протоколов или инфраструктурных компонентов. Идея заключается в повторном использовании существующего экономического обеспечения вместо создания полностью независимого набора стейка.</p>

                <p>В классической модели PoS застейканный актив обеспечивает безопасность основной блокчейн-сети. При restaking тот же экономический капитал может одновременно принимать дополнительные обязательства. В зависимости от реализации пользователь может принимать дополнительные условия и дополнительные риски наказания.</p>

                <h3>Зачем используется restaking</h3>

                <p>Новый протокол или сервис может нуждаться в экономической безопасности, но не иметь собственного крупного набора активов. Использование уже существующего стейка позволяет привлечь экономическую безопасность от участников существующей PoS-экосистемы.</p>

                <p>Для пользователя привлекательность модели может заключаться в возможности получать дополнительное вознаграждение поверх базовой доходности стейкинга. Однако дополнительное вознаграждение связано с дополнительными обязательствами и рисками, поэтому его нельзя рассматривать как бесплатное увеличение доходности.</p>

                <h3>Дополнительный риск</h3>

                <p>При restaking один и тот же капитал может быть связан сразу с несколькими системами. Ошибка или нарушение правил дополнительного сервиса может иметь последствия для позиции пользователя, если соответствующая архитектура предусматривает такую возможность. Поэтому необходимо отдельно анализировать условия базового стейкинга и каждого дополнительного сервиса.</p>

                <p>Restaking также может использовать <span class="term" data-term="staking/liquid-staking-token">ликвидные токены стейкинга</span> в качестве представления базовой позиции. В таком случае к рискам PoS добавляются риски производного токена и соответствующей инфраструктуры.</p>'
            ],

            'delegated-proof-of-stake' => [
                'title' => 'Что такое Delegated Proof-of-Stake | TM Wiki',
                'description' => 'Delegated Proof-of-Stake — модель консенсуса, где владельцы токенов делегируют голосующую силу выбранным производителям блоков.',
                'name' => 'Delegated Proof-of-Stake',
                'caption' => 'PoS-модель с делегированием голосующей силы',
                'definition' => '<p><strong>Delegated Proof-of-Stake (DPoS)</strong> — разновидность <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span>, в которой владельцы токенов используют свою экономическую или голосующую силу для выбора ограниченного набора участников, отвечающих за производство или подтверждение блоков. Эти участники могут называться делегатами, производителями блоков или иметь другое протокольное название.</p>

                <p>В классической модели пользователь может непосредственно делегировать актив валидатору, а в DPoS акцент часто делается на голосовании за ограниченный набор производителей блоков. Конкретная реализация существенно зависит от блокчейна, поэтому термин DPoS нельзя свести к одной универсальной формуле.</p>

                <h3>Основная модель</h3>

                <ol>
                    <li>владельцы токенов получают определенную голосующую силу;</li>
                    <li>они голосуют за участников, которые будут выполнять функции производства блоков;</li>
                    <li>выбранные участники работают в соответствии с расписанием или правилами протокола;</li>
                    <li>за корректную работу они могут получать вознаграждение;</li>
                    <li>владельцы токенов могут изменять свой выбор в соответствии с механизмом голосования сети.</li>
                </ol>

                <p>DPoS позволяет ограничить количество активных производителей блоков, что может упростить координацию и повысить пропускную способность конкретной архитектуры. Одновременно распределение влияния зависит от того, как устроено голосование и насколько широко распределены токены и голосующие права.</p>

                <p>DPoS следует отличать от общего понятия <span class="term" data-term="staking/delegation">делегирования</span>. Делегирование может быть лишь одной операцией внутри PoS-протокола, тогда как DPoS описывает более широкую архитектуру консенсуса с выбором производителей блоков через голосование держателей токенов.</p>'
            ],
        ],
    ],

    'security' => [
        'title' => 'Термины безопасности криптовалют',
        'description' => 'Словарь терминов безопасности криптовалют: приватные ключи, seed-фразы, 2FA, multisig, cold storage и другие понятия.',
        'name' => 'Безопасность',
        'caption' => 'Термины безопасности криптовалют и блокчейна: приватные ключи, seed-фразы, 2FA, multisig, холодное хранение и другие понятия.',
        'terms' => [
            'crypto-security' => [
                'title' => 'Что такое безопасность криптовалют | TM Wiki',
                'description' => 'Безопасность криптовалют включает защиту ключей, кошельков, транзакций, аккаунтов и блокчейн-инфраструктуры.',
                'name' => 'Безопасность криптовалют',
                'caption' => 'Защита криптоактивов, кошельков и блокчейн-систем',
                'definition' => '<p><strong>Безопасность криптовалют</strong> — совокупность методов, технологий и организационных мер, направленных на защиту <span class="term" data-term="cryptocurrency/crypto-asset">криптоактивов</span>, кошельков, аккаунтов, транзакций, смарт-контрактов и блокчейн-инфраструктуры от кражи, подделки, несанкционированного доступа и других атак.</p>

                <p>В отличие от традиционных финансовых систем, криптовалютная безопасность во многом зависит от самого владельца актива. Потеря <span class="term" data-term="crypto-wallets/private-key">приватного ключа</span> или <span class="term" data-term="crypto-wallets/seed-phrase">seed-фразы</span> может привести к безвозвратной потере доступа к средствам, если не существует другой формы восстановления.</p>

                <p>Безопасность криптовалют охватывает несколько уровней. На уровне блокчейна важны <span class="term" data-term="blockchain/consensus">консенсус</span>, защита от атак на сеть и корректность обработки <span class="term" data-term="blockchain/transaction">транзакций</span>. На уровне пользователя важны <span class="term" data-term="crypto-wallets/self-custody">самостоятельное хранение</span>, защита ключей и аутентификация. На уровне приложений важны безопасность <span class="term" data-term="blockchain/smart-contract">смарт-контрактов</span>, контроль доступа и аудит кода.</p>

                <h3>Основные уровни безопасности</h3>

                <ul>
                    <li><strong>Безопасность блокчейна</strong> — защита <span class="term" data-term="blockchain/chain">цепочки блоков</span>, механизма консенсуса и сетевых узлов.</li>
                    <li><strong>Безопасность кошелька</strong> — защита приватных ключей, seed-фразы и устройства, на котором выполняется <span class="term" data-term="crypto-wallets/transaction-signing">подписание транзакций</span>.</li>
                    <li><strong>Безопасность аккаунта</strong> — защита учетных данных с помощью аутентификации и дополнительных факторов.</li>
                    <li><strong>Безопасность приложений</strong> — поиск уязвимостей в dApp, биржах и смарт-контрактах.</li>
                </ul>

                <p>К распространенным угрозам относятся <span class="term" data-term="security/phishing">фишинг</span>, <span class="term" data-term="security/social-engineering">социальная инженерия</span>, атаки перебора, кража ключей, вредоносное ПО и атаки на блокчейн-консенсус, включая <span class="term" data-term="security/51-percent-attack">атаку 51%</span> и <span class="term" data-term="security/sybil-attack">Sybil-атаки</span>.</p>

                <p>Таким образом, безопасность криптовалют — это не одна технология, а многоуровневая система защиты, в которой безопасность протокола, программного обеспечения, инфраструктуры и действий пользователя взаимосвязаны.</p>'
            ],

            '51-percent-attack' => [
                'title' => 'Что такое атака 51% | TM Wiki',
                'description' => 'Атака 51% — получение контроля над большей частью консенсусного ресурса блокчейна с возможностью влиять на порядок транзакций.',
                'name' => 'Атака 51%',
                'caption' => 'Контроль большинства вычислительной или стейковой силы сети',
                'definition' => '<p><strong>Атака 51%</strong> — это ситуация, при которой один участник или координированная группа получает контроль над большинством ресурса, определяющего <span class="term" data-term="blockchain/consensus">консенсус</span> в блокчейне. В сетях <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> таким ресурсом обычно является вычислительная мощность, а в <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span> аналогичная угроза рассматривается через контроль значительной доли <span class="term" data-term="staking/staking">стейка</span>, хотя конкретная модель атаки зависит от протокола.</p>

                <p>Контроль большинства не означает автоматического полного контроля над сетью. Злоумышленник обычно не может произвольно создавать монеты, менять чужие подписи или изменять уже надежно финализированные данные. Основная угроза заключается в возможности влиять на выбор и порядок новых <span class="term" data-term="blockchain/block">блоков</span> и конкурировать с честной цепочкой.</p>

                <h3>Что может сделать атакующий</h3>

                <ul>
                    <li>организовать <span class="term" data-term="security/double-spending">двойную трату</span> собственных средств при определенных условиях;</li>
                    <li>цензурировать или задерживать отдельные транзакции;</li>
                    <li>влиять на порядок включения транзакций;</li>
                    <li>создавать конкурирующую цепочку и проводить реорганизации, если протокол это допускает.</li>
                </ul>

                <p>Наиболее известный сценарий связан с двойной тратой. Атакующий совершает платеж в одной цепочке, а затем использует контролируемый ресурс для построения альтернативной истории, в которой эта транзакция отсутствует. Если альтернативная цепочка становится предпочтительной согласно правилам консенсуса, получатель первоначального платежа может потерять основание считать его окончательным.</p>

                <p>Защита зависит от архитектуры сети. В PoW важны распределенность <span class="term" data-term="mining/hashrate">хешрейта</span> и стоимость получения значительной вычислительной мощности. В PoS большое значение имеют экономическая стоимость контроля стейка, <span class="term" data-term="staking/slashing">slashing</span>, финальность и другие механизмы протокола.</p>

                <p>Риск атаки 51% особенно важен для небольших сетей, где получение значительной доли консенсусного ресурса может быть экономически доступнее. Поэтому децентрализация и распределение ресурсов между независимыми участниками являются важными элементами безопасности блокчейна.</p>'
            ],

            'double-spending' => [
                'title' => 'Что такое двойная трата | TM Wiki',
                'description' => 'Двойная трата — попытка использовать одни и те же криптовалютные средства более одного раза в разных транзакциях.',
                'name' => 'Двойная трата',
                'caption' => 'Повторное использование одних и тех же средств',
                'definition' => '<p><strong>Двойная трата</strong> — это попытка потратить одни и те же единицы криптовалюты более одного раза. Проблема возникает из-за цифровой природы активов: в отличие от физической монеты, цифровую информацию можно скопировать, поэтому блокчейну необходимо определить, какая из конфликтующих <span class="term" data-term="blockchain/transaction">транзакций</span> считается действительной.</p>

                <p>Для предотвращения двойной траты блокчейн использует <span class="term" data-term="blockchain/consensus">консенсус</span>. Узлы сети проверяют, существуют ли доступные средства, и принимают транзакции в соответствии с правилами протокола. После включения транзакции в <span class="term" data-term="blockchain/block">блок</span> и получения достаточного количества подтверждений вероятность успешной альтернативной истории обычно уменьшается.</p>

                <h3>Как возникает двойная трата</h3>

                <p>Атакующий может попытаться одновременно отправить одну сумму двум получателям или создать альтернативную историю блокчейна после совершения платежа. В обычной сети конфликтующие транзакции не могут одновременно расходовать один и тот же ресурс: одна из них должна быть отклонена или стать неактуальной.</p>

                <p>Наиболее серьезный сценарий связан с <span class="term" data-term="security/51-percent-attack">атакой 51%</span>, когда злоумышленник получает значительный контроль над процессом формирования цепочки. В зависимости от механизма консенсуса возможны и другие сценарии, например атаки на сетевое окружение или эксплуатация особенностей финальности.</p>

                <p>Двойная трата отличается от обычной ошибки пользователя. Если пользователь случайно отправил средства не на тот <span class="term" data-term="crypto-wallets/wallet-address">адрес кошелька</span>, это не является double-spending: речь идет о корректной транзакции, которую пользователь хотел бы отменить. Двойная трата подразумевает именно попытку получить признание нескольких расходований одного и того же баланса.</p>

                <p>Механизмы предотвращения двойной траты являются одной из фундаментальных задач блокчейна. Именно поэтому безопасность <span class="term" data-term="blockchain/consensus-mechanism">механизма консенсуса</span>, распределение участников и правила финальности непосредственно влияют на надежность цифрового актива.</p>'
            ],

            'sybil-attack' => [
                'title' => 'Что такое Sybil-атака | TM Wiki',
                'description' => 'Sybil-атака — создание множества ложных идентичностей или узлов для получения непропорционального влияния на распределенную сеть.',
                'name' => 'Sybil-атака',
                'caption' => 'Массовое создание псевдоучастников сети',
                'definition' => '<p><strong>Sybil-атака</strong> — это атака, при которой злоумышленник создает множество псевдоучастников, идентификаторов или сетевых узлов, чтобы получить большее влияние на распределенную систему, чем ему полагается как одному реальному участнику.</p>

                <p>Проблема возникает потому, что в распределенной сети сам факт существования большого количества сетевых идентификаторов не означает наличие большого количества независимых владельцев. Один оператор может контролировать десятки или тысячи узлов. Поэтому блокчейны должны использовать механизм, связывающий влияние участника с экономическим или вычислительным ресурсом.</p>

                <p>В <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> защитой служит необходимость расходовать вычислительные ресурсы для производства блоков. В <span class="term" data-term="staking/proof-of-stake">Proof-of-Stake</span> влияние связано со <span class="term" data-term="staking/staking">стейком</span>. Простое создание большого количества аккаунтов не дает злоумышленнику пропорционального веса, если для влияния требуется соответствующий экономический ресурс.</p>

                <h3>Почему Sybil-атака опасна</h3>

                <p>Sybil-атака может использоваться для манипуляции распределенными системами, голосованием, сетевыми соединениями и механизмами распространения данных. В блокчейне ее последствия зависят от архитектуры сети и от того, каким образом протокол определяет вес участника.</p>

                <p>Sybil-атака сама по себе не обязательно означает получение контроля над блокчейном. Если влияние определяется <span class="term" data-term="mining/hashrate">хешрейтом</span> или стейком, тысячи дешевых идентичностей без соответствующего ресурса могут почти ничего не изменить. Однако Sybil-атаки могут усиливать другие виды атак, особенно на сетевом уровне.</p>

                <p>Поэтому защита от Sybil-атак является важной частью проектирования <span class="term" data-term="blockchain/consensus-mechanism">механизма консенсуса</span> и сетевой инфраструктуры.</p>'
            ],

            'eclipse-attack' => [
                'title' => 'Что такое Eclipse-атака | TM Wiki',
                'description' => 'Eclipse-атака изолирует блокчейн-узел от честных участников сети, подменяя его сетевое окружение контролируемыми соединениями.',
                'name' => 'Eclipse-атака',
                'caption' => 'Изоляция узла от честной части сети',
                'definition' => '<p><strong>Eclipse-атака</strong> — это атака на сетевой уровень блокчейна, при которой злоумышленник старается окружить конкретный <span class="term" data-term="blockchain/blockchain-node">узел</span> соединениями, контролируемыми атакующим. В результате жертва может перестать получать достоверную информацию от остальной сети.</p>

                <p>Блокчейн-узел зависит от сетевых подключений для получения блоков, транзакций и другой информации. Если все или большая часть его доступных соединений контролируется одним атакующим, узел может видеть альтернативное представление состояния сети.</p>

                <p>Eclipse-атака особенно опасна как вспомогательный механизм. Само по себе изолирование узла не дает злоумышленнику полного контроля над блокчейном, но может упростить проведение других атак. Например, атакующий может скрывать от жертвы определенные <span class="term" data-term="blockchain/transaction">транзакции</span> или блоки и создавать условия для ошибочных решений.</p>

                <h3>Защита</h3>

                <ul>
                    <li>поддержание большого и разнообразного набора сетевых соединений;</li>
                    <li>ограничение зависимости от одного источника адресов;</li>
                    <li>случайный выбор и периодическая смена peers;</li>
                    <li>проверка получаемой информации через независимые соединения.</li>
                </ul>

                <p>Eclipse-атака показывает, что безопасность блокчейна зависит не только от криптографии и <span class="term" data-term="blockchain/consensus">консенсуса</span>. Надежная сетевая инфраструктура также является частью общей модели безопасности.</p>'
            ],

            'replay-attack' => [
                'title' => 'Что такое Replay-атака | TM Wiki',
                'description' => 'Replay-атака — повторное использование ранее действительной подписанной транзакции или сообщения в другом контексте.',
                'name' => 'Replay-атака',
                'caption' => 'Повторное воспроизведение действительных данных',
                'definition' => '<p><strong>Replay-атака</strong> — это атака, при которой злоумышленник повторно использует ранее перехваченное и действительное сообщение, подпись или <span class="term" data-term="blockchain/transaction">транзакцию</span>, чтобы добиться повторного выполнения операции.</p>

                <p>Цифровая подпись доказывает, что определенный набор данных был подписан соответствующим ключом, но сама по себе подпись не всегда гарантирует, что сообщение может быть использовано только один раз. Для защиты протокол должен учитывать контекст, уникальность операции и состояние сети.</p>

                <p>В блокчейнах защита от replay-атак может использовать <span class="term" data-term="blockchain/transaction-input">входы транзакции</span>, nonce, идентификатор сети, уникальный идентификатор цепочки или другие параметры. Такие данные позволяют отличать новую операцию от уже использованной.</p>

                <p>Особенно известны replay-риски при разделении одной сети на две цепочки после <span class="term" data-term="blockchain/hard-fork">hard форк</span>. Если правила подписи и идентификации транзакций в двух цепочках недостаточно различаются, транзакция, действительная в одной сети, потенциально может быть воспроизведена в другой.</p>

                <p>Защита от replay-атак является частью проектирования транзакционного формата, <span class="term" data-term="security/digital-signature">цифровых подписей</span> и правил конкретного блокчейна.</p>'
            ],

            'man-in-the-middle' => [
                'title' => 'Что такое Man-in-the-Middle | TM Wiki',
                'description' => 'Man-in-the-Middle — атака, при которой злоумышленник перехватывает или изменяет коммуникацию между двумя участниками.',
                'name' => 'Man-in-the-Middle',
                'caption' => 'Перехват и изменение коммуникации',
                'definition' => '<p><strong>Man-in-the-Middle (MitM)</strong> — атака, при которой злоумышленник занимает промежуточное положение между двумя сторонами коммуникации и пытается читать, изменять или подменять передаваемые данные.</p>

                <p>В криптовалютной инфраструктуре MitM-атака может быть направлена на веб-интерфейс биржи, соединение кошелька с приложением, сетевое подключение к серверу или коммуникацию между компонентами инфраструктуры. Целью может быть кража учетных данных, изменение адреса назначения или подмена передаваемой информации.</p>

                <p>Одним из важных средств защиты является <span class="term" data-term="security/encryption">шифрование</span> канала связи с корректной проверкой подлинности удаленной стороны. Однако само наличие шифрования не гарантирует защиту, если пользователь принимает поддельный сертификат, устанавливает вредоносное программное обеспечение или игнорирует предупреждения браузера.</p>

                <p>В криптовалютных операциях особенно опасна подмена <span class="term" data-term="crypto-wallets/wallet-address">адреса кошелька</span> перед подписанием транзакции. Поэтому критически важные данные рекомендуется проверять непосредственно на доверенном устройстве и, где возможно, на экране аппаратного кошелька.</p>

                <p>MitM-атака отличается от <span class="term" data-term="security/phishing">фишинга</span>: при фишинге пользователя часто убеждают самостоятельно передать данные атакующему, тогда как при MitM злоумышленник стремится вмешаться в коммуникационный канал.</p>'
            ],

            'phishing' => [
                'title' => 'Что такое фишинг в криптовалюте | TM Wiki',
                'description' => 'Фишинг — обман пользователя с целью получить приватные данные, seed-фразу, пароли, коды или доступ к криптоактивам.',
                'name' => 'Фишинг',
                'caption' => 'Поддельные сайты и сообщения для кражи данных',
                'definition' => '<p><strong>Фишинг</strong> — это вид атаки, при котором злоумышленник создает ложное ощущение доверия, чтобы заставить пользователя раскрыть секретную информацию или выполнить опасное действие. В криптовалюте целью часто становятся <span class="term" data-term="crypto-wallets/seed-phrase">seed-фразы</span>, <span class="term" data-term="crypto-wallets/private-key">приватные ключи</span>, пароли и коды подтверждения.</p>

                <p>Фишинговая атака может использовать поддельный сайт биржи, копию интерфейса кошелька, электронное письмо, сообщение в мессенджере, рекламу или ссылку в социальной сети. Внешне такой ресурс может почти полностью повторять настоящий сервис.</p>

                <h3>Распространенные признаки</h3>

                <ul>
                    <li>неожиданное требование срочно подтвердить аккаунт;</li>
                    <li>ссылка на домен, похожий на настоящий, но отличающийся одной или несколькими деталями;</li>
                    <li>просьба ввести seed-фразу или приватный ключ;</li>
                    <li>обещание бесплатных токенов или высокой доходности в обмен на подключение кошелька;</li>
                    <li>давление на пользователя через угрозы блокировки или ограничение доступа.</li>
                </ul>

                <p>Особенно важно понимать, что легитимный криптосервис не должен требовать от пользователя раскрытия приватного ключа или seed-фразы для обычного входа в кошелек. Эти данные предназначены для контроля над активами и должны храниться в соответствии с принципами <span class="term" data-term="security/private-key-security">безопасности приватного ключа</span> и <span class="term" data-term="security/seed-phrase-security">защиты seed-фразы</span>.</p>

                <p>Фишинг часто комбинируется с <span class="term" data-term="security/social-engineering">социальной инженерией</span>. Поэтому технические средства защиты аккаунта необходимо дополнять внимательной проверкой источника информации и адреса сайта.</p>'
            ],

            'social-engineering' => [
                'title' => 'Что такое социальная инженерия | TM Wiki',
                'description' => 'Социальная инженерия — манипулирование человеком для получения доступа к аккаунту, ключам, средствам или конфиденциальной информации.',
                'name' => 'Социальная инженерия',
                'caption' => 'Манипуляция пользователем вместо взлома системы',
                'definition' => '<p><strong>Социальная инженерия</strong> — это набор методов, при которых злоумышленник использует психологические и социальные приемы, чтобы заставить человека раскрыть информацию, предоставить доступ или выполнить небезопасное действие.</p>

                <p>В криптовалютной среде социальная инженерия особенно опасна потому, что многие операции невозможно отменить. Если пользователь добровольно передал <span class="term" data-term="crypto-wallets/private-key">приватный ключ</span> или <span class="term" data-term="crypto-wallets/seed-phrase">seed-фразу</span>, технические средства блокчейна обычно не позволяют вернуть контроль над кошельком.</p>

                <p>Атакующий может выдавать себя за сотрудника биржи, разработчика, модератора сообщества, техническую поддержку или знакомого. Он может создавать искусственную срочность, обещать компенсацию, угрожать блокировкой аккаунта или сообщать о якобы подозрительной активности.</p>

                <h3>Типичные сценарии</h3>

                <ul>
                    <li>ложная техническая поддержка;</li>
                    <li>поддельные сообщения от администрации проекта;</li>
                    <li>предложения получить токены или инвестиционную возможность;</li>
                    <li>запрос секретного кода или seed-фразы под видом проверки;</li>
                    <li>убеждение пользователя установить удаленное программное обеспечение.</li>
                </ul>

                <p>Защита основана прежде всего на процедуре проверки. Нельзя считать личность собеседника подтвержденной только на основании имени, фотографии или сообщения в официально выглядящем аккаунте. Критические действия следует подтверждать через независимый канал.</p>

                <p>Социальная инженерия тесно связана с <span class="term" data-term="security/phishing">фишингом</span>, но понятие шире: фишинг является конкретным способом обмана, тогда как социальная инженерия включает широкий набор методов воздействия на человека.</p>'
            ],

            'private-key-security' => [
                'title' => 'Как защитить приватный ключ | TM Wiki',
                'description' => 'Безопасность приватного ключа определяет контроль над криптоактивами и требует защиты от кражи, копирования и раскрытия.',
                'name' => 'Безопасность приватного ключа',
                'caption' => 'Защита ключа, который контролирует криптоактивы',
                'definition' => '<p><strong>Безопасность приватного ключа</strong> — совокупность мер по защите секретного криптографического ключа, с помощью которого владелец получает право управлять криптоактивами и создавать <span class="term" data-term="security/digital-signature">цифровые подписи</span>.</p>

                <p>Приватный ключ не является паролем в обычном смысле. Он является криптографическим секретом, связанным с соответствующим <span class="term" data-term="crypto-wallets/public-key">публичным ключом</span>. В большинстве блокчейнов транзакция считается авторизованной, если ее подпись корректно проверяется соответствующим публичным ключом.</p>

                <p>Главный принцип безопасности заключается в том, что приватный ключ нельзя передавать третьим лицам. Если злоумышленник получает копию ключа, он может создать действительную подпись и, в зависимости от протокола, вывести активы без дополнительного разрешения владельца.</p>

                <h3>Основные меры защиты</h3>

                <ul>
                    <li>хранение ключа в доверенной среде;</li>
                    <li>использование <span class="term" data-term="crypto-wallets/hardware-wallet">аппаратного кошелька</span> для значительных сумм;</li>
                    <li>отсутствие копий ключа в открытом виде в облачных сервисах и переписке;</li>
                    <li>защита резервных копий от физического доступа посторонних;</li>
                    <li>проверка адреса и деталей операции перед подписанием.</li>
                </ul>

                <p>Потеря приватного ключа и его компрометация — разные события. В первом случае владелец может потерять возможность подписывать операции. Во втором случае доступ может получить злоумышленник. Поэтому резервное копирование кошелька и защита от раскрытия должны рассматриваться одновременно.</p>

                <p>Безопасность приватного ключа является основой модели <span class="term" data-term="crypto-wallets/self-custody">самостоятельного хранения</span> и непосредственно связана с безопасностью seed-фразы, если ключи кошелька получаются из нее через <span class="term" data-term="crypto-wallets/derivation-path">derivation path</span>.</p>'
            ],

            'seed-phrase-security' => [
                'title' => 'Как защитить seed-фразу | TM Wiki',
                'description' => 'Безопасность seed-фразы — защита главного секрета кошелька, из которого могут восстанавливаться приватные ключи и доступ к активам.',
                'name' => 'Безопасность seed-фразы',
                'caption' => 'Защита главного секрета криптовалютного кошелька',
                'definition' => '<p><strong>Безопасность seed-фразы</strong> — совокупность мер, направленных на защиту мнемонической фразы, используемой для восстановления криптовалютного кошелька и связанных с ним ключей.</p>

                <p>Seed-фраза, также называемая <span class="term" data-term="crypto-wallets/mnemonic-phrase">мнемонической фразой</span>, представляет собой последовательность слов, из которой кошелек может восстановить криптографическое состояние. В зависимости от стандарта и реализации она может давать доступ к множеству <span class="term" data-term="crypto-wallets/private-key">приватных ключей</span> и адресов.</p>

                <p>Поэтому seed-фраза фактически является резервным корнем доступа к кошельку. Ее компрометация может быть опаснее потери одного отдельного приватного ключа: одна фраза потенциально дает возможность восстановить целое дерево ключей.</p>

                <h3>Правила хранения</h3>

                <ul>
                    <li>не хранить seed-фразу в переписке, электронной почте или публичном облаке;</li>
                    <li>не вводить ее на случайных сайтах и в неизвестных приложениях;</li>
                    <li>не передавать ее службе поддержки или другому человеку;</li>
                    <li>создавать физическую резервную копию и защищать ее от повреждения и кражи;</li>
                    <li>проверять порядок слов и дополнительные параметры восстановления.</li>
                </ul>

                <p>Важно различать seed-фразу и пароль кошелька. Пароль может защищать приложение на конкретном устройстве, тогда как seed-фраза обычно позволяет восстановить ключи на другом совместимом устройстве.</p>

                <p>Seed-фраза должна рассматриваться как секрет, сопоставимый по значимости с набором приватных ключей. Любое неожиданное требование ввести ее является серьезным сигналом риска, особенно если оно связано с <span class="term" data-term="security/phishing">фишингом</span> или <span class="term" data-term="security/social-engineering">социальной инженерией</span>.</p>'
            ],

            'encryption' => [
                'title' => 'Что такое шифрование | TM Wiki',
                'description' => 'Шифрование преобразует данные в форму, недоступную без соответствующего ключа, и используется для защиты конфиденциальной информации.',
                'name' => 'Шифрование',
                'caption' => 'Защита данных от несанкционированного чтения',
                'definition' => '<p><strong>Шифрование</strong> — преобразование исходных данных в зашифрованную форму с использованием алгоритма и ключа таким образом, чтобы прочитать исходную информацию без соответствующего ключа было невозможно или практически неосуществимо.</p>

                <p>Шифрование применяется для защиты данных при передаче и хранении. В криптовалютной инфраструктуре оно может использоваться для защищенного сетевого соединения, хранения резервных копий, защиты файлов кошелька и других конфиденциальных данных.</p>

                <p>Важно отличать шифрование от <span class="term" data-term="security/hash-function">хеширования</span>. Шифрование предназначено для обратимого преобразования при наличии ключа, тогда как криптографический хеш обычно является односторонним преобразованием фиксированного размера.</p>

                <h3>Основные виды</h3>

                <ul>
                    <li><strong>Симметричное шифрование</strong> использует один секретный ключ для шифрования и расшифровки.</li>
                    <li><strong>Асимметрическая криптография</strong> использует пару ключей и применяется, среди прочего, в цифровых подписях и протоколах защищенной связи.</li>
                </ul>

                <p>Шифрование не гарантирует безопасность само по себе. Если ключ украден, злоумышленник может расшифровать защищенные данные. Поэтому управление ключами является не менее важной частью системы, чем сам алгоритм шифрования.</p>

                <p>Для криптовалют особенно важно не путать шифрование с защитой блокчейн-транзакций. Публичные данные блокчейна обычно не скрываются шифрованием: их целостность и авторство обеспечиваются другими криптографическими механизмами, включая <span class="term" data-term="security/digital-signature">цифровые подписи</span> и <span class="term" data-term="security/cryptographic-hash">криптографические хеши</span>.</p>'
            ],

            'hash-function' => [
                'title' => 'Что такое хеш-функция | TM Wiki',
                'description' => 'Хеш-функция преобразует произвольные данные в строку фиксированного размера и используется в блокчейнах и криптографии.',
                'name' => 'Хеш-функция',
                'caption' => 'Преобразование данных в фиксированный цифровой отпечаток',
                'definition' => '<p><strong>Хеш-функция</strong> — математическая функция, которая преобразует входные данные произвольной длины в выход фиксированного размера, называемый хешем или дайджестом.</p>

                <p>Для криптографических применений важны свойства, затрудняющие поиск исходных данных по хешу, поиск двух разных входов с одинаковым результатом и подбор входа с заранее заданным хешем. Конкретные свойства зависят от используемого алгоритма.</p>

                <p>Хеш-функции широко используются в <span class="term" data-term="blockchain/blockchain">блокчейнах</span>. Они участвуют в формировании идентификаторов блоков, связывании блоков между собой, проверке данных и различных механизмах консенсуса. В <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> вычисление хешей является основой процесса поиска подходящего решения.</p>

                <p>Важно различать обычные хеш-функции и <span class="term" data-term="security/cryptographic-hash">криптографические хеш-функции</span>. Не каждая хеш-функция обладает свойствами, необходимыми для защиты от злоумышленника.</p>

                <h3>Ключевые свойства криптографического хеша</h3>

                <ul>
                    <li>детерминированность результата;</li>
                    <li>быстрое вычисление для допустимого входа;</li>
                    <li>сложность восстановления исходных данных;</li>
                    <li>сложность поиска коллизий;</li>
                    <li>сильная чувствительность результата к изменению входных данных.</li>
                </ul>

                <p>Даже небольшое изменение исходных данных обычно приводит к полностью другому хешу. Это позволяет использовать хеши как цифровые отпечатки данных и связывать элементы <span class="term" data-term="blockchain/chain">цепочки блоков</span>.</p>'
            ],

            'cryptographic-hash' => [
                'title' => 'Что такое криптографический хеш | TM Wiki',
                'description' => 'Криптографический хеш — односторонний цифровой отпечаток данных, предназначенный для проверки целостности и защиты криптографических систем.',
                'name' => 'Криптографический хеш',
                'caption' => 'Цифровой отпечаток данных для криптографии',
                'definition' => '<p><strong>Криптографический хеш</strong> — результат применения криптографической <span class="term" data-term="security/hash-function">хеш-функции</span> к набору данных. Он представляет вход в виде строки фиксированного размера и используется для проверки целостности, построения структур данных и различных криптографических механизмов.</p>

                <p>Хорошая криптографическая хеш-функция должна делать практически невозможным восстановление подходящего исходного сообщения только по его хешу. Также должно быть вычислительно сложно найти два разных входа с одинаковым хешем, то есть коллизию.</p>

                <p>В блокчейнах хеши используются повсеместно. Например, хеш предыдущего блока может включаться в <span class="term" data-term="blockchain/block-header">заголовок следующего блока</span>, создавая криптографическую связь между элементами цепочки. Изменение старых данных меняет соответствующий хеш и нарушает эту связь.</p>

                <p>В <span class="term" data-term="mining/proof-of-work">Proof-of-Work</span> криптографические хеши используются для поиска значений, удовлетворяющих определенному условию сложности. Именно это создает вычислительную стоимость производства блоков.</p>

                <p>Криптографический хеш также используется совместно с <span class="term" data-term="security/digital-signature">цифровыми подписями</span>. Обычно подписывается не весь большой объем данных непосредственно, а его криптографическое представление, что делает операции эффективнее.</p>'
