            'digital-signature' => [
                'title' => 'Что такое цифровая подпись | TM Wiki',
                'description' => 'Цифровая подпись подтверждает владение приватным ключом и позволяет проверить авторство и целостность подписанных данных.',
                'name' => 'Цифровая подпись',
                'caption' => 'Криптографическое подтверждение авторства операции',
                'definition' => '<p><strong>Цифровая подпись</strong> — криптографический механизм, позволяющий доказать, что определенные данные были подписаны владельцем соответствующего <span class="term" data-term="crypto-wallets/private-key">приватного ключа</span>, а также проверить, что подписанные данные не были изменены.</p>

                <p>В типичной схеме используется пара ключей: приватный ключ остается секретным, а <span class="term" data-term="crypto-wallets/public-key">публичный ключ</span> доступен для проверки. Подписывающая сторона создает подпись с использованием приватного ключа, после чего другие участники могут проверить ее с помощью публичного ключа.</p>

                <p>В блокчейнах цифровые подписи являются основой авторизации многих <span class="term" data-term="blockchain/transaction">транзакций</span>. Кошелек формирует сообщение транзакции, подписывает его, а сеть проверяет подпись перед включением операции в блок.</p>

                <p>Подпись не скрывает содержимое транзакции. Конфиденциальность и целостность — разные задачи. Цифровая подпись подтверждает авторство и защищает от незаметного изменения подписанных данных, но не делает их автоматически секретными.</p>

                <h3>Безопасность подписи</h3>

                <p>Безопасность цифровой подписи зависит от надежности алгоритма, правильности реализации и защиты приватного ключа. Если злоумышленник получает приватный ключ, он может создавать подписи, которые сеть будет воспринимать как корректные.</p>

                <p>Поэтому цифровая подпись тесно связана с <span class="term" data-term="security/private-key-security">безопасностью приватного ключа</span>, аппаратными кошельками и <span class="term" data-term="crypto-wallets/transaction-signing">подписанием транзакций</span>.</p>'
            ],

            'zero-knowledge-proof' => [
                'title' => 'Что такое Zero-Knowledge Proof | TM Wiki',
                'description' => 'Zero-Knowledge Proof позволяет доказать истинность утверждения без раскрытия самого секрета или всей подтверждаемой информации.',
                'name' => 'Zero-Knowledge Proof',
                'caption' => 'Доказательство знания без раскрытия секрета',
                'definition' => '<p><strong>Zero-Knowledge Proof (ZKP)</strong> — криптографический метод, позволяющий одной стороне доказать другой стороне истинность определенного утверждения, не раскрывая сам секрет, на котором основано это утверждение.</p>

                <p>В упрощенном виде существуют доказывающий и проверяющий. Доказывающий обладает некоторым секретом или удовлетворяет определенному условию и создает доказательство. Проверяющий может убедиться в корректности доказательства, не получая сам секрет.</p>

                <p>В блокчейнах ZKP применяются для масштабирования, повышения приватности и проверки вычислений. Например, доказательство может подтверждать выполнение определенных условий без публикации всех исходных данных.</p>

                <h3>Пример применения</h3>

                <p>Представим систему, которой необходимо убедиться, что пользователь обладает определенным правом или удовлетворяет условию. Вместо передачи самого секрета можно предоставить доказательство, позволяющее проверить утверждение без раскрытия исходной информации.</p>

                <p>ZKP отличаются от обычного <span class="term" data-term="security/encryption">шифрования</span>. Шифрование защищает данные от чтения без ключа, а zero-knowledge proof позволяет доказать определенное утверждение, не раскрывая соответствующий секрет.</p>

                <p>Практические реализации ZKP могут иметь сложные требования к вычислениям, размеру доказательств, настройке системы и криптографическим предположениям. Поэтому конкретные свойства зависят от используемого протокола.</p>

                <p>Zero-Knowledge Proof является важным инструментом современной криптографии и используется в ряде блокчейн-проектов для построения приватных и масштабируемых систем.</p>'
            ],

            'cryptojacking' => [
