                <p>Для защиты применяются обновления программного обеспечения, антивирусная защита, ограничение прав приложений, контроль процессов и мониторинг инфраструктуры. В дата-центрах и крупных системах полезно отслеживать аномалии <span class="term" data-term="equipment-specifications/power-consumption">энергопотребления</span> и нагрузки.</p>

                <p>Cryptojacking отличается от обычного майнинга тем, что экономическая выгода от вычислений получает не владелец оборудования, а атакующий.</p>'
