                'definition' => '<p><strong>Аудит смарт-контракта</strong> — систематическая проверка исходного кода <span class="term" data-term="blockchain/smart-contract">смарт-контракта</span> с целью обнаружить уязвимости, ошибки логики, неправильное управление доступом и другие проблемы, которые могут привести к потере средств или нарушению работы протокола.</p>

                <p>Аудит особенно важен для контрактов, управляющих большими объемами активов. Это относится к <span class="term" data-term="defi/liquidity-pool">пулу ликвидности</span>, кредитным протоколам, мостам, стейкинговым системам и другим приложениям <span class="term" data-term="defi/defi">DeFi</span>.</p>

