                </ul>

                <p>Аудит может включать ручной анализ кода, автоматические инструменты статического анализа, тестирование и моделирование потенциальных атак. Автоматические инструменты полезны, но не гарантируют обнаружение всех логических и экономических уязвимостей.</p>

                <p>Наличие опубликованного аудита не означает, что смарт-контракт абсолютно безопасен. После аудита код может измениться, могут появиться новые методы атак или уязвимость может находиться за пределами области проверки.</p>

                <p>Поэтому пользователю <span class="term" data-term="defi/decentralized-finance">децентрализованного финансового</span> приложения важно учитывать не только наличие аудита, но и его область, дату, проверенную версию кода, ограничения отчета и последующие изменения протокола.</p>'
